(function(){if(typeof L5R4E==="undefined")return;
const X={"clans": [{"id": "naga", "nome": "Naga"}, {"id": "nezumi", "nome": "Nezumi"}, {"id": "kenku", "nome": "Kenku"}, {"id": "tsuno", "nome": "Tsuno"}, {"id": "ogre", "nome": "Free Ogres"}, {"id": "kolat", "nome": "Kolat"}, {"id": "shadowlands", "nome": "Shadowlands (Lost)"}], "escolas": [{"id": "x_dark_moto", "nome": "Dark Moto", "clanId": "shadowlands", "livro": "Enemies of the Empire", "pagina": "63", "traco": "strength", "honra": "0.0", "tags": ["bushi", "shadowlands_bushi", "maho"], "pericias": [{"id": "defense", "rank": 1, "enfase": ""}, {"id": "horsemanship", "rank": 1, "enfase": ""}, {"id": "kenjutsu", "rank": 1, "enfase": ""}, {"id": "kyujutsu", "rank": 1, "enfase": ""}, {"id": "lore_shadowlands", "rank": 1, "enfase": ""}, {"id": "polearms", "rank": 1, "enfase": ""}, {"id": "spears", "rank": 1, "enfase": ""}], "periciasTexto": "Defense, Horsemanship, Kenjutsu, Kyujutsu, Lore: Shadowlands, Polearms, Spears, any one Bugei or Low Skill", "beneficio": "+1 Strength", "tecnicas": [{"id": "x_dark_moto_power_in_the_darkness", "nome": "Power in the Darkness", "rank": 1, "descricao": "The embrace of the Taint grants the Dark Moto strength beyond that of mortals. Your maximum Raises are now limited by your Taint Rank or your Void, whichever is higher. You add your Taint Rank in unkept dice to all attack rolls. However, you no longer gain any benefit from the Full Defense stance."}, {"id": "x_dark_moto_ride_beyond_death", "nome": "Ride Beyond Death", "rank": 2, "descricao": "Not even death can break the connection between a Unicorn and his steed. The Dark Moto are bonded to onikage, the monstrous creatures created from horses that fall to the Taint. You may mentally summon an onikage as a Simple Action. The creature will appear at the start of the next Round, bursting forth from the ground."}, {"id": "x_dark_moto_dark_lords_fury", "nome": "Dark Lord’s Fury", "rank": 3, "descricao": "The rage of Jigoku courses through the Dark Moto’s body, driving him to inhuman speed and fury. You may make attacks as a Simple Action instead of a Complex Action."}, {"id": "x_dark_moto_visage_of_the_damned", "nome": "Visage of the Damned", "rank": 4, "descricao": "The Dark Moto radiate a powerful aura of terror and malignance, and can intensify this power to the point where it will cripple their foes. Once per skirmish as a Simple Action you may create a Fear effect equal to your Taint Rank against all those who gaze upon you. Any opponent who succumbs to the Fear is, in addition to the normal penalties, limited to one Simple Action (and no Complex Actions) on their next Turn. They may take Free Actions as normal."}, {"id": "x_dark_moto_death_is_an_illusion", "nome": "Death Is an Illusion", "rank": 5, "descricao": "The corrupted forms of the Dark Moto are nearly impervious to injury, and they can continue to fight until they are deThe Lost stroyed. You no longer suffer any Wound penalties, not even at the Down or Out Ranks, and you heal Wounds equal to your Taint Rank during the Reactions Stage of each Round."}]}, {"id": "x_naga_jakla", "nome": "Naga Jakla", "clanId": "naga", "livro": "Enemies of the Empire", "pagina": "84", "traco": "intelligence", "honra": "5.5", "tags": ["shugenja", "naga_shugenja", "nonhuman"], "pericias": [{"id": "athletics", "rank": 1, "enfase": ""}, {"id": "kyujutsu", "rank": 1, "enfase": ""}, {"id": "lore_shadowlands", "rank": 1, "enfase": ""}, {"id": "medicine", "rank": 1, "enfase": ""}, {"id": "meditation", "rank": 1, "enfase": "Akasha Recovery"}, {"id": "spellcraft", "rank": 1, "enfase": ""}], "periciasTexto": "Athletics, Kyujutsu, Lore: Shadowlands, Medicine, Meditation (Akasha Recovery), Spellcraft, any one High Skill", "beneficio": "+1 Intelligence", "tecnicas": [{"id": "x_naga_jakla_shining_heart", "nome": "Shining Heart", "rank": 1, "descricao": "The jakla learns to hone his focus until he can tap into the magical powers that lie within his pearls. Every day, you may The Naga cast two of your spells without expending spell slots. You gain one Free Raise on spells cast in this manner."}], "afinidade": "Water/Fire"}, {"id": "x_naga_scout", "nome": "Naga Scout", "clanId": "naga", "livro": "Enemies of the Empire", "pagina": "84", "traco": "perception", "honra": "4.5", "tags": ["bushi", "naga_bushi", "nonhuman"], "pericias": [{"id": "athletics", "rank": 1, "enfase": ""}, {"id": "hunting", "rank": 1, "enfase": "Tracking"}, {"id": "investigation", "rank": 1, "enfase": ""}, {"id": "kyujutsu", "rank": 1, "enfase": ""}, {"id": "lore_shadowlands", "rank": 1, "enfase": ""}, {"id": "stealth", "rank": 1, "enfase": ""}], "periciasTexto": "Athletics, Hunting (Tracking), Investigation, Kyujutsu, Lore: Shadowlands, Stealth, any one Bugei Skill", "beneficio": "+1 Perception", "tecnicas": [{"id": "x_naga_scout_the_silent_stalker", "nome": "The Silent Stalker", "rank": 1, "descricao": "The Scout is at home within the forest, as comfortable as the animals that reside within. You add +1k0 to all School Skills while inside a forest. Additionally, you may ignore any penalties for wearing light armor."}, {"id": "x_naga_scout_the_great_enemy", "nome": "The Great Enemy", "rank": 2, "descricao": "The Scout can sense the foul presence of the Shadowlands Taint nearby. You may make an Awareness roll at TN 20 to discern any creature of the Shadowlands or the Nothing with84 in 50’. This TN may be higher if the creature has abilities that obfuscate attempts to find it. This Technique cannot discern any creatures with less than one full Rank in their corruption."}, {"id": "x_naga_scout_eyes_of_an_eagle", "nome": "Eyes of an Eagle", "rank": 3, "descricao": "The Scout learns to spot the minutest details, able to spot even the remnants of a trail in the dead of night. You may spend an Akasha Point to add +4k1 to any Hunting (Tracking) roll."}, {"id": "x_naga_scout_blackened_sky", "nome": "Blackened Sky", "rank": 4, "descricao": "The Scout learns to defeat his foes before the enemy is even aware of his presence. You may make attacks as a Simple Action instead of a Complex Action when using a bow."}, {"id": "x_naga_scout_relentless_ranger", "nome": "Relentless Ranger", "rank": 5, "descricao": "The Naga Scout learns to push aside the stresses of his own body when on the hunt, relying on the focus of the Akasha to continue beyond his own means. You may function at full […]"}]}, {"id": "x_naga_vedic", "nome": "Naga Vedic", "clanId": "naga", "livro": "Enemies of the Empire", "pagina": "85", "traco": "awareness", "honra": "6.5", "tags": ["courtier", "naga_courtier", "nonhuman"], "pericias": [{"id": "courtier", "rank": 1, "enfase": ""}, {"id": "divination", "rank": 1, "enfase": "Astrology"}, {"id": "etiquette", "rank": 1, "enfase": ""}, {"id": "medicine", "rank": 1, "enfase": "Non-Humans"}, {"id": "meditation", "rank": 1, "enfase": ""}], "periciasTexto": "Courtier, Divination (Astrology), Etiquette, Lore: Naga Law, Medicine (Non-Humans), Meditation, any one Lore skill", "beneficio": "+1 Awareness", "tecnicas": [{"id": "x_naga_vedic_reflecting_calm", "nome": "Reflecting Calm", "rank": 1, "descricao": "The Vedics are often diplomats and negotiators when situations requre a calm eye and an unshakable mind. You may make a Contested Courtier / Awareness roll to impart the calm of the Akasha on any one target. You gain a bonus of +2k0 to the total of this roll, +3k1 if the target is a Naga. If the roll succeeds, you sway the target’s mood to be more amenable to your position. The target will no longer be combative; if the test occurs during a skirmish, the skirmish immediately ends and the target will attempt to talk through the situation. If anyone else attacks your target or if the talks fail, combat immediately begins once more and your target gains a free Combat Round before normal combat continues. You may not attempt to use this Technique on the same target more than once a day."}, {"id": "x_naga_vedic_arbiter", "nome": "Arbiter", "rank": 2, "descricao": "The Naga Vedics are masters of the laws of Naga society and act as judges when the situation merits. You gain a bonus of +2k1 to the total of any Social rolls with Naga."}, {"id": "x_naga_vedic_heartbeat_of_the_world", "nome": "Heartbeat of the World", "rank": 3, "descricao": "The Naga Vedic attunes himself to the pulse of the world, becoming one with nature itself. You immediately gain one Inner Gift of your choosing (subject to GM’s discretion)."}, {"id": "x_naga_vedic_finding_harmony_within", "nome": "Finding Harmony Within", "rank": 4, "descricao": "The Vedic is calm at all times, balancing his personal desires with the will of the Akasha. While you are acting in the best interests of the Naga, you gain a bonus of +2k0 to the total of any Social Roll. This Technique stacks with your Rank 2 Technique."}, {"id": "x_naga_vedic_swimming_the_depths_of_the_akasha", "nome": "Swimming the Depths of the Akasha", "rank": 5, "descricao": "The Vedic is in tune with the desires of the Akasha, and the great consciousness of the Naga wishes to protect its children. You may take a Complex Action to touch a target and suffer Wounds equal to one full Wound Rank. If your target is a Naga, he immediately heals two full Wound Ranks; otherwise, the target heals one full Wound Rank. If the target suffers from a disease, infection, mental illness, or similar problem, you must immediately make a Stamina roll (at an appropriate TN as set by the GM) or succumb to its effects. However, if the roll is successful, you cleanse the target of the negative effect, whatever it might be. You may not be healed from any diseases or other effects gained from this Technique by any means for a minimum of one full day. The Shadowlands Taint and the Nothing are unaffected by this Technique."}]}, {"id": "x_naga_warrior", "nome": "Naga Warrior", "clanId": "naga", "livro": "Enemies of the Empire", "pagina": "85", "traco": "strength", "honra": "4.5", "tags": ["bushi", "naga_bushi", "nonhuman"], "pericias": [{"id": "defense", "rank": 1, "enfase": ""}, {"id": "hunting", "rank": 1, "enfase": ""}, {"id": "kenjutsu", "rank": 1, "enfase": ""}, {"id": "kyujutsu", "rank": 1, "enfase": ""}, {"id": "spears", "rank": 1, "enfase": "Naga Spear"}, {"id": "lore_shadowlands", "rank": 1, "enfase": ""}], "periciasTexto": "Defense, Hunting, Kenjutsu, Kyujutsu, Spears (Naga Spear), Lore: Shadowlands, any one Bugei Skill", "beneficio": "+1 Strength", "tecnicas": [{"id": "x_naga_warrior_the_soul_of_the_naga", "nome": "The Soul of the Naga", "rank": 1, "descricao": "The first lesson for the Naga Warrior is that he can rely on the Akasha to guide his hand. Once each Turn you may gain a bonus equal to your Akasha Trait to the total of any one roll (except damage rolls). This bonus doubles against enemies of the Naga (Shadowlands creatures, Nothing creatures, Ashalan)."}, {"id": "x_naga_warrior_high_strike", "nome": "High Strike", "rank": 2, "descricao": "The Naga Warrior learns to rear to his full height, rising over his comrades in the front lines to strike at the enemy. As a Free Action you may rear onto your tail to tower over your enemies. While you are standing tall in this way, your Armor TN is lowered by 5 but you add +2k0 to all melee attack rolls against targets at ground height. You may drop back to your normal stance in the same Round as a Simple Action, or as a Free Action on a different Round."}, {"id": "x_naga_warrior_chosen_of_qatol", "nome": "Chosen of Qatol", "rank": 3, "descricao": "The Naga Warrior is the consummate fighter, never relenting in the face of his enemies. You may make attacks as a Simple Action instead of a Complex Action while using a weapon with the Naga keyword."}, {"id": "x_naga_warrior_the_akasha_protects", "nome": "The Akasha Protects", "rank": 4, "descricao": "The Naga Warrior is never alone, knowing that his connection to the rest of his race cannot be severed. Once per skirmish, you may take a Free Action at the start of any Round to activate this Technique. You gain Reduction equal to your Akasha Trait for 3 full Rounds."}, {"id": "x_naga_warrior_heart_of_a_warrior", "nome": "Heart of a Warrior", "rank": 5, "descricao": "The Naga Warrior never falters or stops, as the Akasha cleanses his soul. You may spend an Akasha Point as a Free Action during your Turn to remove any one Status Effect on yourself. If you are Stunned, you may still use this Technique but it counts as a Simple Action instead."}]}, {"id": "x_nezumi_warriors_ch", "nome": "Nezumi Warriors (\"Ch\")", "clanId": "nezumi", "livro": "Enemies of the Empire", "pagina": "112", "traco": "agility", "honra": "", "tags": ["bushi", "nezumi_bushi", "nonhuman"], "pericias": [{"id": "athletics", "rank": 1, "enfase": ""}, {"id": "defense", "rank": 1, "enfase": ""}, {"id": "hunting", "rank": 1, "enfase": "Survival"}, {"id": "lore_shadowlands", "rank": 1, "enfase": ""}, {"id": "stealth", "rank": 1, "enfase": ""}], "periciasTexto": "Athletics, Defense, Hunting (Survival), Jiujutsu, Lore: Shadowlands, Stealth, any one Weapon skill", "beneficio": "+1 Agility", "tecnicas": [{"id": "x_nezumi_warriors_ch_speed_of_the_rat", "nome": "Speed of the Rat", "rank": 1, "descricao": "Nezumi are lightning fast creatures with incredible reflexes. A Nezumi warrior may re-roll his Initiative a number of times per day equal to his Rank in this school. The warrior may choose which of the two rolls to keep. The warrior adds half of his ranks in the Athletics skill to his Armor TN while not in the Full Attack Stance […]"}, {"id": "x_nezumi_warriors_ch_strength_of_the_pack", "nome": "Strength of the Pack", "rank": 2, "descricao": "Young Nezumi warriors hunt and fight in packs to increase their chances of survival. For every ally who has attacked the Nezumi’s target since his last Turn (whether their attacks were successful or not), he gains a +1k0 bonus on his next melee attack roll. The total dice bonus may not exceed his School Rank."}, {"id": "x_nezumi_warriors_ch_strike_strike_fast", "nome": "Strike-Strike Fast", "rank": 3, "descricao": "The warrior has learned the true lightning speed of the Nezumi. He may make melee attacks as a Simple Action instead of a Complex Action."}, {"id": "x_nezumi_warriors_ch_darting_strike", "nome": "Darting Strike", "rank": 4, "descricao": "Accustomed to fighting larger, stronger opponents, the warrior has learned to rely on his speed to avoid their blows. The The Ratlings warrior adds +10 to his Armor TN against any attack roll from an opponent with a lower Initiative score."}, {"id": "x_nezumi_warriors_ch_tail_sweep", "nome": "Tail Sweep", "rank": 5, "descricao": "111 The tail is an often-overlooked advantage of the Nezumi warrior, and at this rank the Ratling has learned to make full use of it. During any round in which the Nezumi makes a suc- […]"}]}, {"id": "x_nezumi_scrounger_ithith", "nome": "Nezumi Scrounger (\"Ithith\")", "clanId": "nezumi", "livro": "Enemies of the Empire", "pagina": "112", "traco": "perception", "honra": "", "tags": ["ninja", "nezumi_ninja", "nonhuman"], "pericias": [{"id": "athletics", "rank": 1, "enfase": ""}, {"id": "defense", "rank": 1, "enfase": ""}, {"id": "hunting", "rank": 1, "enfase": ""}, {"id": "lore_shadowlands", "rank": 1, "enfase": ""}, {"id": "stealth", "rank": 1, "enfase": "Sneaking"}, {"id": "sleight_of_hand", "rank": 1, "enfase": ""}], "periciasTexto": "Athletics, Defense, Hunting, Lore: Shadowlands, Stealth (Sneaking), Sleight of Hand, any one Skill", "beneficio": "+1 Perception", "tecnicas": [{"id": "x_nezumi_scrounger_ithith_scurry_scurry_through_the_darkness", "nome": "Scurry-Scurry Through the Darkness", "rank": 1, "descricao": "The first lesson taught to every Scrounger is to rely on speed and cunning. You gain a bonus of +2k0 to all your Stealth Skill rolls, and you may add your Stealth Skill Rank to your Armor TN at all times (even if you are caught unaware)."}, {"id": "x_nezumi_scrounger_ithith_fight_and_fly", "nome": "Fight and Fly", "rank": 2, "descricao": "Scroungers are taught the art of distraction in order to avoid dangerous foes. If you successfully strike an opponent in a skirmish, and there is cover or darkness available nearby 112 to conceal you, you may forego inflicting Wounds. Instead, you spend a Name Point and make a Contested Roll of your The Ratlings Stealth (Sneaking) / Agility against your opponent’s Investigation (Notice) / Perception. If you succeed, your opponent loses track of your location."}, {"id": "x_nezumi_scrounger_ithith_yours_is_mine", "nome": "Yours Is Mine", "rank": 3, "descricao": "Scroungers are such swift and instinctive thieves that they can steal even from those who are aware of their presence. If you are within 5’ of a target, you may take a Simple Action to make a Contested Roll of your Sleight of Hand (Pick Pocket) / Agility against your opponent’s Defense / Agility. If you succeed, you snatch a random item from the target’s obi, pocket, or any other accessible place. (You cannot steal items directly out of your opponent’s hands.)"}, {"id": "x_nezumi_scrounger_ithith_riding_the_shadow", "nome": "Riding the Shadow", "rank": 4, "descricao": "The Scrounger who has reached this level of skill is now so lightning fast that he may make melee attacks as a Simple Action instead of a Complex Action when he is using unarmed attacks or weapons with the Small or Peasant qualities."}, {"id": "x_nezumi_scrounger_ithith_hide_from_tomorrow", "nome": "Hide From Tomorrow", "rank": 5, "descricao": "At this rank, a Scrounger becomes so swift and cunning that he can literally hide in his enemy’s shadow. You may attempt to hide behind your opponent as a Complex Action, making a Contested Roll of Stealth (Sneaking) / Agility against your opponent’s Investigation (Notice) / Perception. If you beat your opponent by at least 15, you successfully hide behind him. Your opponent may suspect where you are, but you move too quickly for him to catch a glimpse of you. You may not hide behind more than one opponent at a time."}]}, {"id": "x_nezumi_shaman_nameseeker_kir", "nome": "Nezumi Shaman (Nameseeker/\"Kir\")", "clanId": "nezumi", "livro": "Enemies of the Empire", "pagina": "113", "traco": "", "honra": "", "tags": ["shugenja", "nezumi_shugenja", "nonhuman"], "pericias": [{"id": "lore_shadowlands", "rank": 1, "enfase": ""}, {"id": "meditation", "rank": 1, "enfase": ""}, {"id": "stealth", "rank": 1, "enfase": ""}], "periciasTexto": "Lore: Shadowlands, Lore: Spirit Realms (Yumedo), Meditation, Perform: Nezumi Dance, Stealth, any two Skills", "beneficio": "+1 Name", "tecnicas": [{"id": "x_nezumi_shaman_nameseeker_kir_name_magic", "nome": "Name Magic", "rank": 1, "descricao": "A Nezumi shaman is capable of casting Nezumi Name Magic spells. See the section later in this chapter for details. All Shamans begin play knowing three Name Magic spells of appropriate Mastery Level of their choice."}]}, {"id": "x_nezumi_rememberer_tch_tch", "nome": "Nezumi Rememberer (\"Tch'tch\")", "clanId": "nezumi", "livro": "Enemies of the Empire", "pagina": "113", "traco": "intelligence", "honra": "", "tags": ["courtier", "nezumi_courtier", "nonhuman"], "pericias": [{"id": "lore_shadowlands", "rank": 1, "enfase": ""}, {"id": "perform_storytelling", "rank": 1, "enfase": ""}, {"id": "stealth", "rank": 1, "enfase": ""}], "periciasTexto": "Lore: Nezumi History, Lore: Nezumi Culture, Lore: Shadowlands, Perform: Storytelling, Stealth, any one Skill", "beneficio": "+1 Intelligence", "tecnicas": [{"id": "x_nezumi_rememberer_tch_tch_remembering", "nome": "Remembering", "rank": 1, "descricao": "Rememberers are taught from earliest youth how to create Memory Sticks, tangible reminders of the past. A Rememberer may normally create any Memory Sticks with a Mastery Level equal to his Rank in this School, but may also create one type of Memory Stick that is one Mastery Level above his current School Rank. (Thus a Rank Two Rememberer can create all Mastery Level One and Two Memory Sticks, and one type of Mastery Level Three Memory Stick.) All Rememberers begin with the Precise Memory Advantage at no Experience Point cost."}]}, {"id": "x_kenku_swordsman_school", "nome": "Kenku Swordsman School", "clanId": "kenku", "livro": "Enemies of the Empire", "pagina": "181", "traco": "reflexes", "honra": "", "tags": ["bushi", "kenku_bushi", "nonhuman"], "pericias": [{"id": "defense", "rank": 1, "enfase": ""}, {"id": "hunting", "rank": 1, "enfase": ""}, {"id": "kenjutsu", "rank": 1, "enfase": "Katana"}, {"id": "meditation", "rank": 1, "enfase": ""}, {"id": "tea_ceremony", "rank": 1, "enfase": ""}], "periciasTexto": "Defense, Hunting, Kenjutsu (Katana), Meditation, Tea Ceremony, any one Lore skill, any one Bugei Skill", "beneficio": "+1 Reflexes", "tecnicas": [{"id": "x_kenku_swordsman_school_wing_of_thunder", "nome": "Wing of Thunder", "rank": 1, "descricao": "The kenku bushi has learned to harness the speed of the wind itself, and can draw that element into himself. You may add the total of your Reflexes and School Rank to your Armor TN against any enemy with lower Initiative."}, {"id": "x_kenku_swordsman_school_heavens_claw", "nome": "Heaven’s Claw", "rank": 2, "descricao": "The bushi has tapped the power of the thunderbolt, striking hard at his enemy’s weaknesses. Any time you inflict more than 10 points of damage with a single attack, your opponent loses one Void Point. Against opponents with no Void Points remaining (or no Void), you may instead re-roll a single damage die and take the better of the two results."}, {"id": "x_kenku_swordsman_school_lightning_kiss", "nome": "Lightning Kiss", "rank": 3, "descricao": "The kenku bushi has captured the swift fury of lightning. You may attack as a Simple Action while using any melee weapon in which you possess a Skill Emphasis."}, {"id": "x_kenku_swordsman_school_churning_skies", "nome": "Churning Skies", "rank": 4, "descricao": "The kenku bushi has learned to patiently build his energies, only to strike with thunderous power. If you choose to delay your Turn during a Round until after all your opponents have acted, you may ignore the effects of all Wound Penalties (including Down and Out) and your may spend any amount of your Void Points on your damage rolls during this Round."}, {"id": "x_kenku_swordsman_school_the_same_breeze", "nome": "The Same Breeze", "rank": 5, "descricao": "Even two leaves carried on the same breeze may take quite different paths. This is the final lesson of the kenku school. At the beginning of your Turn, you may take a Free Action and spend a Void Point to copy one bushi Technique of any other character (human or otherwise) within 20’ for a number of Rounds equal to your Air. You must abide by whatever costs and restrictions apply to the copied Technique (Void Point cost, specific armor or weapons, etc). If you are not a Kenku yourself, you must have seen the Technique you are copying used at least once. Regardless of whether you are human or Kenku, you may only copy one Technique at a time."}]}, {"id": "x_tsuno_ravager", "nome": "Tsuno Ravager", "clanId": "tsuno", "livro": "Enemies of the Empire", "pagina": "188", "traco": "", "honra": "", "tags": ["bushi", "tsuno_bushi", "nonhuman"], "pericias": [{"id": "athletics", "rank": 1, "enfase": ""}, {"id": "battle", "rank": 1, "enfase": ""}, {"id": "defense", "rank": 1, "enfase": ""}, {"id": "iaijutsu", "rank": 1, "enfase": ""}, {"id": "lore_spirit_realms", "rank": 1, "enfase": ""}, {"id": "kenjutsu", "rank": 1, "enfase": "Tsuno Blade"}], "periciasTexto": "Athletics, Battle, Defense, Iaijutsu, Lore: Spirit Realms, Kenjutsu (Tsuno Blade), any one Bugei Skill.", "beneficio": "None", "tecnicas": [{"id": "x_tsuno_ravager_kill_your_weakness", "nome": "Kill Your Weakness", "rank": 1, "descricao": "Tsuno Ravagers draw strength from the weakness of others, and learn to conquer their own. When a Ravager is wounded he draws strength from the pain. When a Ravager is injured, he gains a Reduction rating equal to his current Wound Penalties. (This Technique works off of base Wound Penalties, ignoring any Wound Penalty modifications for spells, Advantages such as Strength of the Earth, and similar effects.) This bonus changes as the Ravager’s Wound Penalties change, and ceases to function once he is at Down or Out."}, {"id": "x_tsuno_ravager_howl_of_the_displaced", "nome": "Howl of the Displaced", "rank": 2, "descricao": "Ravagers are leaders among their Tsuno brethren. Once per day a Ravager can take a Simple Action to draw upon the fury of the Tsuno race and unleash a terrifying howl, inspiring the Ravager’s allies and disheartening his enemies. Any foes who hear the howl are affected by Fear 5, and any allies within earshot gain a +1k0 bonus to their attack rolls. Both effects last for a number of Rounds equal to the Ravager’s School Rank."}, {"id": "x_tsuno_ravager_tsuno_technique", "nome": "Tsuno Technique", "rank": 3, "descricao": "A Ravager’s years of battle in the Spirit Realms have taught him speed as well as strength. The Ravager may make melee attacks as a Simple Action instead of a Complex Action."}, {"id": "x_tsuno_ravager_undying_vengeance", "nome": "Undying Vengeance", "rank": 4, "descricao": "Gaining the ire of a Tsuno Ravager is usually the last mistake its enemies ever make, for Ravagers have a supernatural sense of their enemies’ locations. If a Ravager has wounded or been wounded by a foe, he may take a Simple Action to make an Awareness Roll (TN 15 if the foe is within the same Spirit […]"}, {"id": "x_tsuno_ravager_slaughter_is_in_the_blood", "nome": "Slaughter Is in the Blood", "rank": 5, "descricao": "Centuries of battle within Toshigoku have imbued the Tsuno Ravagers with a thirst for slaughter. If a Ravager kills an opponent, he immediately gains a number of individual +1k1 bonuses equal to his School Rank. These bonuses may be used on attack rolls, damage rolls, or any Skill or Trait roll, and must be used before the end of the next Round or they are lost. This Technique can be triggered a number of times each skirmish equal to the Ravager’s School Rank."}]}, {"id": "x_tsuno_soultwister", "nome": "Tsuno Soultwister", "clanId": "tsuno", "livro": "Enemies of the Empire", "pagina": "189", "traco": "", "honra": "", "tags": ["shugenja", "tsuno_shugenja", "nonhuman"], "pericias": [{"id": "athletics", "rank": 1, "enfase": ""}, {"id": "battle", "rank": 1, "enfase": ""}, {"id": "defense", "rank": 1, "enfase": ""}, {"id": "intimidation", "rank": 1, "enfase": "Torture"}, {"id": "kenjutsu", "rank": 1, "enfase": "Tsuno Blade"}, {"id": "lore_spirit_realms", "rank": 1, "enfase": ""}], "periciasTexto": "Athletics, Battle, Defense, Intimidation (Torture), Kenjutsu (Tsuno Blade), Lore: Spirit Realms, any one Bugei skill.", "beneficio": "None", "tecnicas": [{"id": "x_tsuno_soultwister_the_power_of_the_spirits", "nome": "The Power of the Spirits", "rank": 1, "descricao": "Soultwisters travel across the Spirit Realms, learning tricks and stealing power, then imbuing their allies and enemies with the traits and powers of the spirits. No Soultwister can master the magic of all of the spirit realms; each Tsuno must choose three Spirit Realms when he becomes a Soultwister. He may only use spells related to those realms. He begins by knowing one spell from each of these three spirit realms. Every time the Soultwister increases in School Rank he may choose to either gain three new spells from his chosen Spirit Realms, or learn magic from a new Spirit Realm and gain one […]"}], "afinidade": "Soultwisters have an affinity for"}, {"id": "x_self_taught_shugenja", "nome": "Self-Taught Shugenja", "clanId": "ronin", "livro": "Enemies of the Empire", "pagina": "206", "traco": "willpower", "honra": "4.0", "tags": ["shugenja", "ronin_shugenja"], "pericias": [{"id": "athletics", "rank": 1, "enfase": ""}, {"id": "hunting", "rank": 1, "enfase": ""}, {"id": "meditation", "rank": 1, "enfase": ""}, {"id": "spellcraft", "rank": 1, "enfase": ""}], "periciasTexto": "Athletics, Hunting, Meditation, Spellcraft, any three non-High Skills", "beneficio": "+1 Willpower", "tecnicas": [{"id": "x_self_taught_shugenja_the_kamis_gift", "nome": "The Kami’s Gift", "rank": 1, "descricao": "Those who are self-taught possess an affinity for the kami that many among the clans would envy. When you spend a Void Point on a Spellcasting Roll, you add +2k2 instead of +1k1. Unfortunately, you do not automatically gain additional spells when you advance in Rank; you must seek them out on your own. Spells: Sense, Commune, Summon, and any five spells you can cast (no spells may be in Elements for which you have a Deficiency)."}], "afinidade": "Self-taught shugenja typically"}, {"id": "x_dutiful_disciple_shugenja", "nome": "Dutiful Disciple Shugenja", "clanId": "ronin", "livro": "Enemies of the Empire", "pagina": "206", "traco": "intelligence", "honra": "4.0", "tags": ["shugenja", "ronin_shugenja"], "pericias": [{"id": "calligraphy", "rank": 1, "enfase": ""}, {"id": "lore_theology", "rank": 1, "enfase": ""}, {"id": "meditation", "rank": 1, "enfase": ""}, {"id": "spellcraft", "rank": 1, "enfase": ""}], "periciasTexto": "Calligraphy, Lore: Theology, Lore (pick one), Meditation, Spellcraft, any two Skills", "beneficio": "+1 Intelligence", "tecnicas": [{"id": "x_dutiful_disciple_shugenja_soul_of_study", "nome": "Soul of Study", "rank": 1, "descricao": "Disciples often idolize their mentors and regard their teachings as the most sacred of verses. When casting one of your beginning spells (the ones given you by you mentor), you roll an additional +1k0 on Spell Casting Rolls. Spells: Sense, Commune, Summon, 3 spells of your […]"}], "afinidade": "Disciple shugenja typically have"}, {"id": "x_ronin_order_shugenja", "nome": "Ronin Order Shugenja", "clanId": "ronin", "livro": "Enemies of the Empire", "pagina": "207", "traco": "awareness", "honra": "5.0", "tags": ["shugenja", "ronin_shugenja"], "pericias": [{"id": "calligraphy", "rank": 1, "enfase": "Cipher"}, {"id": "divination", "rank": 1, "enfase": ""}, {"id": "lore_theology", "rank": 1, "enfase": ""}, {"id": "meditation", "rank": 1, "enfase": ""}, {"id": "spellcraft", "rank": 1, "enfase": ""}], "periciasTexto": "Calligraphy (Cipher), Divination, Lore: Theology, Lore (pick any), Meditation, Spellcraft, any one Skill", "beneficio": "+1 Awareness", "tecnicas": [{"id": "x_ronin_order_shugenja_the_path_of_dicipline", "nome": "The Path of Dicipline", "rank": 1, "descricao": "Orders such as the Brotherhood and other prominent ronin groups emphasize the most basic tenets of shugenja traditions, strengthening the core beliefs and abilities of their students. You gain one Free Raise on all Sense, Commune, and Summon spells for all elements except Void and Earth. Spells: Sense, Commune, Summon, 3 Air spells, 2 Water spells, and 1 Fire spell […]"}], "afinidade": "Ronin orders tend to emphasize"}, {"id": "x_free_ogre_bushi_muhomono", "nome": "Free Ogre Bushi (Muhomono)", "clanId": "ogre", "livro": "Enemies of the Empire", "pagina": "240", "traco": "strength", "honra": "0", "tags": ["bushi", "ogre_bushi", "nonhuman"], "pericias": [{"id": "battle", "rank": 1, "enfase": ""}, {"id": "defense", "rank": 1, "enfase": ""}, {"id": "jiujutsu", "rank": 1, "enfase": ""}, {"id": "heavy_weapons", "rank": 1, "enfase": "ogres treat any large club, tree-trunk, etc, as a Heavy Weapon"}, {"id": "hunting", "rank": 1, "enfase": ""}, {"id": "intimidation", "rank": 1, "enfase": "Bullying"}, {"id": "stealth", "rank": 1, "enfase": ""}], "periciasTexto": "Battle, Defense, Jiujutsu, Heavy Weapons (ogres treat any large club, tree-trunk, etc, as a Heavy Weapon), Hunting, Intimidation (Bullying), Stealth", "beneficio": "+1 Strength", "tecnicas": [{"id": "x_free_ogre_bushi_muhomono_muhomonos_strength", "nome": "Muhomono’s Strength", "rank": 1, "descricao": "Named for the legendary king of ogres, this technique comes as a profound revelation to most free ogres as they reconnect with their race’s ancient legacy. It allows the ogre to focus its strength into more powerful blows, instead of wasting it like his savage cousins. Before rolling Initiative, you may choose to inflict a –1k1 penalty on your Initiative roll. If you do, you gain +2k0 on all damage rolls for the rest of the skirmish. Also, you gain a Free Raise on all Intimidation (Bullying) rolls."}, {"id": "x_free_ogre_bushi_muhomono_muhomonos_eyes", "nome": "Muhomono’s Eyes", "rank": 2, "descricao": "The great Muhomono won many fights with his terrifying gaze, striking fear into his opponents before the fight even began. Your Fear rating is increased by 1, and you add +1k0 to your attack rolls against any opponent who failed to resist your Fear."}, {"id": "x_free_ogre_bushi_muhomono_muhomonos_speed", "nome": "Muhomono’s Speed", "rank": 3, "descricao": "The ogre warrior strikes his opponent with speed and strength, certain in his superiority over any opponent. You may make attacks as a Simple Action instead of a Complex Action while using large weapons, Heavy Weapons, or unarmed attacks."}, {"id": "x_free_ogre_bushi_muhomono_muhomonos_arm", "nome": "Muhomono’s Arm", "rank": 4, "descricao": "The broad and powerful arm of the ogre bushi carries over from one opponent to another, never slowing down. Once per skirmish, if you successfully hit an opponent with a melee attack, you may immediately inflict the same damage roll on another opponent of your choice within 5 feet of the first one, without making an attack roll against the second opponent. This does not count as a separate attack."}, {"id": "x_free_ogre_bushi_muhomono_muhomonos_armor", "nome": "Muhomono’s Armor", "rank": 5, "descricao": "A true ogre bushi knows that physical armor is only a disguise – the true warrior needs nothing more than his skin and determination. Your natural Reduction increases to 20."}]}, {"id": "x_free_ogre_shugenja", "nome": "Free Ogre Shugenja", "clanId": "ogre", "livro": "Enemies of the Empire", "pagina": "241", "traco": "willpower", "honra": "0", "tags": ["shugenja", "ogre_shugenja", "nonhuman"], "pericias": [{"id": "battle", "rank": 1, "enfase": ""}, {"id": "defense", "rank": 1, "enfase": ""}, {"id": "hunting", "rank": 1, "enfase": ""}, {"id": "jiujutsu", "rank": 1, "enfase": ""}, {"id": "intimidation", "rank": 1, "enfase": "Bullying"}], "periciasTexto": "Battle, Defense, Hunting, Jiujutsu, Intimidation, Lore: History (Ogres), Spellcraft", "beneficio": "+1 Willpower", "tecnicas": [{"id": "x_free_ogre_shugenja_strength_of_the_mind", "nome": "Strength of the Mind", "rank": 1, "descricao": "The ogre mages do not use the same techniques as the Rokugani shugenja, but instead coerce the kami into submission through mystical sigils and sheer strength of will. You can never learn or use the spells Sense, Commune, or Summon. You do not need spell scrolls; instead you call on the power of sigils carved into your own skin (in mechanical terms, all of your spells are considered to be memorized). You have no Affinity or Deficiency and cannot learn kiho. Spells: 3 Fire, 2 Earth, and 1 Air."}]}, {"id": "x_kolat_assassin", "nome": "Kolat Assassin", "clanId": "kolat", "livro": "Enemies of the Empire", "pagina": "50", "traco": "", "honra": "", "tags": ["ninja", "kolat_ninja", "advanced"], "pericias": [], "periciasTexto": "Acting 5, Knives 5, Stealth 5 Other Requirements: Must be a member of the KoENEMIES OF THE EMPIRE c lat and recruited into the Lotus Sect. Cannot be Tainted or corrupted by the Nothing. 50 The Kolat", "beneficio": "", "tecnicas": [{"id": "x_kolat_assassin_kiss_of_the_lotus", "nome": "Kiss of the Lotus", "rank": 1, "descricao": "The Kolat assassins are taught to slip through Rokugani society all but unnoticed. You are a master of deception and infiltration. When you spend a Void Point on a Stealth or Acting Skill roll, you gain a +2k2 bonus instead of the normal +1k1."}, {"id": "x_kolat_assassin_tigers_claw", "nome": "Tiger’s Claw", "rank": 2, "descricao": "When striking on the first Round of a skirmish against an unaware opponent, or an opponent who does not realize you are a threat, you gain a +1k0 bonus to your attack rolls and may make melee attacks as Simple Action."}, {"id": "x_kolat_assassin_steal_the_light", "nome": "Steal the Light", "rank": 3, "descricao": "During a skirmish, once per opponent you may call 2 Raises to make a melee attack that keeps only 1 die of damage (regardless of the weapon used) but leaves the opponent either blind, deaf, or mute (your choice) for a number of minutes equal to your Water. Blinded characters suffer the Blind Conditional Effect from the L5R 4th Edition core rulebook. The GM has discretion to decide the exact penalties of being deafened or muted, but some effects should be obvious – for example, a muted character cannot cast spells."}]}, {"id": "x_nezumi_berserkers_chitatachikkan", "nome": "Nezumi Berserkers (\"Chitatachikkan\")", "clanId": "nezumi", "livro": "Enemies of the Empire", "pagina": "113", "traco": "", "honra": "", "tags": ["bushi", "nezumi_bushi", "advanced", "nonhuman"], "pericias": [], "periciasTexto": "", "beneficio": "", "tecnicas": [{"id": "x_nezumi_berserkers_chitatachikkan_mad_fury", "nome": "Mad Fury", "rank": 1, "descricao": "The Berserkers are touched by a power most Nezumi do not understand, and in combat they are a torrent of furious attacks. You gain a +1k1 bonus to all attack rolls made while in the Full Attack Stance. You may make melee attacks as a Simple Action rather than a Complex Action."}, {"id": "x_nezumi_berserkers_chitatachikkan_dance_of_the_doomed", "nome": "Dance of the Doomed", "rank": 2, "descricao": "The Berserkers do not feel pain, instead fighting all the harder as their life-blood leaks out. Once per skirmish, at the start of your Turn you may take a Free Action to activate this Technique. Once it is active, you may ignore Wound Penalties (including Down or Out) for a number of Rounds equal to your Strength Rank. This ability does not allow you to keep fighting after you are dead."}, {"id": "x_nezumi_berserkers_chitatachikkan_sever_tomorrow", "nome": "Sever Tomorrow", "rank": 3, "descricao": "For a true Berserker, failure is worse than death. If you suffer enough Wounds to kill you, before dying you may immediately take a Free Action to make a final melee attack against an opponent within melee range (this must be the opponent who killed you if he is within reach). You gain a +3k0 bonus to this attack roll. You die after this attack is resolved (whether or not it succeeds)."}]}, {"id": "x_maho_bujin", "nome": "Maho-Bujin", "clanId": "shadowlands", "livro": "Enemies of the Empire", "pagina": "64", "traco": "", "honra": "", "tags": ["bushi", "shadowlands_bushi", "advanced", "maho"], "pericias": [], "periciasTexto": "", "beneficio": "", "tecnicas": [{"id": "x_maho_bujin_carve_the_crimson_road", "nome": "Carve the Crimson Road", "rank": 1, "descricao": "The maho-bujin’s body flows freely with the Taint that inhabits it, and his blows strike with a terrible power no mortal flesh can match. Your maximum Raises are now limited by your Taint Rank or your Void, whichever is higher. You gain a bonus in unkept dice equal to your Shadowlands Taint Rank on all damage rolls. You can now make the Extra Attack maneuver with only 2 Raises instead of 5."}, {"id": "x_maho_bujin_corruption_rewards", "nome": "Corruption Rewards", "rank": 2, "descricao": "The fighting instincts of a maho-bujin sense blood and leap for it, striking with preternatural skill and speed, and as his foes grow weaker the maho-bujin moves relentlessly faster and faster. During each Reactions Stage of a skirmish, you increase your Initiative by your Taint Rank. You may now make attacks as a Simple Action instead of a Complex Action."}, {"id": "x_maho_bujin_devourer_of_purity", "nome": "Devourer of Purity", "rank": 3, "descricao": "The warriors of Jigoku are able to heal themselves by feeding on the suffering of their enemies, even consuming their honor and strength of soul. Moreover, the maho-bujin has now transcended the Celestial Order and fully embraced the power of the Taint, making him nigh-indestructible. Any time you reduce someone to Down or Out or kill them, you instantly heal a number of Wounds equal to 2 x (their Honor Rank). This may be done any number of times per Round, but you cannot heal off the same person more than once in the same Round. In addition, you gain the creature ability of Invulnerability. (If you are already Invulnerable due to a Shadowlands power, you gain Reduction 10 instead.)"}]}, {"id": "x_scorpion_saboteurs", "nome": "Scorpion Saboteurs", "clanId": "scorpion", "livro": "Imperial Histories", "pagina": "180", "traco": "", "honra": "", "tags": ["ninja", "scorpion_ninja", "advanced", "historica"], "pericias": [], "periciasTexto": "Craft: Explosives 3, Stealth 5, Knives 4, Ninjutsu 4 c Other: Must be trained in one of the Scorpion basic schools with the [Ninja] tag", "beneficio": "", "tecnicas": [{"id": "x_scorpion_saboteurs_follow_the_pincers", "nome": "Follow the Pincers", "rank": 1, "descricao": "The Saboteurs are trained to an extreme degree of focus and alertness, assuring they can slip through enemy lines and silence anyone who spots them. You gain a +1k1 bonus to all Stealth rolls and suffer no Initiative penalties for being surprised, Dazed, or Fatigued."}, {"id": "x_scorpion_saboteurs_no_mistakes", "nome": "No Mistakes", "rank": 2, "descricao": "The Saboteur specializes in using demolitions to destroy vital targets such as walls, bridges, supply dumps, and castles. When you spend a Void Point on a roll with Craft: Explosives, you gain a +2k2 bonus instead of the normal +1k1. Due to your extensive training with gaijin pepper, you suffer no ill effects from low rolls with Craft: Explosives and if the optional “fizzle” rule is in effect you are immune to it as well."}, {"id": "x_scorpion_saboteurs_seeking_weakness_179", "nome": "Seeking Weakness", "rank": 3, "descricao": "The Saboteurs are trained to strike at their opponents’ The Clan War weak points with lethal and shocking speed. When fighting with a Small weapon (melee or ranged) you may make a single attack as a Free Action each Round in addition to any other Simple Action or Complex Action attacks you might make. Also, when fighting with a Small weapon (melee or ranged), you may ignore the effects of your opponent’s armor on his Armor TN and Reduction."}]}, {"id": "x_daidoji_harriers", "nome": "Daidoji Harriers", "clanId": "crane", "livro": "Imperial Histories", "pagina": "181", "traco": "", "honra": "", "tags": ["ninja", "crane_ninja", "advanced", "historica"], "pericias": [{"id": "hunting", "rank": 1, "enfase": "Traps"}], "periciasTexto": "Craft: Explosives 3, Hunting (Traps) 3, Stealth 5, Knives 4. c Other: Must be a Daidoji and recruited for membership in the Harriers", "beneficio": "", "tecnicas": [{"id": "x_daidoji_harriers_move_like_shadows", "nome": "Move Like Shadows", "rank": 1, "descricao": "The Harriers are taught to sacrifice their own Honor for the sake of the greater good of the Crane Clan (as they perceive it). They train to blend into the shadows and to defeat their foes with traps and ambushes. You lose only half the normal amount of Honor (rounded down) for any dishonorable actions taken on behalf of the Crane Clan. You gain a +1k1 bonus to the DR of any rural traps you create (this stacks with the Daidoji Scout techniques, if applicable). rank tw wOO: irOn Feather The lightning reflexes of a Harrier allows him to dodge his opponent’s attacks easily. When wearing light armor, ashigaru armor, or no armor, you may add your Stealth Skill Rank to your Armor TN."}, {"id": "x_daidoji_harriers_unforgiving_steel", "nome": "Unforgiving Steel", "rank": 3, "descricao": "The Harrier is taught to disable his foes with a single deadly strike. If you successfully attack a surprised or unaware opponent, or if an opponent takes damage from a rural trap you created, he is Dazed in addition to any other effects of your attack. He may not attempt to recover from the Daze until after the next Reactions stage, and the TN to recover from the Daze is increased by +5."}]}, {"id": "x_kitsu_sodan_senzo", "nome": "Kitsu Sodan-Senzo", "clanId": "lion", "livro": "Imperial Histories", "pagina": "244", "traco": "", "honra": "", "tags": ["shugenja", "lion_shugenja", "advanced", "historica"], "pericias": [], "periciasTexto": "Lore: Spirit Realms 4, Meditation 5 c Other: Must be a true blooded Kitsu with the ability to cast Water spells of Mastery Level 4 or higher", "beneficio": "", "tecnicas": [{"id": "x_kitsu_sodan_senzo_senses_of_the_kitsu", "nome": "Senses of the Kitsu", "rank": 1, "descricao": "The first gift of a true son of the kitsu is the ability to detect portals between the realms. Any time a spirit portal exists within a radius equal to your School Rank x 10 miles, the GM may opt to secretly make a Spellcraft / Perception (TN 25) roll to determine if you detect it. If the portal is within a number of miles equal to your School Rank or less, you pass this test automatically. Your previous School Rank increases by one for the purpose of casting spells."}, {"id": "x_kitsu_sodan_senzo_hand_of_the_kitsu", "nome": "Hand of the Kitsu", "rank": 2, "descricao": "Although peaceful, the kitsu were powerful warriors, and their descendants carry that potential within them. Your unarmed damage increases by an additional +0k1, representing the spiritual talons of the kitsu. You may make a Meditation Skill Roll (TN 30) to project your soul into the realms of Meido or Yomi, where you may interact with ancestral spirits (using Social Skill Rolls as normal if required)."}, {"id": "x_kitsu_sodan_senzo_soul_of_the_kitsu", "nome": "Soul of the Kitsu", "rank": 3, "descricao": "For the true kitsu there are no boundaries. When you proj241 ect your soul into the spirit realms (as described above in the Rank Two technique) you may take another person ThE War of SpiriTS with you if they also succeed at the Meditation Skill Roll. This passenger may see and hear everything you experience, but may not speak. Ancestral spirits with whom you interact can sense this passenger. Additionally, you gain one additional rank in your previous School for the purpose of casting spells."}]}, {"id": "x_hantei_bushi_school", "nome": "Hantei Bushi School", "clanId": "imperial", "livro": "Imperial Histories 2", "pagina": "27", "traco": "agility", "honra": "6.5", "tags": ["bushi", "imperial_bushi", "historica"], "pericias": [{"id": "athletics", "rank": 1, "enfase": ""}, {"id": "defense", "rank": 1, "enfase": ""}, {"id": "etiquette", "rank": 1, "enfase": ""}, {"id": "kenjutsu", "rank": 1, "enfase": ""}, {"id": "kyujutsu", "rank": 1, "enfase": ""}], "periciasTexto": "Athletics, Defense, Etiquette, Kenjutsu, Kyujutsu, Lore: Nonhumans, any one High or Bugei Skill", "beneficio": "+1 Agility", "tecnicas": [{"id": "x_hantei_bushi_school_the_blessings_of_heaven", "nome": "The Blessings of Heaven", "rank": 1, "descricao": "The basic lesson of Hantei is to call on the favor of the Celestial Realms to oppose those who stand against Heaven. When facing a “nonhuman” opponent, you may add either your Earth or your Honor (whichever is higher) to your Armor TN. You gain a +1k0 bonus to all your attack rolls with Samurai weapons."}, {"id": "x_hantei_bushi_school_wrath_of_the_earth_dragon", "nome": "Wrath of the Earth Dragon", "rank": 2, "descricao": "The power of Celestial Favor can overcome any who presume to trouble Ningen-do or the Empire of Togashi. At the start of your Turn, as a Free Action you may spend a Void Point to let your attacks this Round ignore all the Reduction of “nonhuman” opponents."}, {"id": "x_hantei_bushi_school_speed_of_the_air_dragon", "nome": "Speed of the Air Dragon", "rank": 3, "descricao": "The Celestial Dragons strike with speed beyond thought, and you seek to emulate them as well as a mortal may do so. You may attack as a Simple Action when you are wielding Samurai weapons or when attacking a “nonhuman” opponent."}, {"id": "x_hantei_bushi_school_courage_of_the_thunder_dragon", "nome": "Courage of the Thunder Dragon", "rank": 4, "descricao": "Those who serve the Celestial Heavens care not who their opponent may be, for the strength of Heaven’s favor cannot be withstood. After striking an opponent, you may spend a Void Point as a Free Action to ignore any one of that opponent’s Techniques, armor effects, spells, special qualities, or creature abilities (except for Invulnerability) which reduce/mitigate damage."}, {"id": "x_hantei_bushi_school_judgment_of_the_celestial_dragon", "nome": "Judgment of the Celestial Dragon", "rank": 5, "descricao": "The final lesson of the Hantei School is that the divine strike of Celestial Favor may defeat any foe, even one so powerful as Lord Moon himself. Once per skirmish, after hitting your opponent, you may spend four Void Points to automatically inflict enough damage to reduce that opponent to Down/Out/Dead (whichever applies first). If your opponent is “nonhuman” you may activate this Technique for three Void Points instead. It is GM’s discretion whether this Technique can defeat exceptionally powerful or transcendent entities such as Fortunes or similar. As an option, the GM may allow the Technique to work on such foes if you voluntarily choose to die in order to activate it."}]}, {"id": "x_otomo_diplomat_school", "nome": "Otomo Diplomat School", "clanId": "imperial", "livro": "Imperial Histories 2", "pagina": "28", "traco": "awareness", "honra": "6.5", "tags": ["courtier", "imperial_courtier", "historica"], "pericias": [{"id": "calligraphy", "rank": 1, "enfase": ""}, {"id": "courtier", "rank": 1, "enfase": ""}, {"id": "etiquette", "rank": 1, "enfase": "Courtesy"}, {"id": "intimidation", "rank": 1, "enfase": ""}, {"id": "sincerity", "rank": 1, "enfase": ""}], "periciasTexto": "Calligraphy, Courtier, Etiquette (Courtesy), Intimidation, Lore: Nonhumans, Sincerity, any one High Skill", "beneficio": "+1 Awareness", "tecnicas": [{"id": "x_otomo_diplomat_school_wisdom_of_the_owl", "nome": "Wisdom of the Owl", "rank": 1, "descricao": "The basic technique of the Otomo Diplomat is to find ways to relate successfully to all parties, human and nonhuman 28 alike, smoothing over misunderstandings and conflicts. You gain a +1k0 bonus to your Etiquette rolls. During any social interaction with “nonhumans,” you may as a Free Action roll Lore: Nonhumans / Intelligence at TN 20 to remember an important aspect of social interaction with those nonhumans (the GM chooses the specific thing you remember, but it will always be something useful to the situation)."}, {"id": "x_otomo_diplomat_school_unity_of_the_realms", "nome": "Unity of the Realms", "rank": 2, "descricao": "Because the Otomo specialize in negotiating with the “nonhuman” races, they have many friends, allies, and contacts among them. Any time you encounter a “nonhuman” in a non-hostile environment, you may roll Courtier / Awareness at TN 25. With a success, the “nonhuman” will treat you as an Ally with Devotion 2 for the remainder of the encounter (unless you actively do something to threaten or harm it)."}, {"id": "x_otomo_diplomat_school_the_voice_of_heaven", "nome": "The Voice of Heaven", "rank": 3, "descricao": "When understanding does not work, the Otomo have another method: cowing others by invoking the awesome authority of the Celestial Heavens. When you spend a Void Point on an Intimidation roll, you gain +2k2 instead of the normal +1k1. If the roll is made against a “nonhuman” opponent, the bonus is +3k2 instead. Either way, you do not lose Honor for using Intimidation in this manner."}, {"id": "x_otomo_diplomat_school_uphold_the_peace", "nome": "Uphold the Peace", "rank": 4, "descricao": "At this rank, the Otomo Diplomat is able to call on the awesome repute of the clan founder, Hantei himself, to impose peace on all manner of confrontations. At the start of a skirmish, or during your Turn on any later Round in such a skirmish, you may take a Complex Action to spend a Void Point and demand an immediate cessation of hostilities. You make a Contested Intimidation / Willpower roll against all those within hearing, gaining a +3k0 bonus against any of those targets who are “nonhumans.” Any combatants who lose the roll must cease all offensive action until they are attacked or until three Rounds have passed. This Technique cannot work against Shadowlands creatures or denizens of Jigoku or Tengoku."}, {"id": "x_otomo_diplomat_school_hanteis_mandate", "nome": "Hantei’s Mandate", "rank": 5, "descricao": "The Otomo may now bring the full weight of Hantei’s Celestial favor to bear against those who trouble Ningendo. You gain an additional +3k0 bonus to your Intimidation rolls with your Rank Four Technique (this stacks with the +3k0 bonus against “nonhumans” in that Technique)."}]}, {"id": "x_seppun_shugenja_school_dawn_of_the_empire", "nome": "Seppun Shugenja School (Dawn of the Empire)", "clanId": "imperial", "livro": "Imperial Histories 2", "pagina": "28", "traco": "intelligence", "honra": "6.5", "tags": ["shugenja", "imperial_shugenja", "historica"], "pericias": [{"id": "calligraphy", "rank": 1, "enfase": ""}, {"id": "defense", "rank": 1, "enfase": ""}, {"id": "investigation", "rank": 1, "enfase": ""}, {"id": "lore_theology", "rank": 1, "enfase": ""}, {"id": "meditation", "rank": 1, "enfase": ""}], "periciasTexto": "Calligraphy, Defense, Investigation, Lore: Nonhumans, Lore: Theology, Meditation, any one High skill", "beneficio": "+1 Intelligence", "tecnicas": [{"id": "x_seppun_shugenja_school_dawn_of_the_empire_in_defense_of_ningen_do", "nome": "In Defense of Ningen-Do", "rank": 1, "descricao": "The Seppun shugenja exist both to communicate with nonhumans and spirits and to protect the Empire from their depredations when they act improperly. You gain a Free Raise on any spell which targets a “nonhuman.” When casting a spell which inflicts damage on others, you may expend an additional spell slot (of the same Element or of Void) to have the spell ignore Reduction on the target(s) equal to twice your Void Rank. If the target is “nonhuman,” this Technique also ignores all damage mitigation effects from creature abilities (other than Invulnerability)."}], "afinidade": "Fire / Water"}, {"id": "x_first_dawn_scholars", "nome": "First Dawn Scholars", "clanId": "monks", "livro": "Imperial Histories 2", "pagina": "29", "traco": "intelligence", "honra": "5.5", "tags": ["monk", "monks_monk", "historica"], "pericias": [], "periciasTexto": "", "beneficio": "+1 Intelligence", "tecnicas": [{"id": "x_first_dawn_scholars_way_of_the_ancient_world", "nome": "Way of the Ancient World", "rank": 1, "descricao": "Your recognition that enlightenment and understanding transcend both race and time allows you to learn one additional Mystical kiho and grants you a +1k0 bonus on all Etiquette and Lore skills."}]}, {"id": "x_order_of_the_five_rings", "nome": "Order of the Five Rings", "clanId": "monks", "livro": "Imperial Histories 2", "pagina": "105", "traco": "awareness", "honra": "4.0", "tags": ["monk", "monks_monk", "historica"], "pericias": [], "periciasTexto": "", "beneficio": "+1 Awareness", "tecnicas": [{"id": "x_order_of_the_five_rings_cracks_within_the_elements", "nome": "Cracks Within the Elements", "rank": 1, "descricao": "Monks of the Order of the Five Rings excel at seeking out the imbalances within others and exploiting them to their own advantage. Whenever you are making an attack roll or a Social Skill Roll against a mortal opponent, you gain a bonus to the roll equal to twice the difference between your opponent’s highest and lowest Rings."}]}, {"id": "x_utaku_mounted_infantry", "nome": "Utaku Mounted Infantry", "clanId": "unicorn", "livro": "Imperial Histories 2", "pagina": "171", "traco": "agility", "honra": "5.5", "tags": ["bushi", "unicorn_bushi", "historica"], "pericias": [{"id": "athletics", "rank": 1, "enfase": ""}, {"id": "battle", "rank": 1, "enfase": ""}, {"id": "defense", "rank": 1, "enfase": ""}, {"id": "kenjutsu", "rank": 1, "enfase": ""}, {"id": "polearms", "rank": 1, "enfase": ""}, {"id": "spears", "rank": 1, "enfase": ""}], "periciasTexto": "Athletics, Battle, Defense, Kenjutsu, Polearms, Spears, any one Bugei or High Skill", "beneficio": "+1 Agility", "tecnicas": [{"id": "x_utaku_mounted_infantry_choose_your_weapon", "nome": "Choose Your Weapon", "rank": 1, "descricao": "The Utaku infantry are trained to fight with sword, spear, and polearm, but each student of the School is expected to choose one such weapon on which to focus his training. You may choose either the Kenjutsu Skill, the Polearms Skill, or the Spears Skill – you gain a free Emphasis of your choice in that skill. You are trained to use that weapon for both attack and defense. You add a +1k0 bonus when attacking with that Skill. If your chosen Skill is Spears or Polearms, when you are in the Defense or Full Defense stance while wielding a weapon using that Skill, you may add your Skill Ranks to your Armor TN. If your chosen Skill is Kenjutsu, you add half your Skill Rank (rounded down) instead."}, {"id": "x_utaku_mounted_infantry_speed_of_my_sisters", "nome": "Speed of My Sisters", "rank": 2, "descricao": "The Utaku Infantryman is taught to move swiftly in order to support the Unicorn cavalry on rapidly-evolving battlefields. On foot you move as though your Water Ring is 1 Rank higher and add a +1k0 bonus to your Initiative rolls."}, {"id": "x_utaku_mounted_infantry_all_fronts_attack", "nome": "All-Fronts Attack", "rank": 3, "descricao": "The Utaku Infantryman’s mastery of his chosen weapon has now reached the point of allowing him to strike in all directions with blinding speed. When using your chosen weapon Skill, you may attack as a Simple Action instead of a Complex Action."}, {"id": "x_utaku_mounted_infantry_utakus_thunder", "nome": "Utaku’s Thunder", "rank": 4, "descricao": "Like the women of the Utaku family, the men of the Utaku Infantry are taught to call upon their Honor to strengthen their purpose and their blows. Once per Skirmish while wielding your chosen weapon, you may spend a Void Point to add your Honor Rank in unkept dice to your attack roll. In addition, your movement bonus (from your Rank 2 Technique) now lets you move as though your Water Rank is 2 higher (instead of 1)."}, {"id": "x_utaku_mounted_infantry_epic_of_my_name", "nome": "Epic of My Name", "rank": 5, "descricao": "The fully trained Utaku Infantryman is an unpredictable whirlwind on the battlefield, striking and dodging with equal skill. The Armor TN bonus from your Rank One technique now also applies while you are in the Attack Stance. Once per skirmish while in the Full Attack Stance you may add a +4k2 bonus to your damage roll with chapter Seven your chosen weapon; if your chosen weapon is Spears or Polearms, you may do this in the Attack Stance as well."}]}, {"id": "x_tsudao_s_legion", "nome": "Tsudao's Legion", "clanId": "imperial", "livro": "Imperial Histories 2", "pagina": "248", "traco": "", "honra": "", "tags": ["bushi", "imperial_bushi", "advanced", "historica"], "pericias": [], "periciasTexto": "Battle 5, any one Weapon Skill at 5 c Other: Honor Rank 6+, Status Rank 2+, any one Paragon Advantage", "beneficio": "", "tecnicas": [{"id": "x_tsudao_s_legion_all_things_through_honor", "nome": "All Things Through Honor", "rank": 1, "descricao": "The members of Tsudao’s Legion are taught there is nothing that cannot be accomplished if one’s Honor is true. When making a Skill Roll with a High or Bugei Skill in which you have at least 1 Rank, you may spend a Void Point to make that roll as though your Skill Rank is equal to your Honor Rank."}, {"id": "x_tsudao_s_legion_wisdom_of_the_sensei", "nome": "Wisdom of the Sensei", "rank": 2, "descricao": "The dojo of Tsudao’s Legion teaches both tactical versatility and the joy of battle in the name of one’s lord. When rolling on the Mass Battle Table, you may add or subtract your Void Ring from the total of your roll, as desired. Additionally, you may select one Maneuver. Whenever you attempt that Maneuver, you gain one Free Raise toward success."}, {"id": "x_tsudao_s_legion_empowered_by_her_name", "nome": "Empowered by Her Name", "rank": 3, "descricao": "Those who devote themselves utterly to the cause of the Empress are nigh unstoppable in their fervor. If your Honor Rank exceeds your opponent’s Honor Rank, you may make a single additional melee attack (as a Free Action) once per Round against that opponent."}]}, {"id": "x_fudoist_order", "nome": "Fudoist Order", "clanId": "monks", "livro": "Imperial Histories 2", "pagina": "290", "traco": "willpower", "honra": "1.5", "tags": ["monk", "monks_monk", "historica"], "pericias": [], "periciasTexto": "", "beneficio": "+1 Willpower", "tecnicas": [{"id": "x_fudoist_order_for_each_one_path", "nome": "For Each, One Path", "rank": 1, "descricao": "Monks of Fudo must choose their own path, and it can vary wildly from one to another. At the time of character creation, you must choose a low or high Honor Rank (as indicated above). Likewise, you must choose to specialize in either opposed Social Skill Rolls or in Attack rolls. You gain a bonus to your total in the selected roll type equal to twice the difference between your Honor Rank and that of your opponent."}]}, {"id": "x_generic_ronin", "nome": "Generic Ronin", "clanId": "ronin", "livro": "Secrets of the Empire", "pagina": "238", "traco": "agility", "honra": "4.5", "tags": ["bushi", "ronin_bushi"], "pericias": [{"id": "athletics", "rank": 1, "enfase": ""}, {"id": "defense", "rank": 1, "enfase": ""}, {"id": "hunting", "rank": 1, "enfase": ""}, {"id": "intimidation", "rank": 1, "enfase": ""}, {"id": "kenjutsu", "rank": 1, "enfase": ""}, {"id": "knives", "rank": 1, "enfase": ""}], "periciasTexto": "Athletics, Defense, Hunting, Intimidation, Kenjutsu, Knives, any one Weapon Skill", "beneficio": "+1 Agility", "tecnicas": [{"id": "x_generic_ronin_strength_of_my_father", "nome": "Strength of My Father", "rank": 1, "descricao": "Ronin are known for their resilience in the face of adversity. When you are suffering TN penalties due to Wounds, you may make an Earth Roll (ignoring Wound TN penalties) during the Reactions Stage of each Round, with a TN equal to 5 + 5x the number of Wound Ranks you are currently suffering. If the roll is successful, you may ignore the effects of your Wound penalties until the next Reactions Stage. This Technique does not work once you reach the Down or Out Wound Ranks."}, {"id": "x_generic_ronin_never_yield", "nome": "Never Yield", "rank": 2, "descricao": "Ronin are accustomed to being the underdogs. When you are outnumbered in a skirmish, you gain a bonus to your Armor TN equal to the amount by which the number of enemies exceeds the number of your allies. This bonus cannot exceed the total of your School Rank x2."}, {"id": "x_generic_ronin_bite_of_the_wolf", "nome": "Bite of the Wolf", "rank": 3, "descricao": "Veteran ronin are swift and deadly fighters. You may attack as a Simple Action when wielding a katana or a knife."}, {"id": "x_generic_ronin_twice_cutting_spirit", "nome": "Twice-Cutting Spirit", "rank": 4, "descricao": "As ronin become truly experienced, they become ever more deadly with many different weapons. Choose one additional melee weapon: you may attack with that weapon as a Simple Action. Once per skirmish, you may spend a Void Point on a damage roll, regardless of what weapon you are using."}, {"id": "x_generic_ronin_valor_of_the_wolf", "nome": "Valor of the Wolf", "rank": 5, "descricao": "Those ronin who survive long enough to perfect their skills become legends of the battlefield, able to endure all manner of hardship and prevail in spite of severe injuries. Choose another melee weapon: you may attack with that weapon as a Simple Action. Additionally, you may spend a Void Point to activate your R1 Technique without requireing a Willpower Trait Roll; when you activate it in this way, it lasts a number of Rounds equal to your Fire Ring."}]}, {"id": "x_order_of_peaceful_repose", "nome": "Order of Peaceful Repose", "clanId": "monks", "livro": "Secrets of the Empire", "pagina": "244", "traco": "awareness", "honra": "4.5", "tags": ["monk", "monks_monk"], "pericias": [], "periciasTexto": "", "beneficio": "+1 Awareness", "tecnicas": [{"id": "x_order_of_peaceful_repose_emma_os_insight", "nome": "Emma-O’s Insight", "rank": 1, "descricao": "You may detect the presence of ghosts (yorei or goryo, but not gaki) by spending 10 minutes in meditation and making a roll of Meditation / Awareness at TN 25. You may do this a number of times per day equal to your Void Rank. You may call Raises on this roll to learn the following additional information (one piece of information per Raise): the ghost’s identity, its manner of death, and its connection to the mortal world. For three Raises, you can gain specific insight into what will lay the ghost to rest. (GM’s discretion as to exactly what you learn, but it will always be directly useful to resolving the ghost’s presence in the mortal world.)"}]}], "caminhos": [{"id": "x_kolat_master", "nome": "Kolat Master", "clanId": "kolat", "livro": "Enemies of the Empire", "pagina": "49", "tipo": "courtier", "tecnicaRank": "6 (can also be taken at Insight Ranks", "substitui": "Any Technique (or none) at Insight Rank", "requisitosTexto": "Must be a member of the Kolat conspiracy and chosen to lead one of the ten Sects. Cannot be Tainted or corrupted by the Nothing.", "tecnicas": [{"id": "x_kolat_master_will_of_the_master", "nome": "Will of the Master", "rank": 6, "descricao": "The ten Kolat Masters exert total control over the conspiracy. All members of their Sect are answerable to them and other Kolat will show them the greatest of respect and deference. You are considered to be Status 10 to any character who is a member of the Kolat conspiracy and who belongs to your Sect, and Status 9 to any character who is a Kolat but not of your Sect. You gain +2k0 on all Courtier and Intimidation Skill rolls."}], "requisitos": [{"campo": "courtier", "tipo": "tag", "min": "", "texto": "Escola: courtier"}]}, {"id": "x_kolat_hidden_guard", "nome": "Kolat Hidden Guard", "clanId": "kolat", "livro": "Enemies of the Empire", "pagina": "50", "tipo": "bushi", "tecnicaRank": "4", "substitui": "", "requisitosTexto": "Must be recruited by the Kolat for their Hidden Guard. Cannot be Tainted or corrupted by the Nothing.", "tecnicas": [{"id": "x_kolat_hidden_guard_tigers_do_not_fall", "nome": "Tigers Do Not Fall", "rank": 4, "descricao": "The lesson of the Hidden Guardians is that defenders must make themselves immovable, stopping all who might threaten the Hidden Temple. Any time an opponent in a skirmish declares a Maneuver against you (including the Increased Damage Maneuver), you may choose to immediately take a Free Action to spend a Void Point and negate the beneficial effects of the Maneuver. (The opponent must still make his Raises in order to hit you, but no longer gains any benefit from them.) In addition, at all times you may ignore the penalty to your Armor TN for being Grappled."}], "requisitos": [{"campo": "kolat_bushi", "tipo": "tag", "min": "", "texto": "Escola: kolat_bushi"}]}, {"id": "x_disciples_of_the_dashmar", "nome": "Disciples of the Dashmar", "clanId": "naga", "livro": "Enemies of the Empire", "pagina": "86", "tipo": "courtier", "tecnicaRank": "2", "substitui": "Naga Vedic 2", "requisitosTexto": "", "tecnicas": [{"id": "x_disciples_of_the_dashmar_friend_of_man", "nome": "Friend of Man", "rank": 2, "descricao": "The Disciples of The Dashmar attempt to learn the ways of Rokugan in order to gain new allies against their greatest enemies. You gain a bonus of +1k1 to the total of any Social Roll when trying to convince humans of your goodwill or to soothe dangerous situations with humans."}], "requisitos": [{"campo": "naga_courtier", "tipo": "tag", "min": "", "texto": "Escola: naga_courtier"}]}, {"id": "x_naga_master_bowman", "nome": "Naga Master Bowman", "clanId": "naga", "livro": "Enemies of the Empire", "pagina": "86", "tipo": "bushi", "tecnicaRank": "3", "substitui": "Naga Warrior 3", "requisitosTexto": "", "tecnicas": [{"id": "x_naga_master_bowman_arrows_from_the_ranks", "nome": "Arrows From the Ranks", "rank": 3, "descricao": "The Master Bowman is an artist with his bow, able to strike […]"}], "requisitos": [{"campo": "naga_bushi", "tipo": "tag", "min": "", "texto": "Escola: naga_bushi"}]}, {"id": "x_pearl_shapers", "nome": "Pearl Shapers", "clanId": "naga", "livro": "Enemies of the Empire", "pagina": "86", "tipo": "shugenja", "tecnicaRank": "2", "substitui": "", "requisitosTexto": "", "tecnicas": [{"id": "x_pearl_shapers_shards_of_light", "nome": "Shards of Light", "rank": 2, "descricao": "Pearl Shapers sacrifice their normal magical connections to focus their talents into fierce magical assaults. They shatter jakla pearls to release their magical energy across the battlefield. As a Complex Action, you may crush any pearl (it does not need to be a jakla spell-pearl) and spend a spell slot of any Element to make a ranged attack against a single target within 100’. Your attack roll is equal to your Agility + (twice your School Rank), keeping your Agility. This attack ignores any armor bonuses to Armor TN. The energy bolt’s damage roll is equal to your Akasha + your School Rank, keeping your Akasha."}], "requisitos": [{"campo": "naga_shugenja", "tipo": "tag", "min": "", "texto": "Escola: naga_shugenja"}]}, {"id": "x_hawk_purist", "nome": "Hawk Purist", "clanId": "ronin", "livro": "Imperial Histories 2", "pagina": "105", "tipo": "courtier", "tecnicaRank": "1", "substitui": "", "requisitosTexto": "", "tecnicas": [{"id": "x_hawk_purist_grace_from_the_shadows", "nome": "Grace From the Shadows", "rank": 1, "descricao": "The ronin who fancy themselves members of the Hawk Clan rely on a mix of popular opinion, bluff, and intimidation to make themselves part of a greater movement and gain favor with others. Any time you are speaking with another person, you may assert your membership in the “Hawk Clan” and try to convince him to treat you with 103 corresponding respect. This is a Contested Awareness roll (and is a Complex Action if Actions are relevant). If you succeed in the roll, your opponent will treat you as if your Status is one Rank greater than it is. (Thus a normal Status 0 ronin will instead be treated as though he is Status 1.)"}], "tags": ["historica"], "requisitos": [{"campo": "ronin_courtier", "tipo": "tag", "min": "", "texto": "Escola: ronin_courtier"}]}, {"id": "x_order_of_the_stone_crab", "nome": "Order of the Stone Crab", "clanId": "crab", "livro": "Imperial Histories 2", "pagina": "129", "tipo": "bushi", "tecnicaRank": "4", "substitui": "Any Bushi School (of appropriate clan)", "requisitosTexto": "Must have an Honor Rank lower than 5.0", "tecnicas": [{"id": "x_order_of_the_stone_crab_scorn_the_weak", "nome": "Scorn the Weak", "rank": 4, "descricao": "Members of the Order of Stone are known for their particular relish in crushing those weaker than themselves, exploiting any weaknesses they might find. When attacking human opponents, you gain a bonus of +1k1 on your attack rolls for each Physical Disadvantage they possess."}], "tags": ["historica"], "requisitos": [{"campo": "bushi", "tipo": "tag", "min": "", "texto": "Escola: bushi"}]}, {"id": "x_chrysanthemum_conspirator", "nome": "Chrysanthemum Conspirator", "clanId": "imperial", "livro": "Imperial Histories 2", "pagina": "129", "tipo": "courtier", "tecnicaRank": "2", "substitui": "Any Bushi or Courtier School at Rank 2", "requisitosTexto": "You must have the Disadvantage Dark Secret (Rebel)", "tecnicas": [{"id": "x_chrysanthemum_conspirator_no_course_but_one", "nome": "No Course But One", "rank": 2, "descricao": "Those who conspire against the Steel Chrysanthemum 127 place greater value on Honor than on social status or Imperial authority. You gain a Free Raise on any attack The Reign of The STeel ChRySanThemum roll made against an opponent whose Status Rank exceeds their Honor Rank."}], "tags": ["historica"], "requisitos": [{"campo": "courtier", "tipo": "tag", "min": "", "texto": "Escola: courtier"}]}, {"id": "x_the_unbroken", "nome": "The Unbroken", "clanId": "ronin", "livro": "Imperial Histories 2", "pagina": "221", "tipo": "bushi", "tecnicaRank": "3", "substitui": "", "requisitosTexto": "Lore: Shadowlands 3 c Special: Must have at least one Rank of Taint and find a way to learn the Unbroken Technique.", "tecnicas": [{"id": "x_the_unbroken_the_unbroken", "nome": "The Unbroken", "rank": 3, "descricao": "The students of the Unbroken learn to set the impurity within themselves against the impurity of their foes. When you are fighting a Shadowlands creature or one of the Lost, you may add your Taint Rank in unkept dice to your attack rolls. Each time you do this you gain three additional Point of Taint. However, any time you singlehandedly kill a Shadowlands creature or one of the Lost, you may spend a Void Point to permanently lose one Point of Taint. If you ever single-handedly kill an extremely powerful Shadowlands foe, you may spend a Void Point as a Free Action to make a Contested Earth roll against the Earth of the foe you have slain. With a success, you immediately purge all the Taint from your body – and thereafter lose the ability to perform this Technique. Ultimately, it is the GM’s discretion whether a particular foe is powerful enough to trigger the more potent aspects of the Unbroken Technique. Examples of creatures which could trigger the effect include major oni, any of the Onisu, or a Lost of at least two Insight Ranks higher."}], "tags": ["historica"], "requisitos": [{"campo": "ronin_bushi", "tipo": "tag", "min": "", "texto": "Escola: ronin_bushi"}]}, {"id": "x_second_gozoku_agent", "nome": "Second Gozoku Agent", "clanId": "imperial", "livro": "Imperial Histories 2", "pagina": "248", "tipo": "courtier", "tecnicaRank": "2", "substitui": "Any School 2", "requisitosTexto": "Honor Rank of 4 or less. Must have Obligation to the Second Gozoku or its leader.", "tecnicas": [{"id": "x_second_gozoku_agent_to_shield_the_empress", "nome": "To Shield the Empress", "rank": 2, "descricao": "The members of the Second Gozoku believe they do what they must to protect the Empress from the harsh realities of rule, and this philosophy in turn protects them from the worst excesses they must embrace. Whenever you take an action that would result in a loss of Honor, if by taking this action you spare Honor or Glory loss to someone of higher Status Rank than you, the loss is halved (rounded down)."}], "tags": ["historica"], "requisitos": [{"campo": "courtier", "tipo": "tag", "min": "", "texto": "Escola: courtier"}]}, {"id": "x_serpent_hunter", "nome": "Serpent Hunter", "clanId": "dragon", "livro": "Imperial Histories 2", "pagina": "291", "tipo": "bushi", "tecnicaRank": "Variable", "substitui": "Any Bushi School Rank that awards an", "requisitosTexto": "Lore: Naga 3, Hunting 3", "tecnicas": [{"id": "x_serpent_hunter_blood_of_the_serpent", "nome": "Blood of the Serpent", "rank": 1, "descricao": "The warriors who have made it their duty to hunt the feral Nagah of the Colonies excel in the execution of their prey. You may make attacks as a Simple Action instead of a Complex Action when wielding melee weapons with the Samurai quality. When facing a Naga opponent of any kind, however, you may make attacks as a Simple Action with any weapon."}], "tags": ["historica"], "requisitos": [{"campo": "bushi", "tipo": "tag", "min": "", "texto": "Escola: bushi"}]}, {"id": "x_gozoku_agent", "nome": "Gozoku Agent", "clanId": "imperial", "livro": "Imperial Histories", "pagina": "69", "tipo": "courtier", "tecnicaRank": "2", "substitui": "Any Basic School at Rank 2", "requisitosTexto": "Forbidden Knowledge (Gozoku)", "tecnicas": [{"id": "x_gozoku_agent_overwhelming_presence", "nome": "Overwhelming Presence", "rank": 2, "descricao": "The agents of the Gozoku conspiracy were feared for the power they could bring to bear on any who dared oppose them in court. You may add your rank in the Intimidate Skill to the total of all Social Skill Rolls you make against individuals who are not members of the Gozoku."}], "tags": ["historica"], "requisitos": [{"campo": "courtier", "tipo": "tag", "min": "", "texto": "Escola: courtier"}]}, {"id": "x_brotherhood_spy", "nome": "Brotherhood Spy", "clanId": "monks", "livro": "Imperial Histories", "pagina": "71", "tipo": "monk", "tecnicaRank": "2", "substitui": "Any Brotherhood Monk School at Rank 2", "requisitosTexto": "Lore: Theology 3", "tecnicas": [{"id": "x_brotherhood_spy_bearing_the_emperors_shame", "nome": "Bearing the Emperor’s Shame", "rank": 2, "descricao": "Acts committed in the Emperor’s name are done with cercertainty that can overcome the shame associated with them, even when they are against one’s personal code of honor. When acting against a known or suspected agent of the Gozoku conspiracy, or when acting on orders from a legitimate Imperial authority, you gain a Free Raise on all Stealth and Deceit Skill Rolls. You lose no Honor for these Skill Rolls when made under these specific circumstances."}], "tags": ["historica"], "requisitos": [{"campo": "monk", "tipo": "tag", "min": "", "texto": "Escola: monk"}]}, {"id": "x_kenburo_s_way", "nome": "Kenburo's Way", "clanId": "imperial", "livro": "Imperial Histories", "pagina": "123", "tipo": "bushi", "tecnicaRank": "4", "substitui": "Any bushi at Rank 4", "requisitosTexto": "Intimidation 5, Iaijutsu 5. Must be a student of the Ruby Dojo.", "tecnicas": [{"id": "x_kenburo_s_way_the_butchers_gaze", "nome": "The Butcher’s Gaze", "rank": 4, "descricao": "During an iaijutsu duel, before Assessment rolls are made, you may spend a Void Point to take a Free Action and make a Contested Intimidation/Willpower roll against your opponent. (This is considered a Fear effect for the purpose of abilities and mechanics that resist Fear.) If you win the Contested Roll, your opponent’s dice do not explode on his Assessment and Focus rolls for this duel."}], "tags": ["historica"], "requisitos": [{"campo": "bushi", "tipo": "tag", "min": "", "texto": "Escola: bushi"}]}, {"id": "x_people_s_legionnaire", "nome": "People's Legionnaire", "clanId": "imperial", "livro": "Imperial Histories", "pagina": "125", "tipo": "bushi", "tecnicaRank": "1", "substitui": "", "requisitosTexto": "", "tecnicas": [{"id": "x_people_s_legionnaire_unity_of_purpose", "nome": "Unity of Purpose", "rank": 1, "descricao": "The People’s Legionnaires drill endlessly, learning to act in unison on the battlefield. After Initiative is rolled at the beginning of a skirmish, you may take a Free Action to lower your Initiative score to match that of an ally who is also trained in this technique. If you and an ally with the same Initiative attack the same opponent, you each gain a +1k0 bonus on your attack roll for each such ally striking the same foe. The maximum number of bonus dice you can 123 gain on a single attack roll is equal to your Insight Rank +1."}], "tags": ["historica"], "requisitos": [{"campo": "imperial_bushi", "tipo": "tag", "min": "", "texto": "Escola: imperial_bushi"}]}, {"id": "x_scorpion_loyalist", "nome": "Scorpion Loyalist", "clanId": "scorpion", "livro": "Imperial Histories", "pagina": "149", "tipo": "courtier", "tecnicaRank": "2", "substitui": "Any Scorpion School at Rank 2", "requisitosTexto": "Courtier 4 (courtiers), Spellcraft 4 (shugenja), one Weapon Skill at 4 (bushi or ninja) Chapter Five", "tecnicas": [{"id": "x_scorpion_loyalist_no_matter_the_cost", "nome": "No Matter the Cost", "rank": 2, "descricao": "Those Scorpion agents who embrace their duties to the fullest strike viciously at the clan’s many enemies without regard for the constraints of honor, custom, or propriety. You may sacrifice points of Honor up to a maximum number equal to your Scorpion School Rank to gain a bonus on one roll made against non-Scorpion opponents. Bushi and ninja gain a bonus of +1k0 per point of Honor on attack rolls, courtiers gain the same bonus on Contested Social Skill Rolls, and shugenja gain the bonus on spell-casting rolls made on Air spells (only) targeting those opponents."}], "tags": ["historica"], "requisitos": [{"campo": "courtier", "tipo": "tag", "min": "", "texto": "Escola: courtier"}]}, {"id": "x_kitsuki_justicar", "nome": "Kitsuki Justicar", "clanId": "dragon", "livro": "Imperial Histories", "pagina": "151", "tipo": "bushi", "tecnicaRank": "3", "substitui": "Kitsuki Investigator 3", "requisitosTexto": "Iaijutsu 4, Investigation 4", "tecnicas": [{"id": "x_kitsuki_justicar_the_purity_of_justice", "nome": "The Purity of Justice", "rank": 3, "descricao": "A justicar is a master of both the hunt and the kill. You may add your Investigation Skill Rank to the total of any Assessment roll made as part of an iaijutsu duel. You also gain a bonus of +1k0 on all Focus and Strike rolls made against an opponent who has been decreed guilty of a crime by an Imperial or Dragon Clan authority higher than you. Finally, you gain a bonus of +1k0 to any Hunting or Investigation rolls made to hunt such guilty targets."}], "tags": ["historica"], "requisitos": [{"campo": "dragon_bushi", "tipo": "tag", "min": "", "texto": "Escola: dragon_bushi"}]}, {"id": "x_three_man_alliance_soldier", "nome": "Three Man Alliance Soldier", "clanId": "ronin", "livro": "Imperial Histories", "pagina": "152", "tipo": "bushi", "tecnicaRank": "2", "substitui": "Tsuruchi Archer 2, Tsuruchi Bounty", "requisitosTexto": "Battle 2", "tecnicas": [{"id": "x_three_man_alliance_soldier_stand_against_oppression", "nome": "Stand Against Oppression", "rank": 2, "descricao": "The scions of the Minor Clans are not intimidated by their more influential detractors among the Great Clans. Far from it, they are inspired to greatness by their hardships. When facing an opponent with a higher Glory Rank than you, you may spend a Void Point to gain bonus unkept dice on your attack roll equal to the difference in your respective Glory Ranks. You may not gain more bonus dice than your Minor Clan School Rank from this Technique."}], "tags": ["historica"], "requisitos": [{"campo": "ronin_bushi", "tipo": "tag", "min": "", "texto": "Escola: ronin_bushi"}]}, {"id": "x_tsume_pikemen", "nome": "Tsume Pikemen", "clanId": "ronin", "livro": "Imperial Histories", "pagina": "279", "tipo": "bushi", "tecnicaRank": "3", "substitui": "", "requisitosTexto": "Spears 3+, Polearms 3+, Honor Rank 3 or higher c Special Notes: Within the Heroes of Rokugan setting, this Technique is normally only available", "tecnicas": [{"id": "x_tsume_pikemen_wall_of_pikes", "nome": "Wall of Pikes", "rank": 3, "descricao": "The Tsume Pikemen are taught to use defensive tactics, luring the enemy into a charge and then impaling them on their spears. While you are in the Defense posture and wielding a spear or polearm, immediately after an opponent makes a melee attack against you or one of your allies within ten feet (whether or not the attack hit), you may spend a Void Point in order to take a Free Action to attack that opponent with your spear/polearm. You may also use this Technique in the Full Defense posture, but making the attack will require spending two Void Points instead of one."}], "tags": ["historica"], "requisitos": [{"campo": "ronin_bushi", "tipo": "tag", "min": "", "texto": "Escola: ronin_bushi"}]}, {"id": "x_the_thousand", "nome": "The Thousand", "clanId": "ronin", "livro": "Secrets of the Empire", "pagina": "237", "tipo": "bushi", "tecnicaRank": "2", "substitui": "", "requisitosTexto": "Iaijutsu 4, Void 3 Technique: Tamedaore’s Secret", "tecnicas": [{"id": "x_the_thousand_tamedaores_secret", "nome": "Tamedaore’s Secret", "rank": 2, "descricao": "While you are in the Center Stance and on the Round immediately after you leave the Center Stance, you gain a bonus to your Armor TN equal to 2x your Void Ring."}], "requisitos": [{"campo": "ronin_bushi", "tipo": "tag", "min": "", "texto": "Escola: ronin_bushi"}]}, {"id": "x_order_of_isashi", "nome": "Order of Isashi", "clanId": "ronin", "livro": "Secrets of the Empire", "pagina": "237", "tipo": "shugenja", "tecnicaRank": "3", "substitui": "Ronin shugenja 3 (any ronin shugenja", "requisitosTexto": "", "tecnicas": [{"id": "x_order_of_isashi_isashis_mercy", "nome": "Isashi’s Mercy", "rank": 3, "descricao": "The Order of Isashi devotes itself to healing the sick and the injured. You gain a +1k0 bonus to Medicine Skill rolls and a Free Raise when casting any spell that heals Wounds or cures illness."}], "requisitos": [{"campo": "shugenja", "tipo": "tag", "min": "", "texto": "Escola: shugenja"}]}, {"id": "x_order_of_the_five_weapons", "nome": "Order of the Five Weapons", "clanId": "ronin", "livro": "Secrets of the Empire", "pagina": "237", "tipo": "shugenja", "tecnicaRank": "4", "substitui": "Ronin shugenja 4 (any ronin shugenja", "requisitosTexto": "", "tecnicas": [{"id": "x_order_of_the_five_weapons_ekuros_weapons", "nome": "Ekuro’s Weapons", "rank": 4, "descricao": "The founder of this order perfected the use of weapons summoned from the Elemental kami. You may cast any of the four Elemental Weapon spells as a Simple Action (rather than a Complex Action). You may spend a Void Point (as a Free Action) to be able to attack with these summoned weapons as a Simple Action for a number of Rounds equal to your Insight Rank. If you have the Ishiken-do Advantage, you may learn the secret spell “Dart of Void.”"}], "requisitos": [{"campo": "shugenja", "tipo": "tag", "min": "", "texto": "Escola: shugenja"}]}, {"id": "x_ichiro_pass_warden", "nome": "Ichiro Pass Warden", "clanId": "badger", "livro": "Secrets of the Empire", "pagina": "238", "tipo": "bushi", "tecnicaRank": "3", "substitui": "Ichiro Bushi 3", "requisitosTexto": "Strength 4, Spears 4, Athletics 4.", "tecnicas": [{"id": "x_ichiro_pass_warden_hold_the_passes", "nome": "Hold the Passes", "rank": 3, "descricao": "Your range with hand-hurled missiles is doubled, and you add +1k0 to damage rolls with thrown weapons; if the weapon is a nage-yari or a rock, the bonus is +1k1 instead."}], "requisitos": [{"campo": "badger_bushi", "tipo": "tag", "min": "", "texto": "Escola: badger_bushi"}]}, {"id": "x_dragonfly_advisor", "nome": "Dragonfly Advisor", "clanId": "dragonfly", "livro": "Secrets of the Empire", "pagina": "239", "tipo": "courtier", "tecnicaRank": "3", "substitui": "Tonbo Shugenja 3", "requisitosTexto": "Intelligence 3, Meditation 5", "tecnicas": [{"id": "x_dragonfly_advisor_seeing_the", "nome": "Seeing the Pattern", "rank": 3, "descricao": "The Dragonfly Advisors are trained to understand all the patterns of cause and effect around them, letting them perceive the potential consequences of their actions. You gain a +2k0 bonus to all Divination and Etiquette Skill Rolls."}], "requisitos": [{"campo": "dragonfly_courtier", "tipo": "tag", "min": "", "texto": "Escola: dragonfly_courtier"}]}, {"id": "x_ox_clan_vigilant", "nome": "Ox Clan Vigilant", "clanId": "ox", "livro": "Secrets of the Empire", "pagina": "240", "tipo": "bushi", "tecnicaRank": "4", "substitui": "Morito Bushi 4", "requisitosTexto": "Investigation 5", "tecnicas": [{"id": "x_ox_clan_vigilant_seek_the_guilty", "nome": "Seek the Guilty", "rank": 4, "descricao": "The Ox Vigilants are trained to root out lawbreakers and conspirators by seeing through their deceptions and tricks, finding their underlying moral weakness and using it against them. When investigating someone for possible lawbreaking or Kolat activity, you may make a Contested Roll of your Investigation (Interrogation) / Perception against the target’s Sincerity (Deceit) / Awareness. If you succeed (and the target is actually guilty – GM’s judgment), you gain a +1k1 bonus to all Intimidation rolls and attack rolls against that target for the next 24 hours."}], "requisitos": [{"campo": "ox_bushi", "tipo": "tag", "min": "", "texto": "Escola: ox_bushi"}]}, {"id": "x_suzume_storyteller", "nome": "Suzume Storyteller", "clanId": "sparrow", "livro": "Secrets of the Empire", "pagina": "241", "tipo": "courtier", "tecnicaRank": "2", "substitui": "Suzume Bushi 2", "requisitosTexto": "Perform: Storytelling 3, Precise Memory", "tecnicas": [{"id": "x_suzume_storyteller_the_heart_of_the_story", "nome": "The Heart of the Story", "rank": 2, "descricao": "The Suzume Storyteller can use a skillfully crafted story to make virtually any point he wishes. When making a Courtier Skill roll, you may spend a Void Point to add your Perform: Storytelling Skill Rank to the total."}], "requisitos": [{"campo": "sparrow_courtier", "tipo": "tag", "min": "", "texto": "Escola: sparrow_courtier"}]}, {"id": "x_tortoise_killer", "nome": "Tortoise Killer", "clanId": "tortoise", "livro": "Secrets of the Empire", "pagina": "241", "tipo": "bushi", "tecnicaRank": "3", "substitui": "Tortoise Smuggler 3", "requisitosTexto": "Agility 3, Stealth 4, any two Weapon Skills at 4", "tecnicas": [{"id": "x_tortoise_killer_the_poisoned_frog", "nome": "The Poisoned Frog", "rank": 3, "descricao": "The Tortoise Killers are trained to dispose of their targets with whatever weapon comes to hand, while maintaining the outward appearance of an ordinary sailor or soldier. Once per opponent per skirmish, when making an attack roll you may spend a Void Point to cause your Raises for damage on that roll to award +1k1 rather than +1k0 to damage. You may never take more Raises than your Void Rank when using this Technique."}], "requisitos": [{"campo": "tortoise_bushi", "tipo": "tag", "min": "", "texto": "Escola: tortoise_bushi"}]}, {"id": "x_satoshi_s_legacy", "nome": "Satoshi's Legacy", "clanId": "phoenix", "livro": "Secrets of the Empire", "pagina": "242", "tipo": "bushi", "tecnicaRank": "4", "substitui": "Miya Herald 4", "requisitosTexto": "Kenjutsu 5", "tecnicas": [{"id": "x_satoshi_s_legacy_fire_and_ice", "nome": "Fire and Ice", "rank": 4, "descricao": "The Satoshi vassal family teaches an aggressive fighting style derived from their founder’s training with the Matsu family. You may make attacks as Simple Actions when you are in the Full Attack stance."}], "requisitos": [{"campo": "phoenix_bushi", "tipo": "tag", "min": "", "texto": "Escola: phoenix_bushi"}]}, {"id": "x_seppun_hidden_guard", "nome": "Seppun Hidden Guard", "clanId": "imperial", "livro": "Secrets of the Empire", "pagina": "243", "tipo": "shugenja", "tecnicaRank": "3", "substitui": "Seppun Shugenja 3", "requisitosTexto": "Must be chosen for service in the Hidden Guard", "tecnicas": [{"id": "x_seppun_hidden_guard_harmony_in_all", "nome": "Harmony in All", "rank": 3, "descricao": "The Hidden Guard are tasked with warding and protecting the Emperor, the Imperial family, and their possessions and holdings. You gain a Free Raise with all spells that have the Wards or Defense properties."}], "requisitos": [{"campo": "imperial_shugenja", "tipo": "tag", "min": "", "texto": "Escola: imperial_shugenja"}]}, {"id": "x_susumu_courtier", "nome": "Susumu Courtier", "clanId": "spider", "livro": "The Imperial Archives", "pagina": "96", "tipo": "courtier", "tecnicaRank": "1", "substitui": "Daigotsu Courtier 1", "requisitosTexto": "", "tecnicas": [{"id": "x_susumu_courtier_the_way_of_victory", "nome": "The Way of Victory", "rank": 1, "descricao": "Susumu courtiers learn how to use the Code of Shourido to strengthen their own efforts in court and to ferret out and intensify the selfish impulses of other samurai. You gain the Student of Shourido Advantage for free (if for some reason you already possess this Advantage, the Experience Point cost is refunded). After a few minutes’ conversation with another samurai, you may make a Contested Social roll of your Temptation/Willpower against your opponent’s Etiquette/Willpower; with a success, you detect whether the character has any personal flaws which would make him amenable to the appeal of Shourido. (You do not learn the specific nature of the flaws, merely whether they exist. From the GM’s viewpoint, in addition to role-played flaws, this could also detect the presence of Disadvantages such as Brash, Compulsion, Consumed, Contrary, Disbeliever, Driven, Failure of Bushido, Cast Out, Dark Paragon, Forbidden Knowledge, and Perceived Honor.)"}], "requisitos": [{"campo": "spider_courtier", "tipo": "tag", "min": "", "texto": "Escola: spider_courtier"}]}, {"id": "x_scorpion_maskmaker", "nome": "Scorpion Maskmaker", "clanId": "scorpion", "livro": "The Imperial Archives", "pagina": "96", "tipo": "courtier", "tecnicaRank": "2", "substitui": "Bayushi Courtier 2, Soshi Shugenja 2,", "requisitosTexto": "", "tecnicas": [{"id": "x_scorpion_maskmaker_conceal_the_eyes", "nome": "Conceal the Eyes", "rank": 2, "descricao": "The artisans who craft masks for Scorpion samurai know how to direct attention away from the wearer’s face (and any social cues it might reveal) to the distracting mask itself. Once every three months, you may craft a mask which is especially effective at concealing thoughts and emotions; this mask matches the abilities of the Inheritance Advantage with the Sincerity Skill (L5R 4th Edition Core rulebook, page 150-151), and creating it requires two Raises on your Craft: Maskmaking roll. Also, your experience at using masks to conceal emotions teaches you how to read others’ intentions without relying on facial expressions. You gain a +2k0 bonus on any Social Skill roll to detect falsehood or concealed intentions in others."}], "requisitos": [{"campo": "scorpion_courtier", "tipo": "tag", "min": "", "texto": "Escola: scorpion_courtier"}]}], "feiticos": [{"id": "x_master_clouds_eyes", "nome": "Master Cloud’s Eyes", "elemento": "air", "mastery": "3", "area": "One target creature", "alcance": "50'", "duracao": "2 minutes", "raises": "Duration (+1 minute)", "descricao": "The kami can share the vision of others. You may view the world through the eyes of another living creature within your line of sight. You only see, you do not experience any of the target’s other senses, and you have no control over what the target looks at. For the duration of this spell, any Perceptionbased rolls you make for your own body suffer a –2k2 penalty, due to the […]", "livro": "Enemies of the Empire", "pagina": "51"}, {"id": "x_the_mirrors_smile", "nome": "The Mirror’s Smile", "elemento": "water", "mastery": "4", "area": "Caster", "alcance": "Touch", "duracao": "1 Day", "raises": "Special (cast after only seeing the target’s face once, 4 Raises)", "descricao": "You call on the Water kami to make your face become that of another person. This is not an illusion but an actual change to the flesh and bone, re-molding your face to match that of the other person. This is a painful experience and it takes several minutes for the kami to complete the re-shaping. Normally, casting this spell requir […]", "livro": "Enemies of the Empire", "pagina": "51"}, {"id": "x_the_world_is_truth", "nome": "The World Is Truth", "elemento": "air", "mastery": "6", "area": "One target person", "alcance": "Touch", "duracao": "1 month", "raises": "Duration (1 additional month per 3 Raises)", "descricao": "This secret spell is an important element in the Kolat’s methods for creating sleeper agents, but even when used by itself it is a potent weapon in the conspiracy’s arsenal. The Kolat typically use this spell when it is vitally necessary to conceal their operations without actually killing someone – typically because the person in question is too important to be easily disposed of. Casting this spell requires the caster to hold the target by the head and focus on him for 8 hours uninterrupted; typically, the target will be bound to prevent interruptions. If contact with the target is broken for more than 3 minutes the spell will fail. At the end of 8 hours the shugenja makes a Contested Insight/ Air roll against the target. If the shugenja wins the roll, the target’s thoughts and memories are rewritten and rearranged in whatever way the caster prefers.", "livro": "Enemies of the Empire", "pagina": "51"}, {"id": "x_the_pearl_of_cleansing_light", "nome": "The Pearl of Cleansing Light", "elemento": "earth", "mastery": "1", "area": "50’", "alcance": "Self", "duracao": "Concentration", "raises": "Area of Effect (+10’ per Raise), Special (Willpower TN +5 per 2 Raises)", "descricao": "A light shines upon the caster, illuminating the ground around him. Creatures with at least 1 full rank of Shadowlands Taint or Shadow corruption must make a Willpower roll at TN 20 or immediately run away from the caster. The victims will not stop running until they leave the area of effect. The creature must make the same Willpower roll again if it steps back into […]", "livro": "Enemies of the Empire", "pagina": "87", "tags": ["pearl", "naga"]}, {"id": "x_the_pearl_of_defense", "nome": "The Pearl of Defense", "elemento": "earth", "mastery": "2", "area": "1 target", "alcance": "5’ or touch", "duracao": "5 Rounds", "raises": "Duration (+1 Round per Raise)", "descricao": "The target gains scales of steel, preparing him for the enemies that he may face. The target gains Reduction 2, with an additional Reduction 3 against creatures of the Nothing and the Shadowlands (for a total of Reduction 5 against those foes).", "livro": "Enemies of the Empire", "pagina": "87", "tags": ["pearl", "naga"]}, {"id": "x_the_pearl_of_judgment", "nome": "The Pearl of Judgment", "elemento": "air", "mastery": "4", "area": "1 target", "alcance": "Touch", "duracao": "1 minute", "raises": "Duration (+1 minute per Raise), Area of Effect (+1 target per Raise)", "descricao": "Naga Vedics are the arbiters of their great cities, but they occasionally require aid when the Akasha cannot determine the truth of the matter at first glance. The Pearl of Judgment allows the caster to link to a single target and achieve a state of complete communication. The caster chooses one willing target for the effects of the Pearl of Judgment. If the target is a Naga, the caster may ask the target one yes or no question and know if the answer is truthful. If the target is not a Naga, the target can feel the weight and breadth of the Akasha for one brief moment. The caster gains a +3k1 bonus on all Courtier rolls with the target for the duration of the spell. However, the caster does not receive insight into the target’s truthfulness. The sheer size of the Akasha may be disorienting to those who are not prepared for its power, and sometimes leaves the target senseless for many minutes (GM’s discretion).", "livro": "Enemies of the Empire", "pagina": "87", "tags": ["pearl", "naga"]}, {"id": "x_the_pearl_of_movement", "nome": "The Pearl of Movement", "elemento": "water", "mastery": "1", "area": "1 target", "alcance": "25’", "duracao": "5 minutes", "raises": "Duration (+5 minutes per two Raises)", "descricao": "The Naga pride themselves on their mastery in the element of Water. The jakla can use the Pearl of Movement to instantly increase a Naga’s swimming speed, making him a formidable foe in the underwater Naga cities. The target’s Water Ring is considered to be 2 Ranks higher for the purposes of movement while swimming.", "livro": "Enemies of the Empire", "pagina": "87", "tags": ["pearl", "naga"]}, {"id": "x_the_pearl_of_swift_retribution", "nome": "The Pearl of Swift Retribution", "elemento": "fire", "mastery": "3", "area": "25’ radius sphere around caster", "alcance": "Self", "duracao": "Concentration", "raises": "Damage (+1k0 per two Raises)", "descricao": "The bow remains the most utilized weapon of the Naga, and the jakla recognize its importance within their culture. The Pearl of Swift Retribution was crafted to aid their efforts in battle. When the jakla focuses his attentions through this pearl, he crafts a spherical bubble of translucent energy. When Naga inside the bubble shoot arrows through its surface, the arrows transform into bolts of energy (much like the blasts of light unleashed by the Pearl Shapers). These arrows ignore Armor TN bonuses granted by the target’s armor, and gain a +0k1 damage bonus. The jakla may not move while he is casting and maintain- […]", "livro": "Enemies of the Empire", "pagina": "87", "tags": ["pearl", "naga"]}, {"id": "x_the_white_pearl", "nome": "The White Pearl", "elemento": "all", "mastery": "5", "area": "", "alcance": "", "duracao": "", "raises": "", "descricao": "Ring/Mastery: Air/Earth/Fire/Water 5 The White Pearl is one of the greatest treasures of the Naga civilization. This pearl resides in a place of honor in the most important Naga city of the time. Those who view it swear they can see the whole of the Akasha within its depths. No one knows the true strength of the White Pearl and it has remained unused except for the greatest of crises. The Jakla’s Pearls and Spell Selection N aga jakla do not interact with the elemental kami in the same way as humans, so jakla may not use the Commune spell. The Naga manipulate the elements by focusing them through the power inherent in their pearls, and do not speak to the kami. The Naga cannot cast Void spells, for they cannot channel an element they cannot touch. Maho spells are also forbidden to the Naga, since they cannot gain the Shadowlands Taint. A Naga jakla can cast any other Elemental spell as long as he has the appropriate pearl that holds the power of the spell within. Each pearl can cast a single spell from its Element of equivalent or lower Mastery Level. Thus a Naga with a Water 2 pearl can choose any one Water spell of Mastery Level 1 or 2 which the pearl can cast. Pearl magic spells are otherwise cast in the same mechanical way as normal elemental spells, with a Spell Casting Roll based on the jakla’s Ring and School Rank, and using up spell slots in the normal manner. Naga spells do not require scrolls and do not have to be spoken aloud, but the Naga must be able to touch and focus upon the appropriate pearl in order to cast the spell. A jakla character gains three new pe […]", "livro": "Enemies of the Empire", "pagina": "87", "tags": ["pearl", "naga"]}, {"id": "x_blessed_wind_of_lady_sun", "nome": "Blessed Wind of Lady Sun", "elemento": "air", "mastery": "2", "area": "10 square feet around caster", "alcance": "Self", "duracao": "Concentration", "raises": "Area (5 square feet)", "descricao": "While the Crane would go without an organized shugenja family or order until the Asahina would be founded centuries after the clan’s founding, a few of Doji’s followers had a talent for speaking with the kami. They focused on the arts of peace and meditation, and this spell was one of their first attempts to bring the harmony of the Elements to a samurai. While this spell is active, all rolls based on Void and Awareness gain a +1k0 bonus when made within the area of effect, and all hostile actions suffer a -1k0 penalty. Hostile actions based on Awareness (such as threatening someone with Intimidation) suffer a -2k0 penalty instead of the previous, self-negating, effects. The caster of this spell may use the Meditation Skill without breaking the concentration required to maintain it.", "livro": "Imperial Histories 2", "pagina": "53"}, {"id": "x_elemental_crucible", "nome": "Elemental Crucible", "elemento": "fire", "mastery": "1", "area": "", "alcance": "Touch", "duracao": "Instantaneous", "raises": "Area (1 cubic foot)", "descricao": "A precursor to the secret elemental transformation spell that Agasha would devise later, this spell stripped a touched object of unwanted Elements, leaving a single Element behind. When the spell is cast, the caster declares a single Element (except Void) that he wishes to reveal. The rest of the elements are destroyed in a fashion appropriate to their type (water boils out, earth crumbles, fire dissipates, air creates a vacuum), leaving behind the desired element. The loss of certain elements may have different effects, based on the item. A lack of water means an item might lose any pliability or movement, a lacking earth means the object becomes brittle, and so on. The form of this remaining element is left to the GM, and the GM may rule that certain objects (such as a katana) have too many closely intertwined elements to be affected by this spell. This spell may only affect a single object of 1 cubic foot in total size, plus an additional cubic foot per Raise.", "livro": "Imperial Histories 2", "pagina": "53"}, {"id": "x_judgment_of_yomi", "nome": "Judgment of Yomi", "elemento": "water", "mastery": "2", "area": "One individual", "alcance": "50’", "duracao": "Concentration (Special)", "raises": "Range (10’), Targets (+1)", "descricao": "While the Lion are known for practically refusing to bring shugenja to battle in most circumstances, the first human Kitsu devised several spells to protect them in combat during the tumultuous time of the early Empire. This spell is one such way in which the Kitsu believed that the spirits of those who came before would be ready to judge and punish the unworthy. When this spell is cast, the target immediately feels the gaze of the Realm of Blessed Ancestors upon them - indeed, the Kitsu was able to bring the attention of the restful dead upon their enemies practically at will. Those who are judged unworthy find their strength sapped and themselves forced away from the caster. If the target is human, for every Social or Spiritual Disadvantage the victim possesses, he suffers a -1k0 on all physical Skill checks. In addition, he must make an Honor check at a TN of 20 or find he cannot move any closer to the caster than the maximum range of this spell (but is not pushed back if he is already closer). There are no other penalties for failing this Honor check. The penalties of this spell last for a full Round, or for as long as the caster maintains concentration on its effects.", "livro": "Imperial Histories 2", "pagina": "53"}, {"id": "x_balance_in_all", "nome": "Balance in All", "elemento": "void", "mastery": "2", "area": "Self", "alcance": "Self", "duracao": "One Round", "raises": "Duration (One Round)", "descricao": "One of the most powerful lessons the Isawa took from the Tao of Shinsei was a deeper understanding of the connection between the various Elements. With this insight, their gifted Void shugenja were able to manipulate these connections to further their spellcasting potential before exhausting themselves. Once this spell is cast, you may cast spells of any given Element as if they were a different Element - affecting the Ring that is used to roll it, the number of spells of that Element you may cast per day, and any relevant Affinity, Deficiency, or other mechanics. The GM should feel free to interpret how using different Elements for a spell might affect the spell in various ways - a Katana of Fire cast as an Air spell, for example, might create a blade of nearly invisible, burning wind.", "livro": "Imperial Histories 2", "pagina": "53"}, {"id": "x_heart_betrays_eyes", "nome": "Heart Betrays Eyes", "elemento": "air", "mastery": "2", "area": "One individual", "alcance": "50’", "duracao": "Three rounds", "raises": "Duration (One round), Range (10’)", "descricao": "An early attempt to use the magic of Air to gain advantage against the unwary, the Soshi family devised this spell to delay those who had stumbled upon their Clan’s machinations, or to cover their tracks. Once this spell is cast, the next thing the victim sees that seems unusual or out of the ordinary instead appears completely normal to them. This does not change the victim’s reaction, it simply clouds their perceptions such that they believe they are seeing something they expect to see, or at least something not unusual at all. A guard under the influence of this spell, for example, might walk through his regular patrol and see an undisturbed room rather than the ransacked mess a thief had left behind. This spell only affects vision, so the victim is allowed an Investigation roll against a TN of the caster’s Air x 5 if there are subtle clues betraying the illusion (such as stepping on a bit of spilled sake). Any major clues (such chapter Two as screaming coming from the changed scene or tripping over an object covered by the illusion) ends the effect immediately.", "livro": "Imperial Histories 2", "pagina": "53"}, {"id": "x_command", "nome": "Command (Iuchi)", "elemento": "all", "mastery": "1", "area": "1 cubic foot of affected material", "alcance": "30’", "duracao": "Permanent", "raises": "Area (+1 cubic foot), Range (+10’), Special", "descricao": "A controversial spell devised by Iuchi during the Ki-Rin Clan’s exile, this spell eschews the traditional method of entreating and praying to the elemental spirits in favor of commanding the Elements directly. Outside of Rokugan, where the kami were quiet or altogether silent, this spell was used to great effect, but inside the Empire, it brings the wrath of the spirits down upon the unwary. This spell can be cast in any of the four standard elements. Once this spell is cast, the caster may create a quantity of the element in question (per the Summon spell) or affect the shape of an existing quantity of that element. A stone table, for example, could be commanded to break, or change its shape so that it is round instead of square. The GM may require Raises for more complex uses of this spell (such as attempting to create a complex shape out of fire). Using this spell within Rokugan (or anywhere that the elemental kami exist) can be dangerous, as it forces the will of the caster over the spirits rather than beseeching their aid. Every use of this spell increases all of the caster’s Spellcasting rolls in the commanded element for the next 24 hours to be at +5TN. This spell may also be used in place of Commune roll when Importuning. If this is done, the Spellcraft roll is automatically successful, but the penalty for casting spells of that Element is +10 to the TN rather than +5 (including the spell being Importuned) if in Rokugan.", "livro": "Imperial Histories 2", "pagina": "55"}, {"id": "x_dart_of_void", "nome": "Dart of Void", "elemento": "void", "mastery": "4", "area": "One target creature", "alcance": "100’", "duracao": "Instantaneous", "raises": "Range (+100’ per Raise), Targets (+1 target per two Raises, maximum targets equal to your Void Ring)", "descricao": "The Dart of Void spell was created by the shugenja Ekuro in his famous battle. The spell has been preserved as a secret of the Order of Five Weapons, but it is believed the Phoenix may also have the spell in their libraries, and it is possible other shugenja families have copies as well. Casting […]", "livro": "Secrets of the Empire", "pagina": "238"}], "vantagens": [{"id": "x_shadowed_heart", "nome": "Shadowed Heart", "tipo": "mental", "custo": 5, "descricao": "You have trained your mind to be nigh-inscrutable to those who surround you. Rolls made to discern your true intentions or motivations, including Social Skill rolls and Spell Casting Roll for any spells which might lay bare your thoughts, have their TN increased by +5.", "livro": "Enemies of the Empire", "pagina": "49"}, {"id": "x_spy_network", "nome": "Spy Network", "tipo": "social", "custo": 8, "descricao": "You have access to an intelligence network that can provide you with a variety of covert information. Once per session if you can contact your spy network you can acquire a piece of useful information which would otherwise be unavailable. The GM has the final say on what you learn, but it will always be something useful to your current endeavors. This Advantage cannot be used in environments where it would be impossible to make contact with your spy network (e.g. wandering the desert, exploring the Shadowlands or the Shinomen Mori, etc). Daidoji family characters may purchase this Advantage for 7 points, Scorpion characters may purchase it for 6 points, and Kolat characters may purchase it for 5 points.", "livro": "Enemies of the Empire", "pagina": "49"}, {"id": "x_sacred_weapon_owl_blade", "nome": "Sacred Weapon: Owl Blade", "tipo": "material", "custo": 6, "descricao": "The sacred Owl Blades, crafted by Seppun artisans, are 3k2 wakizashi. The spirits within them are so strong that the blades are considered to be equivalent to crystal for the purposes of harming otherworldly/nonhuman opponents. These weapons are greatly prized throughout the Empire of Togashi, especially by the Phoenix and the Crab; Otomo diplomats often gain many favors for their clan by offering Owl Blades as gifts.", "livro": "Imperial Histories 2", "pagina": "29"}, {"id": "x_naga_ancestry", "nome": "Naga Ancestry", "tipo": "physical/spiritual", "custo": 7, "descricao": "Either through a quirk of the Akasha’s strange powers, or perhaps due to an unknown dalliance between a human and a Naga, the blood of both races flows through your veins. You may purchase Naga-only Advantages at the normal cost, and you gain a bonus of +1k0 on all Social Skill Rolls made with members of the Naga race. At the GM’s option, characters with this Advantage may manifest physical signs of their inhuman ancestry, such as slit pupils or a faint sheen of scales on their skin. These effects would likely produce a social penalty when interacting with other Rokugani (most likely a –1k0 or –2k0 penalty, depending on how xenophobic a particular person might be), so if this approach is taken the total point cost of this Advantage should be reduced to 5.", "livro": "Imperial Histories 2", "pagina": "290"}, {"id": "x_battle_healing", "nome": "Battle Healing", "tipo": "mystical", "custo": 5, "descricao": "Some of the most ardent and militant shugenja of the Empire, including the Kuni family and Bishamon’s Chosen among the Kitsu, understand that the essence of all Elements can be used to suffuse the broken flesh of an honorable warrior and make it whole. Water is superior for such things, of course, but the other Elements can suffice when necessary. Once per day per person, you may expend one Water spell slot or two spell slots in any other Element(s) to heal one Wound Rank of a Rokugani you are touching.", "livro": "The Book of Water", "pagina": "179"}], "desvantagens": [{"id": "x_sleeper_agent", "nome": "Sleeper Agent", "tipo": "mental", "custo": 5, "descricao": "Unknown to you, the Kolat have previously kidnapped you and programmed you to be one of their sleeper agents. A trigger word or phrase is implanted in your mind. Anyone who knows it may speak it aloud, followed by a simple command of five words or less. You will be compelled to carry out the command regardless of personal wishes. Sleeper agents are generally considered one-time-only assets, so their survival is not a factor in the tasks they are assigned. Some sleepers are given a fail-safe that causes them to kill themselves should the mission fail – if this is the case for you, this Disadvantage is worth 8 points.", "livro": "Enemies of the Empire", "pagina": "49"}, {"id": "x_member_of_the_chrysanthemum_court", "nome": "Member of the Chrysanthemum Court", "tipo": "social", "custo": 5, "descricao": "You are a regular attendee at the Emperor’s court, the vaunted Imperial Court of Rokugan. Under the reign of any other Emperor, this would be an incredible privilege and an opportunity for your family and clan to earn glory and make political alliances. Under the reign of the Steel Chrysanthemum, however, it is a constant danger to your life; one misspoken word and you and all those you hold dear could pay the ultimate price. Whenever you fail a Social Skill Roll in the Imperial Court, if you fail by an amount greater than 10 you permanently lose five Points of Status, plus one additional Point for every Raise you declared on the failed roll. If your Status ever drops to 0, the Emperor capriciously kills you for some imagined slight. This Disadvantage may be used in other eras of play to depict the “privilege” of being assigned to a court ruled by a cruel, capricious, or corrupt lord. In this case the “die at 0 Status” aspect should be dropped, and the Experience Point value of the Disadvantage should be reduced to 3.", "livro": "Imperial Histories 2", "pagina": "127"}, {"id": "x_anachronism", "nome": "Anachronism", "tipo": "mental/social", "custo": 2, "descricao": "Although the society of Rokugan embraces traditionalism and for the most part eschews all change, some degree of social evolution is inevitable. For those spirits returned through Oblivion’s Gate, these changes can seem profound and extremely confusing. You are out of touch with modern conventions and styles. The Target Number of all Artisan, Craft, and Social Skill Rolls you make is increased by 5. Only returned spirits may purchase this Disadvantage. new Basic school: moto death priests The startling individuals known as the Moto Death Priests are adherents of the Shi-Tien Yen-Wang, the pantheon of wrathful gods of death and judgment who were worshipped by the Moto family prior to its allegiance to the Unicorn Clan. When the Moto were still nomads, they paid homage to these Lords of Death out of both reverence and fear. However, when the Lady Shinjo taught the Moto there were gods who could show compassion and reward loyalty, they forsook their old devotion and joined the Unicorn. For centuries, the enraged Lords of Death sought their wayward worshippers, finally locating them in the Empire of Rokugan and afflicting them with ill fortune […]", "livro": "Imperial Histories", "pagina": "243"}], "ancestrais": [{"id": "x_ancestor_otomo", "nome": "Ancestor, Otomo", "tipo": "ancestral", "custo": 6, "descricao": "The clever and notoriously serpentine Otomo was often underestimated by his foes, but his smooth tongue and flexible mind seldom came out second-best. His guidance bestows similar blessings on his descendents. Otomo’s supervision grants you a +1k1 bonus when using the Courtier Skill with the Manipulation or Rhetoric Emphases. cc Constraint: Otomo despised two things: stupidity and disloyalty. If you ever willingly betray the Imperial house, or are ever tricked or outmaneuvered by a political rival with equal or lower Status Rank, Otomo will forsake you. cc GM’s Note: The terminology of “tricked or outmaneuvered” is deliberately open-ended to allow for the wide variety of possible situations in social conflicts. However, it is not intended to mean that the character can lose Otomo’s guidance simply due to a failed Social Skill Roll.", "livro": "Secrets of the Empire", "pagina": "245", "devocao": ""}, {"id": "x_ancestor_seppun", "nome": "Ancestor, Seppun", "tipo": "ancestral", "custo": 10, "descricao": "The Lady Seppun was the first follower of the Kami and the first of the old religious order to fully and unreservedly embrace the ways of Shintao. Her guidance allows you to touch the harmony of the universe more easily. Once per 243 session, you may gain the benefits of a Void Point without actually having to spend the Void Point. cc Constraint: Seppun was a deeply pious woman and was wholly devoted to Hantei. If you ever embrace a heretical religious viewpoint or if you ever place your own needs, goals, or desires ahead of the Imperial house, in even the most minor way, she will abandon you.", "livro": "Secrets of the Empire", "pagina": "245", "devocao": ""}, {"id": "x_ancestor_miya", "nome": "Ancestor, Miya", "tipo": "ancestral", "custo": 5, "descricao": "The first Miya tirelessly and selflessly spread the word of the Empire’s victory over Fu Leng, and also labored to rebuild the damage from the First War. So long as you are on the business of the Imperial house, Miya’s guidance allows you to ignore the effects of lack of rest/sleep for a number of days equal to your Honor Rank. cc Constraint: Miya expects his descendents to show his same compassion toward those suffering from war or disaster. If you ever turn away from helping those suffering from either of these events, Miya will abandon you.", "livro": "Secrets of the Empire", "pagina": "245", "devocao": ""}, {"id": "x_ancestor_ichiro_fureheshu", "nome": "Ancestor, Ichiro Fureheshu", "tipo": "ancestral", "custo": 9, "descricao": "The founder of the Furehershu vassal family had such extraordinary strength that he defeated an oni with his bare hands. Fureheshu’s guidance allows you to call on your own Strength in unusual situations. When performing a Skill roll with a physical Trait, you may spend a Void Point to use Strength in place of the normal Trait. cc Constraint: Fureheshu expects you to always embrace Strength with the same fervor as he did. If you ever lose a contest of Strength, he will abandon you.", "livro": "Secrets of the Empire", "pagina": "245", "devocao": ""}, {"id": "x_ancestor_komori_iongi", "nome": "Ancestor, Komori Iongi", "tipo": "ancestral", "custo": 5, "descricao": "Yoritomo Iongi was an enlightened Mantis samurai who rescued the Tetsubo of Thunder and later swore fealty to the Bat Clan. Those who have his guidance are inspired to similar heroic accomplishments, gaining one extra Void Point per session. cc Constraint: Iongi lived a life of glorious heroism and expects his descendents to do the same. If you ever pass up the chance to do something heroic or glorious, he will forsake you.", "livro": "Secrets of the Empire", "pagina": "246", "devocao": ""}, {"id": "x_ancestor_hida_heichi", "nome": "Ancestor, Hida Heichi", "tipo": "ancestral", "custo": 4, "descricao": "The founder of the Boar Clan was a man not only of courage but also possessing wisdom and tact, able to persuade the Shakoki Dogu to release his people and then devising the means by which the Boar might appease the Emperor. Those with his guidance gain a +1k1 bonus to all Social Skill rolls made against more powerful persons and beings. cc Constraint: Those who are guided by Hida Heichi must emulate his self-control. If you ever lose your temper in a social situation, Heichi will forsake you.", "livro": "Secrets of the Empire", "pagina": "246", "devocao": ""}, {"id": "x_ancestor_tonbo_kuyuden", "nome": "Ancestor, Tonbo Kuyuden", "tipo": "ancestral", "custo": 3, "descricao": "The first true daimyo of the Dragonfly Clan avenged his father’s death but then forsook the sword to embrace the new clan’s ways of peace and diplomacy. Those who have his guidance gain a +1k1 bonus to all Courtier or Etiquette rolls made for the purpose of defusing violence or finding peaceful solutions to conflicts. cc Constraint: If you ever willingly choose violence when diplomacy is still an option, Kuyuden will abandon you.", "livro": "Secrets of the Empire", "pagina": "246", "devocao": ""}, {"id": "x_ancestor_usagi_reichin", "nome": "Ancestor, Usagi Reichin", "tipo": "ancestral", "custo": 7, "descricao": "The founder of the Hare Clan was a man known for both his cheerful nature and for his clever tactics and great courage against the Bloodspeaker Cult. His guidance grants you a +1k1 bonus when resisting Fear effects; if the Fear is caused by a Bloodspeaker, the bonus is +2k2 instead. cc Constraint: Although Reichin was a pragmatic ronin, he also fought with supreme courage in the Battle of the Bloody Retreat. If you ever flee from a battle with a Bloodspeaker when there is still a chance of victory, Reichin will forsake you.", "livro": "Secrets of the Empire", "pagina": "246", "devocao": ""}, {"id": "x_ancestor_toku", "nome": "Ancestor, Toku", "tipo": "ancestral", "custo": 3, "descricao": "The founder of the Monkey Clan is legendary for both his heroism and his extraordinary good fortune. So long as Toku watches over you, you are considered to have a Rank in the Luck Advantage (an additional Rank if you already possess your own Luck).", "livro": "Secrets of the Empire", "pagina": "246", "devocao": ""}, {"id": "x_ancestor_tsi", "nome": "Ancestor, Tsi", "tipo": "ancestral", "custo": 6, "descricao": "The ronin called simply “Tsi,” descended from Tsi Wenfu, was such a skilled swordsmith that the Emperor declared him and his family to be Imperial vassals. His guidance allows his descendents to display skills that almost transcend mortal limitations. Your Raises with the Craft: Swordsmithing Skill are not limited in any way. cc Constraint: Like all of his family, Tsi saw swordsmithing as an art that had little to do with actually killing. If you ever use one of your own swords in combat for any purpose other than selfdefense, Tsi will abandon you. cc GM’s Option: If the GM is using the Alternate Crafting Rules from this book, the following alternate version of Tsi may be used. Instead of lifting all constraints on Raises, the guidance of Tsi awards a Free Raise for the purpose of using the Alternate Crafting rules.", "livro": "Secrets of the Empire", "pagina": "246", "devocao": ""}, {"id": "x_ancestor_morito_garin", "nome": "Ancestor, Morito Garin", "tipo": "ancestral", "custo": 5, "descricao": "After the purge of the Kolat, Morito Garin labored to restore his clan’s reputation and to hunt down any remaining Kolat influences. His guidance grants you a +1k1 bonus to any Perception-based or Awareness-based roll that is trying to determine someone’s true loyalties. cc Constraint: Garin demands you share his dedication to rooting out the Kolat. If you ever knowingly cooperate with the Kolat, or even simply leave them alone when you have a chance to oppose them, Garin will forsake you.", "livro": "Secrets of the Empire", "pagina": "247", "devocao": ""}, {"id": "x_ancestor_doji_suzume", "nome": "Ancestor, Doji Suzume", "tipo": "ancestral", "custo": 4, "descricao": "Suzume founded the Sparrow Clan after the rest of the Empire saw deep wisdom in his unthinking remark. If Suzume watches over you, you find it easier inspire others, gaining a +1k1 bonus to any Social Skill roll to persuade others to follow your guidance/example. However, once in your life (at a time chosen by the GM) a simple or random comment by you will be perceived as holding deep wisdom and meaning. The consequences of this could last a lifetime… cc Constraint: Suzume stayed with the people who followed him, and did his best to lead them despite his own confusion and many adverse circumstances. If you ever abandon followers who have come to you because of your words of wisdom, Suzume will forsake you in turn.", "livro": "Secrets of the Empire", "pagina": "247", "devocao": ""}, {"id": "x_ancestor_agasha_kasuga", "nome": "Ancestor, Agasha Kasuga", "tipo": "ancestral", "custo": 5, "descricao": "Agasha Kasuga was a man possessed of great curiosity, but also a man who placed the security of the Empire above all else, including his own purity. His guidance awards you a +1k1 bonus to any Skill Roll in which you are performing a dishonorable act (one that will cause you a loss of Honor) that is sanctioned by your duty to the Imperial house. cc Constraint: Kasuga expects you to share his selfsacrificing loyalty to Rokugan. If you ever place your own Honor above the needs of the Empire, he will abandon you. Ronin Ancestors It is quite rare for a ronin to cleanse his kharma and enter the Realm of Yomi after death. However, it does occasionally happen, and such fortunate souls try to watch over their descendents as best they can. A ronin ancestor will only watch over a True Ronin character – clan ronin can never have ronin ancestors.", "livro": "Secrets of the Empire", "pagina": "247", "devocao": ""}, {"id": "x_ancestor_sun_tao", "nome": "Ancestor, Sun Tao", "tipo": "ancestral", "custo": 10, "descricao": "Perhaps the greatest ronin soldier in Rokugan’s history, Sun Tao’s influence encompasses every clan and every war since. Many ronin claim to be descended from Sun Tao, but only a few actually win his guidance. Those who are advised by Sun Tao’s spirit share his ability to adapt to different environments and fight with equal skill in any sort of battle. You gain a +1k0 bonus to all Battle Skill rolls. If you make a Bugei Skill roll which fails, Sun Tao’s guidance allows you to spend a Void Point on the roll after it is made (rolling and adding 1k1 to the roll), but in return you lose the benefit of any Raises to the roll. cc Constraint: Sun Tao expects you to always seek to advance your knowledge of the ways of war and battle. If you ever turn down a chance to work for or train with a military force where you have not served before, Sun Tao will abandon you.", "livro": "Secrets of the Empire", "pagina": "247", "devocao": ""}, {"id": "x_ancestor_chiroru", "nome": "Ancestor, Chiroru", "tipo": "ancestral", "custo": 8, "descricao": "Chiroru led the ronin vanguard of the Empire’s army at the Battle of Sleeping River. A proud man who forged bonds of intense loyalty with his fellow wave-men, Chiroru refused an offer of fealty from the Fox Clan, declaring he could not go to the afterlife wearing a mon – after all, if he did, his brothers and sisters from the battle might not recognize him. Those who are guided by Chiroru’s spirit share his ability to forge powerful bonds of loyalty to their comrades. You may choose a number of individuals up to your Void Rank to be your “siblings” – you are considered to have a Kharmic Tie with each of these individuals, and you will always be aware if any of them are in danger. cc Constraint: Loyalty cuts both ways. If you ever forsake, abandon, or betray any of your “siblings,” Chiroru will forsake you in turn. cc GM Notes: It is recommended that players be allowed to have their character choose the “siblings” one at a time over the course of play, rather than having to select them all during character creation. At the GM’s option, a character could be allowed to select a new “sibling” if an earlier one dies or betrays the friendship.", "livro": "Secrets of the Empire", "pagina": "248", "devocao": ""}, {"id": "x_ancestor_miyuko", "nome": "Ancestor, Miyuko", "tipo": "ancestral", "custo": 12, "descricao": "The simple peasant woman called Miyuko was the first and greatest apprentice of the legendary shugenja Naka Kaeturo, the first Grandmaster of the Elements. Despite her humble origins she possessed profound wisdom and insight. After Kaeteru’s death she was offered fealty by the Phoenix, but chose instead to remain unaligned and travel the Empire sharing her late master’s teachings with all. Only ronin shugenja can benefit from the guidance of Miyuko’s spirit, and they share in her deep insights into the nature of magic and the Elements. You are considered to be one School Rank higher for the purpose of casting spells (Mastery level, Spell Casting Rolls, and spell effects). cc Constraint: Miyuko sought to share her wisdom with all who would listen, and she expects the same of you. If you ever refuse to share magical knowledge with an honorable person, Miyuko will abandon you. This means those guided by Miyuko will freely share their spells with others, in sharp contrast to most shugenja. Brotherhood of Shinsei Ancestors Since the vast majority of monks are expected to remain celibate (except for Fortunist monks devoted to Benten), few members of the Brotherhood have children. Moreover, with the exception of Shinsei’s bloodline the Brotherhood does not track ancestry or lines of descent. Thus, when a monk fulfills his destiny and ascends to Yomi, he does not watch over his own blood descendents. Instead, he offers guidance to those of the Brotherhood who follow his beliefs. In g […]", "livro": "Secrets of the Empire", "pagina": "248", "devocao": ""}, {"id": "x_ancestor_basso", "nome": "Ancestor, Basso", "tipo": "ancestral", "custo": 9, "descricao": "The founder of the Shinmaki Sect claimed his Diamond Sutra was written by Shinsei, although many others believe Basso wrote it himself. Basso’s order, with its bizarre meditative practices, remains the most controversial major sect within the Brotherhood. Those who have Basso’s guidance are able to gain true perception through their meditation, piercing the veil of illusions around them to see things as they truly are; you may see through any illusion or deception as a Complex Action with a Meditation/Void roll (TN chosen by the GM based on the strength of the illusion/deception). cc Constraint: Basso demands almost super-human dedication from his followers. You must meditate for at least four hours each day and must be absolutely ascetic, forsaking all worldly pleasures and indulgences, even the most minor. Any voluntary violation of this lifestyle will result in Basso abandoning you.", "livro": "Secrets of the Empire", "pagina": "248", "devocao": "Shinmaki Sect"}, {"id": "x_ancestor_sakura", "nome": "Ancestor, Sakura", "tipo": "ancestral", "custo": 10, "descricao": "The woman called Sakura is said to have been the first mortal to understand the possibility of Enlightenment, and some Brotherhood traditions maintain Shinsei himself was among her students. Some legends claim Shinsei’s crow was actually Sakura, transformed, and other legends suggest she may have been a kenku.", "livro": "Secrets of the Empire", "pagina": "248", "devocao": "Shintaoist"}, {"id": "x_ancestor_mizumoto", "nome": "Ancestor, Mizumoto", "tipo": "ancestral", "custo": 7, "descricao": "Mizumoto was a Crane courtier from the time of Hantei Genji, widely admired for his intellect and education. After retirement to the Brotherhood, he became one of the Empire’s foremost experts on the Tao, renowned for his understanding of the sacred text’s meanings. Those guided by Mizumoto share his intellectual gifts, gaining a +1k1 bonus to all Intelligencebased rolls. cc Constraint: Mizumoto sought always to extend his knowledge of the Tao and the ways of Enlightenment. If you ever voluntarily pass over a chance to learn about a new teaching, sect, or belief within the Brotherhood, Mizumoto will abandon you.", "livro": "Secrets of the Empire", "pagina": "248", "devocao": "Questioner"}, {"id": "x_ancestor_togashi_kaze", "nome": "Ancestor, Togashi Kaze", "tipo": "ancestral", "custo": 5, "descricao": "Although Togashi Kaze was originally a member of the Dragon Clan, he also founded what became the Order of Kaimetsu-Uo when he renovated an abandoned monastery and began teaching the local monks a form of “meditative exercise” based on his martial art techniques. Kaze’s spirit teaches some of his unarmed techniques and meditative abilities to his favored disciples. So long as your Meditation Skill Rank is at least equal to your Jiujutsu Skill Rank, you gain a Free Raise on unarmed attacks. cc Constraint: Kaze expects you to uphold his principles of using violence only for defense and refraining from killing, no matter what the […]", "livro": "Secrets of the Empire", "pagina": "248", "devocao": "Fortunist/Kaimetsu-Uo"}], "kihos": [{"id": "tattoo_balance", "nome": "Balance", "mastery": null, "elemento": null, "tipo": "tattoo", "descricao": "This tattoo of the spiritual yin-yang symbol calms the mind and spirit. While this tattoo is active, the TN of all Spell Casting Rolls made with you as the target are increased or decreased by an amount equal to twice your School Rank plus 5. You determine whether this is an increase or a decrease when you activate the tattoo.", "livro": "Livro Básico (4ª ed.)", "pagina": "115"}, {"id": "tattoo_bamboo", "nome": "Bamboo", "mastery": null, "elemento": null, "tipo": "tattoo", "descricao": "The bamboo plant is ubiquitous throughout the Empire, and is well known not only for the speed with which it grows, but also its durability. While this tattoo is active, your Armor TN is increased by an amount equal to twice your School Rank + 5.", "livro": "Livro Básico (4ª ed.)", "pagina": "115"}, {"id": "tattoo_blaze", "nome": "Blaze", "mastery": null, "elemento": null, "tipo": "tattoo", "descricao": "The power and fury of fire is unleashed in the Blaze tattoo. When activated, this tattoo causes your unarmed strikes to be bolstered with pure fire. Your unarmed attacks are accompanied by flickering flames that inflict an additional amount of fire damage equal to your Fire Ring plus your School Rank.", "livro": "Livro Básico (4ª ed.)", "pagina": "115"}, {"id": "tattoo_centipede", "nome": "Centipede", "mastery": null, "elemento": null, "tipo": "tattoo", "descricao": "The tiny centipede has hundreds of legs working in unison, and that power can be commanded by the monks who bear its image. When this tattoo is activated, you may make a special Complex Move Action that allows you to move a distance equal to your Water Ring x 100'. This effect lasts for an entire day, essentially allowing you to cross the face of the Empire in a day. If you stop for more than one minute, the effect ends. When the effect ends, you collapse into an exhausted state and can take no physical actions for a period of twelve hours.", "livro": "Livro Básico (4ª ed.)", "pagina": "115"}, {"id": "tattoo_crab", "nome": "Crab", "mastery": null, "elemento": null, "tipo": "tattoo", "descricao": "The tiny crab is resilient beyond all measure for its size. While this tattoo is active, you gain a Reduction rating equal to your Earth Ring.", "livro": "Livro Básico (4ª ed.)", "pagina": "115"}, {"id": "tattoo_crane", "nome": "Crane", "mastery": null, "elemento": null, "tipo": "tattoo", "descricao": "The crane is a symbol of luck and beauty. When you activate this tattoo, you gain a number of bonus dice equal to your School Rank plus your Air Ring. These dice may be spent on any Social Skill Rolls. Each die contributes a bonus of +1k0. If these bonus dice are not used within an hour, they are lost. You may not add more bonus dice to a single roll than your Void Ring. This tattoo is considered active the entire hour, and if another tattoo is activated, any unspent dice from this tattoo are lost.", "livro": "Livro Básico (4ª ed.)", "pagina": "115"}, {"id": "tattoo_dragon", "nome": "Dragon", "mastery": null, "elemento": null, "tipo": "tattoo", "descricao": "The dragon is a fearsome tattoo, and contains frightening power waiting to be unleashed. As a Complex Action, you may breathe fire in a cone, equal to ten feet plus your School Rank in length, and fi ve feet wide at the end. This fire deals damage to all in its area of effect, with a DR equal your Fire Ring. You take damage equal to your Fire Ring upon each use.", "livro": "Livro Básico (4ª ed.)", "pagina": "115"}, {"id": "tattoo_hawk", "nome": "Hawk", "mastery": null, "elemento": null, "tipo": "tattoo", "descricao": "You may borrow the essence of the hawk, and cover great distances with ease. As a Complex Action, you may leap a distance equal to your Water Ring x 25'.", "livro": "Livro Básico (4ª ed.)", "pagina": "115"}, {"id": "tattoo_kirin", "nome": "Ki-Rin", "mastery": null, "elemento": null, "tipo": "tattoo", "descricao": "There are few omens of good fortune more signifi cant than that of the sacred ki-rin. Upon activating this tattoo, you may immediately re-roll any one roll per round, keeping the higher of the two results.", "livro": "Livro Básico (4ª ed.)", "pagina": "115"}, {"id": "tattoo_lion", "nome": "Lion", "mastery": null, "elemento": null, "tipo": "tattoo", "descricao": "The lion is a proud and noble warrior. Upon activating this tattoo, you gain ranks equal to your School Rank in any Bugei Skill of your choice.", "livro": "Livro Básico (4ª ed.)", "pagina": "115"}, {"id": "tattoo_mantis", "nome": "Mantis", "mastery": null, "elemento": null, "tipo": "tattoo", "descricao": "The mantis is a fierce and fearless warrior out of all proportion to its tiny size. Upon receiving this tattoo, you are completely immune to all Fear effects. This tattoo is active at all times, and does not prevent the use of other tattoos.", "livro": "Livro Básico (4ª ed.)", "pagina": "115"}, {"id": "tattoo_mountain", "nome": "Mountain", "mastery": null, "elemento": null, "tipo": "tattoo", "descricao": "The mountain is eternal and unmoving. When you activate this tattoo, all your Wound Penalties are reduced by an amount equal to your School Rank plus 2.", "livro": "Livro Básico (4ª ed.)", "pagina": "115"}, {"id": "tattoo_ocean", "nome": "Ocean", "mastery": null, "elemento": null, "tipo": "tattoo", "descricao": "The ocean's boundless depths hold the secrets of life and rejuvenation. When granted this tattoo, you no longer have need of food or drink, although you may still partake of them if you wish. When this tattoo is activated, you are instantly refreshed as if you had spent eight hours of sleep, and you regain all spent Void Points. This tattoo may only be used once every three days.", "livro": "Livro Básico (4ª ed.)", "pagina": "115"}, {"id": "tattoo_phoenix", "nome": "Phoenix", "mastery": null, "elemento": null, "tipo": "tattoo", "descricao": "The Phoenix can never truly be defeated, rising as it does from the ashes to be born anew. You must have at least one unspent Void Point for this tattoo to be triggered. When you are reduced to the Down Wound Level or below, this tattoo automatically activates. All unspent Void Points are lost, and you immediately heal a number of Wounds equal to your School Rank x 10. This tattoo cannot be activated more than once per week.", "livro": "Livro Básico (4ª ed.)", "pagina": "116"}, {"id": "tattoo_scorpion", "nome": "Scorpion", "mastery": null, "elemento": null, "tipo": "tattoo", "descricao": "The scorpion is silent and deadly. While this tattoo is active, you roll additional dice on any Stealth Skill Roll equal to your School Rank. Also, during this time your unarmed attacks automatically Daze your opponent if any dice explode on your damage roll.", "livro": "Livro Básico (4ª ed.)", "pagina": "116"}, {"id": "tattoo_spider", "nome": "Spider", "mastery": null, "elemento": null, "tipo": "tattoo", "descricao": "The spider is quick and dexterous, escaping predators with its speed and agility. While this tattoo is active, you may move across vertical and inverted surfaces (such as sheer walls or ceilings) while making Move Actions. You move at half your normal rate when doing so.", "livro": "Livro Básico (4ª ed.)", "pagina": "116"}, {"id": "tattoo_storm", "nome": "Storm", "mastery": null, "elemento": null, "tipo": "tattoo", "descricao": "The storm is nature's fury, and few can stand against its raw power. While this tattoo is active, your unarmed attacks require only one Raise to use the Knockdown Maneuver.", "livro": "Livro Básico (4ª ed.)", "pagina": "116"}, {"id": "tattoo_void", "nome": "Void", "mastery": null, "elemento": null, "tipo": "tattoo", "descricao": "This ink black kanji represents oneness with all. When this tattoo is activated, you gain awareness of all life around you. You know the location and rough details of all living things within a radius of your School Rank x 10', even if you cannot see them. You know only rough details, such as “two warriors” or “a pair of rabbits,” not specifi c identities. You can recognize individuals well-known to you, however.", "livro": "Livro Básico (4ª ed.)", "pagina": "116"}, {"id": "tattoo_wind", "nome": "Wind", "mastery": null, "elemento": null, "tipo": "tattoo", "descricao": "The wind is swift and moves without hindrance. While this tattoo is active, you gain an additional Simple Action per round, which may not be used to make an attack. Your maximum total movement is not limited to your Water Ring x 20.", "livro": "Livro Básico (4ª ed.)", "pagina": "116"}, {"id": "tattoo_wolf", "nome": "Wolf", "mastery": null, "elemento": null, "tipo": "tattoo", "descricao": "The wolf is the great tracker of the wilds. When you activate this tattoo, your senses become superhumanly sharp, allowing you to perceive small details and even individual scents. You gain a number of Free Raises on Hunting (Tracking) Skill Rolls equal to your School Rank. This tattoo's effect lasts a number of hours equal to your School Rank.", "livro": "Livro Básico (4ª ed.)", "pagina": "116"}], "armas": [{"id": "x_sling", "nome": "Sling", "pericia": "athletics", "dr": "1k2", "drAlt": "", "custo": "—", "tags": ["small", "peasant", "ranged"], "descricao": "Range 100’. Attacks with Athletics/Agility (GM may allow a Sling emphasis). Strength is not added to the DR. Reduction is doubled against sling attacks.", "livro": "Secrets of the Empire", "pagina": "238"}, {"id": "x_naga_scimitar", "nome": "Naga Scimitar", "pericia": "kenjutsu", "dr": "2k3", "drAlt": "", "custo": "20 koku", "tags": ["large", "naga", "melee"], "descricao": "Heavy curved blade that relies on weight and momentum; not folded steel and weaker than Rokugani blades. Used mostly by Naga warriors.", "livro": "Enemies of the Empire", "pagina": "85"}, {"id": "x_naga_spear", "nome": "Naga Spear", "pericia": "spears", "dr": "3k2", "drAlt": "", "custo": "5 koku", "tags": ["large", "naga", "melee", "spear"], "descricao": "Seven to ten feet long, used one- or two-handed with equal ease; can strike from the second rank and be thrown short distances.", "livro": "Enemies of the Empire", "pagina": "85"}, {"id": "x_nageteppo_smoke", "nome": "Nageteppo (smoke)", "pericia": "athletics", "dr": "1k1", "drAlt": "", "custo": "—", "tags": ["ninja", "small", "ranged"], "descricao": "Range 30’. Throwing is a Simple Action. Breaks into a 15’ cloud of choking smoke for five Rounds (those inside are Blind). A direct hit burns for 1k1 per Round for two Rounds. Craft: Explosives/Intelligence TN 25.", "livro": "Imperial Histories", "pagina": "159"}, {"id": "x_nageteppo_incendiary", "nome": "Nageteppo (incendiary)", "pericia": "athletics", "dr": "3k2", "drAlt": "", "custo": "—", "tags": ["ninja", "small", "ranged"], "descricao": "Range 25’. Damage 3k2, ignores 3 points of Reduction. Craft: Explosives/Intelligence TN 25; a failed TN 10 explodes for 3k2.", "livro": "Imperial Histories", "pagina": "159"}]};
for(const k in X){const arr=L5R4E[k]||(L5R4E[k]=[]);const ids=new Set(arr.map(x=>x.id));X[k].forEach(x=>{if(!ids.has(x.id))arr.push(x);});}
})();
/* Bestiário de Inimigos do Império (páginas da edição em português). Somado ao BESTIARIO do index.html sem repetir o que já existe. */
window.BESTIARIO_EXTRA=[{"id": "idi_aguia_washi", "n": "Águia (Washi)", "tipo": "fera", "fonte": "IdI p. 10", "an": [1, 1, 1, 2], "tr": "Reflexos 5, Agilidade 4, Percepção 4", "ini": "5k5", "atq": [["Bico/garras", "5k4", "C", "2k2"]], "tn": 30, "red": 0, "fer": [[7, 5], [15, null]], "per": "", "hab": [["Veloz 3 (ao voar)", ""]], "nota": "A maior ave de rapina de Rokugan é a águia dourada. Embora falcões sejam maiores que águias, águias são conhecidas por sua força surpreendente e por caçarem caprinos."}, {"id": "idi_alce_shika", "n": "Alce (Shika)", "tipo": "fera", "fonte": "IdI p. 10", "an": [2, 1, 1, 2], "tr": "Reflexos 5, Vigor 3, Agilidade 3, Força 4", "ini": "5k5", "atq": [["Chifres", "3k3", "C", "4k2"]], "tn": 30, "red": 3, "fer": [[12, 10], [24, 20], [36, null]], "per": "Furtividade 2", "hab": [["Cio", "Durante sua estação de acasalamento, alces machos se tornam mais agressivos e valentes. Eles recebem +1k1 em jogadas de Ataque, mas perdem todos os níveis da Perícia Furtividade"], ["Veloz 3", ""]], "nota": "O alce é a caça mais comum de Rokugan. Eles são valorizados por sua rapidez e o desafio que representam aos caçadores."}, {"id": "idi_bode_kamoshika", "n": "Bode (Kamoshika)", "tipo": "fera", "fonte": "IdI p. 11", "an": [1, 2, 1, 1], "tr": "Reflexos 2, Agilidade 3, Força 2", "ini": "2k2", "atq": [["Chifres", "4k3", "C", "3k2"]], "tn": 15, "red": 4, "fer": [[16, 10], [32, null]], "per": "Esportes 2", "hab": [["Veloz 2", ""], ["Cabeçada", "Bodes ganham um Incremento Livre para tentativas de Derrubar"]], "nota": "Bodes rokuganis estão entre as maiores espécies de bodes do mundo, chegando a 90 cm de altura e pesando até 130 kg. Eles são notáveis por seu pelo escuro crespo e faces brancas."}, {"id": "idi_cobra_constritora_hebi", "n": "Cobra Constritora (Hebi)", "tipo": "fera", "fonte": "IdI p. 11", "an": [1, 3, 1, 2], "tr": "Reflexos 3, Vigor 4, Agilidade 3, Força 4", "ini": "3k3", "atq": [["Mordida", "3k3", "C", "1k1"], ["Agarrar", "7k3", "C", "—"]], "tn": 20, "red": 3, "fer": [[16, 5], [32, 10], [38, null]], "per": "Jiujutsu 4, Furtividade 4", "hab": [["Espremer", "Ao usar o ataque Espremer, a cobra constritora sempre escolherá causar dano enquanto controlar a Imobilização (ela joga 8k4 para manter o controle da Imobilização). Após a vítima sofrer dano Bestiário de Espremer por um número de Rodadas consecutivas igual ao seu Vigor, ela começará a sufocar, sofrendo outros 2k2 Ferimentos por Rodada. 11 oaThadeuHudsonEm"]], "nota": "Cerca de três dúzias de variedades de cobras chamam Rokugan de lar. Embora não sejam vistas normalmente, cobras estão presentes nas terras de todos os clãs e normalmente desempenham uma grande função na manutenção da saúde da população ao comer espécies de pragas."}, {"id": "idi_cobra_venenosa_hebi", "n": "Cobra Venenosa (Hebi)", "tipo": "fera", "fonte": "IdI p. 12", "an": [1, 2, 1, 1], "tr": "Reflexos 3, Agilidade 3, Percepção 2", "ini": "3k3", "atq": [["Mordida", "3k3", "C", "1k1"]], "tn": 20, "red": 0, "fer": [[6, 10], [12, null]], "per": "Furtividade 5", "hab": [["Veneno", "Peçonha de áspide só é perigosa se introduzida na corrente sanguínea (via picada). Ela reduz Agilidade, Reflexos, Vigor e Força do alvo em 1 por hora. No começo da segunda e a cada hora subsequente, o alvo pode fazer um teste de Vigor (NA 25) para evitar penalidades adicionais para esta hora. Caso contrário, essas penalidades continuam a ocorrer até que o alvo passe em três testes consecutivos, o "]], "nota": "Cobras venenosas são encontradas em Rokugan mas são mais comuns nas partes centrais e sul do Império. O Clã Escorpião usa seu veneno para seus fins sinistros, e outras organizações mais secretas também colhem peçonha de cobras."}, {"id": "idi_crocodilo_wani", "n": "Crocodilo (Wani)", "tipo": "fera", "fonte": "IdI p. 12", "an": [1, 3, 2, 2], "tr": "Reflexos 3, Vigor 4, Agilidade 4, Percepção 4", "ini": "4k3", "atq": [["Mordida", "5k4", "C", "4k4"]], "tn": 20, "red": 5, "fer": [[24, 5], [36, 10], [64, null]], "per": "Furtividade 2", "hab": [["Aquático", "Crocodilos nadam em água tão facilmente quanto se movem em terra, se não ainda mais fácil. Eles não precisam fazer um teste de Perícia para nadar."], ["Medo 2", ""], ["Veloz 2 (ao nadar)", ""], ["Mandíbulas Vorazes", "Crocodilos que mordam alguém podem prendê-los com um Teste Disputado de Força, causando 2k2 de dano adicional a cada Turno. Se isto ocorrer na água, a vítima começará a se afogar nas rodadas subsequentes."]], "nota": "Crocodilos são répteis anfíbios quadrúpedes conhecidos por devorarem humanos. Os maiores crocodilos podem chegar a 6 m e pesar até 1 tonelada."}, {"id": "idi_elefante_zo", "n": "Elefante (Zo)", "tipo": "fera", "fonte": "IdI p. 12", "an": [1, 4, 2, 2], "tr": "Reflexos 3, Vigor 6, Agilidade 3, Força 7", "ini": "4k3", "atq": [["Presas", "4k3", "C", "7k2"], ["Pisotear", "5k4", "C", "4k4"]], "tn": 20, "red": 7, "fer": [[20, 5], [40, 10], [60, 15], [80, 20], [100, null]], "per": "", "hab": [["Investida", "Se um elefante estiver na Postura Ataque Total e se mover ao menos 10 m, ele pode atacar com suas presas como Ação Simples ao invés de Ação Complexa."], ["Medo 2", ""], ["Imenso", ""]], "nota": "Elefantes são nativos do longínquo reino conhecido como Reinos de Marfim e são totalmente desconhecidos em Rokugan. Alguns samurais importaram elefantes como curiosidade, mas nunca houve mais do que quatro no Império por vez."}, {"id": "idi_esquilo_voador_musasabi", "n": "Esquilo Voador (Musasabi)", "tipo": "fera", "fonte": "IdI p. 13", "an": [2, 1, 1, 1], "tr": "Reflexos 4, Agilidade 2, Percepção 2", "ini": "4k4", "atq": [["Dentes", "3k2", "C", "1k1"]], "tn": 25, "red": 0, "fer": [[6, 5], [12, null]], "per": "Esportes 5", "hab": [["Planar", "O esquilo pode planar de locais mais altos para mais baixos como Ação Complexa. Isto é considerado como Veloz 4 (ao invés de Veloz 2) ao planar."], ["Veloz 2", ""]], "nota": "O esquilo voador é o maior esquilo rokugani. Ele pode saltar e planar grandes distâncias, usando uma camada de pele que conecta suas patas traseira e dianteiras em cada lado."}, {"id": "idi_garca_tsuru", "n": "Garça (Tsuru)", "tipo": "fera", "fonte": "IdI p. 13", "an": [1, 1, 1, 1], "tr": "Reflexos 4, Agilidade 3, Percepção 2", "ini": "4k4", "atq": [["Bico", "3k3", "C", "2k1"]], "tn": 25, "red": 0, "fer": [[6, 5], [12, null]], "per": "", "hab": [["Veloz 4 (ao voar)", ""]], "nota": "Garças selvagens são assuntos de inúmeros poemas e pinturas rokuganis. Garças não são ameaça para humanos, e samurais não as ferirão, mas ronins ocasionais as caçam."}, {"id": "idi_gato_neko", "n": "Gato (Neko)", "tipo": "fera", "fonte": "IdI p. 13", "an": [2, 1, 1, 1], "tr": "Reflexos 4, Agilidade 3, Percepção 4", "ini": "4k4", "atq": [["Mordida", "4k3", "C", "1k1"], ["Garra", "3k3", "C", "—"]], "tn": 25, "red": 0, "fer": [[5, 5], [10, 15], [15, null]], "per": "", "hab": [["Febre do Arranhão de Gato", "Sempre que um personagem for arranhado por um gato, há 1 chance em 10 de ele adoecer. Isto resultará em febre e inflamação por 1 a 3 semanas, infligindo uma penalidade total de -1k0 Bestiário a todas as ações até ser curado (feitiços ou Medicina NA 30) ou a doença passar."], ["Visão em Baixa Luz", "Gatos operam normalmente em luz fraca (como luz das estrelas), embora ainda fiquem 13 cegos em escuridão completa."]], "nota": "Gatos em Rokugan são alvo de considerável superstição e alguns camponeses acreditam que eles são espíritos metamorfos ou amigáveis. Eles são por vezes mantidos como animais de estimação, e muitos monastérios e vilarejos também encorajam sua presença, pois reduzem o número de ratos e outras pragas."}, {"id": "idi_gorila_ozaru", "n": "Gorila (Ozaru)", "tipo": "fera", "fonte": "IdI p. 13", "an": [1, 2, 2, 1], "tr": "Reflexos 3, Vigor 4, Agilidade 4, Força 5", "ini": "4k3", "atq": [["Bater", "5k4", "S", "5k2"], ["Mordida", "4k4", "C", "—"]], "tn": 20, "red": 4, "fer": [[10, 5], [20, 10], [30, 15], [40, null]], "per": "Esportes (Escalar) 3", "hab": [["Medo 1 oaThadeuHudsonEm", ""]], "nota": "Gorilas são grandes animais humanoides, cobertos de pelos, com grande inteligência; algumas raças são conhecidas por serem capazes de utilizar ferramentas de pedra lascada ou madeira. Eles são comuns nas selvas das Ilhas de Seda e Especiaria, e às vezes aparecem no continente também, embora muito ma"}, {"id": "idi_javali_inoshishi", "n": "Javali (Inoshishi)", "tipo": "fera", "fonte": "IdI p. 14", "an": [1, 5, 1, 2], "tr": "Reflexos 3, Agilidade 3, Força 4", "ini": "4k3", "atq": [["Presas", "5k3", "C", "5k2"]], "tn": 20, "red": 12, "fer": [[30, 5], [75, null]], "per": "Jiujutsu 3", "hab": [["Eviscerar", "Um javali pode iniciar tentativas de Imobilização com suas presas. Enquanto controlar a Imobi- lização, o javali causa 4k4 de dano em seu oponente a cada rodada."], ["Investida Atroz", "Quando um javali está na Postura Ataque Total, ele pode atacar como uma Ação Simples ao invés de uma Ação Complexa, e acrescenta +1k1 às suas jogadas de ataque e dano."], ["Imenso 14", ""]], "nota": "Javalis são mamíferos médios parentes dos porcos, diferenciando-se de seus primos menores por couros espessos, pelo grosso e as duas imensas presas nos cantos de suas mandíbulas. Embora herbívoros, eles são animais perigosos e agressivos, notoriamente difíceis de matar, e a única coisa mais fácil qu"}, {"id": "idi_lebre_usagi", "n": "Lebre (Usagi)", "tipo": "fera", "fonte": "IdI p. 14", "an": [1, 1, 1, 1], "tr": "Reflexos 4, Percepção 3", "ini": "4k4", "atq": [], "tn": 20, "red": 0, "fer": [[5, 10], [10, null]], "per": "Esportes 5", "hab": [["Veloz 3", ""]], "nota": "Bestiário Pequenas, rápidas e atentas, lebres podem ser encontradas em quase qualquer lugar do continente rokugani. Elas são presas comuns de falcoeiros, embora seja claro que samurais não comam de fato tal carne vermelha."}, {"id": "idi_macaco_saru", "n": "Macaco (Saru)", "tipo": "fera", "fonte": "IdI p. 14", "an": [2, 1, 2, 1], "tr": "Reflexos 4, Vigor 2, Agilidade 3, Força 3", "ini": "5k4", "atq": [["Mordida", "3k3", "C", "3k1"]], "tn": 25, "red": 0, "fer": [[8, 5], [16, 10], [24, null]], "per": "Esportes (Saltar) 5", "hab": [["Veloz 2", ""]], "nota": "Muito mais numerosos que seus primos maiores, os gorilas, macacos são encontrados em muitas partes do continente rokugani, bem como nas Ilhas do Louva-a-deus. Alguns deles até mesmo habitam nas frias montanhas do norte, se aquecendo em fontes termais."}, {"id": "idi_morcego_koumori", "n": "Morcego (Koumori)", "tipo": "fera", "fonte": "IdI p. 14", "an": [2, 1, 1, 1], "tr": "Reflexos 3, Agilidade 3, Percepção 3", "ini": "3k3", "atq": [["Mordida", "3k3", "C", "1k1"]], "tn": 20, "red": 0, "fer": [[5, 10], [10, null]], "per": "", "hab": [["Ecolocalização", "Morcegos podem operar em total escuridão sem penalidade."], ["Veloz 3 (ao voar)", ""], ["Vetor de Doença", "Sempre que um personagem for mordido por um morcego, há 1 chance em 10 de o personagem adoecer. A menos que seja tratado com magia ou a perícia Medicina (NA 30), o personagem sofrerá febres crônicas, calafrios e dores musculares, reduzindo todos os Atributos físicos em 1. Se não for tratado em longo prazo, a doença pode eventualmente resultar em dano físico permanente ou morte, a critério do Mestr"]], "nota": "Morcegos são normalmente vistos como bom presságio em Rokugan, já que comem insetos como mosquitos que são normalmente considerados como uma forma de Gaki. Morcegos são noturnos, e capazes de se orientar no escuro por uso de ecolocalização, “vendo” com seus ouvidos."}, {"id": "idi_polvo_e_lula_tako", "n": "Polvo e Lula (Tako)", "tipo": "fera", "fonte": "IdI p. 15", "an": [2, 2, 2, 2], "tr": "Reflexos 3, Vigor 4, Agilidade 3, Força 4", "ini": "4k3", "atq": [["Tentáculos", "5k4", "S", "4k4"], ["Bico", "4k4", "C", "—"]], "tn": 20, "red": 5, "fer": [[16, 6], [32, 12], [48, null]], "per": "Jiujutsu 5, Furtividade (Esconder, Emboscada) 5", "hab": [["Mudar de Cor (apenas polvo)", "A capacidade natural de um polvo para mudar de cor permite que ele se misture ao fundo do mar. Se ele gastar uma Ação Simples para se ocultar dessa maneira, ele ganha +1k1 em seu Teste da Perícia Furtividade para se esconder."], ["Propulsão a Jato", "Uma lula ou um polvo pode disparar um jato de água para se mover a grande velocidade. Se a criatura gastar uma Ação Complexa para se mover, ela pode se mover até Água x 9 m."], ["Mordida Venenosa", "Num ataque bem sucedido com seu bico, uma lula ou polvo afligirá seu alvo com um veneno paralisante. O alvo fica Atordoado por quatro Rodadas, recuperando-se durante o Estágio de Reações da quarta rodada. Se a vítima rolar Vigor contra NA 20, o efeito Atordoado dura apenas duas rodadas. ita Bestiário RAPOSA (KITSUNE) 15 Raposas são pequenas criaturas vulpinas, parentes distantes"]], "nota": "- Polvos são criaturas aquáticas com oito tentáculos com corpos macios e moles, habitantes das águas da costa de Rokugan. Lulas são similares a polvos, mas têm um corpo mais rígido, alongado e tentáculos mais perigosos, além de uma boca maior e um bico."}, {"id": "idi_raposa_kitsune", "n": "Raposa (Kitsune)", "tipo": "fera", "fonte": "IdI p. 15", "an": [2, 1, 1, 1], "tr": "Reflexos 4, Vigor 2, Agilidade 3, Percepção 3", "ini": "5k4", "atq": [["Mordida", "4k3", "C", "2k2"]], "tn": 25, "red": 3, "fer": [[12, 10], [24, null]], "per": "Esportes 2, Furtividade 3", "hab": [["Veloz 2 doaThadeuHudsonEm", ""]], "nota": ""}, {"id": "idi_tigre_tora", "n": "Tigre (Torá)", "tipo": "fera", "fonte": "IdI p. 16", "an": [2, 3, 2, 3], "tr": "Reflexos 4, Vigor 4, Agilidade 4, Força 4", "ini": "5k4", "atq": [["Garras", "6k4", "C", "5k2"], ["Mordida", "4k4", "C", "—"]], "tn": 25, "red": 4, "fer": [[24, 10], [48, null]], "per": "Caça 4, Furtividade 4 FORÇA 2", "hab": [["Medo 2", ""], ["Veloz 1", ""]], "nota": "Tigres são imensos felinos predadores, ainda maiores que leões. Seu pelo é normalmente um padrão de branco, laranja e preto listrados, mas algumas raças não possuem a coloração laranja e tigres albinos ocasionalmente sejam relatados."}, {"id": "idi_tubarao_aoizame", "n": "Tubarão (Aoizame)", "tipo": "fera", "fonte": "IdI p. 16", "an": [1, 1, 2, 2], "tr": "Reflexos 4, Vigor 2, Agilidade 3", "ini": "4k4", "atq": [["Mordida", "4k3", "C", "4k2"]], "tn": 30, "red": 3, "fer": [[12, 10], [24, null]], "per": "Caça 5", "hab": [["Frenesi de Sangue", "Tubarões se enfurecem pela presença de sangue na água, que podem farejar a até 800 m de distância. Um tubarão em frenesi de sangue atacará a presa mais próxima mesmo se não estiver com fome. Enquanto estiver nesse estado alucinado, um tubarão tem +1k1 em todas as jogadas de Iniciativa, Ataque e Dano."], ["Veloz 4", ""], ["Vulnerabilidade", "Um Golpe Mirado no nariz do tubarão (2 Incrementos) causará um efeito de Medo 3 nele."]], "nota": "Há vários tipos de tubarão nativos das águas de Rokugan, muitos deles muito pequenos ou inofensivos para ameaçar humanos. A mais comum espécie perigosa, o aoizame (também chamado de mako) é um animal veloz e agressivo com cerca de 1,2 m de comprimento."}, {"id": "idi_tubarao_hohojirozame", "n": "Tubarão (Hohojirozame)", "tipo": "fera", "fonte": "IdI p. 17", "an": [1, 2, 1, 3], "tr": "Reflexos 3, Vigor 3, Agilidade 4, Força 4", "ini": "4k4", "atq": [["Mordida", "5k4", "C", "7k3"]], "tn": 25, "red": 5, "fer": [[18, 10], [36, null]], "per": "Caça 4", "hab": [["Frenesi de Sangue", "Tubarões se enfurecem pela presença de sangue na água, que podem farejar a até 800 m de distância. Um tubarão em frenesi de sangue atacará a presa mais próxima mesmo se não estiver com fome. Enquanto estiver nesse estado alucinado, um tubarão tem +1k1 em todas as jogadas de Iniciativa, Ataque e Dano."], ["Medo 2", ""], ["Imenso", ""], ["Veloz 4", ""], ["Vulnerabilidade", "Um Golpe Mirado ao nariz do tubarão (2 Incrementos) causará um efeito de Medo 3 sobre ele."]], "nota": "A maior raça de tubarão encontrada em águas rokuganis, o hohojirozame ou “tubarão de face branca” pode chegar a até 3 m de comprimento e tem mandíbulas poderosas o bastante para partir um homem adulto ao meio. Ele não gosta de comer humanos mas é um animal agressivo e é muito mais propenso a atacar "}, {"id": "idi_urso_kuma", "n": "Urso (Kuma)", "tipo": "fera", "fonte": "IdI p. 17", "an": [1, 6, 1, 2], "tr": "Reflexos 3, Agilidade 4, Força 7", "ini": "4k3", "atq": [["Garras", "6k4", "S", "7k3"], ["Mordida", "5k4", "C", "—"]], "tn": 20, "red": 9, "fer": [[30, 5], [60, 10], [90, null]], "per": "", "hab": [["Medo 2", ""], ["Veloz 3 (exceto em declives)", ""], ["Imenso oaThadeuHudsonEm “Cresceremos invisíveis nas sombras ", ""]], "nota": "Ursos são grandes mamíferos onívoros encontrados em todo o continente de Rokugan. As variedades mais comuns são o urso preto e o pardo."}, {"id": "idi_iuchiban_o_orador_de_sangue", "n": "Iuchiban, o Orador de Sangue", "tipo": "humano", "fonte": "IdI p. 30", "an": [6, 7, 5, 5, 6], "tr": "Inteligência 8, Percepção 6", "ini": "10k9", "atq": [["Faca", "10k5", "C", "7k1"]], "tn": 35, "red": 10, "fer": [[133, null]], "per": "Caligrafia 2, Corte (Manipulação) 5, Defesa 3, Etiqueta 5, Cavalaria 3, Intimidação (Controle) 6, Kenjutsu 3, Facas 5, Conhecimento: Gaijin 3, Conhecimento: Heráldica 4, Conhecimento: História 4, Conh", "hab": [], "nota": ""}, {"id": "idi_asahina_yajinden_o_artifice_do_sangue", "n": "Asahina Yajinden, o Artífice do Sangue", "tipo": "humano", "fonte": "IdI p. 32", "an": [7, 4, 4, 3, 5], "tr": "Inteligência 7, Percepção 6", "ini": "10k9", "atq": [["Faca", "10k4", "C", "4k1"]], "tn": 40, "red": 0, "fer": "h", "per": "Arte (várias) 2-5, Caligrafia 5, Corte 3, Criação: Mempo 4, Criação: Armas 10, Defesa 2, Etiqueta (Cortesia) 6, Facas 6, Conhecimento: Heráldica 3, Conhecimento: História 5, Conhecimento: Maho 6, Conh", "hab": [], "nota": ""}, {"id": "idi_jama_suru_o_general_de_iuchiban", "n": "Jama Suru, o General de Iuchiban", "tipo": "humano", "fonte": "IdI p. 33", "an": [4, 4, 5, 4, 2], "tr": "Reflexos 5, Percepção 6", "ini": "10k5", "atq": [["Katana", "10k5", "C", "7k2"]], "tn": 30, "red": 0, "fer": "h", "per": "Batalha 5, Corte 2, Defesa 4, Etiqueta 3, Intimidação (Controle) 4, Kenjutsu (Katana) 5, Facas 3, Conhecimento: Batalhas 3, Conhecimento: Heráldica 2, Conhecimento: Maho 7, Conhecimento: Terras Sombri", "hab": [], "nota": ""}, {"id": "idi_assassino_de_ataque_direto", "n": "Assassino de Ataque Direto", "tipo": "humano", "fonte": "IdI p. 46", "an": [4, 3, 4, 3, 2], "tr": "Força 4", "ini": "9k4", "atq": [["Katana", "8k4", "C", "7k2"], ["tanto", "9k4", "C", "—"]], "tn": 30, "red": 3, "fer": "h", "per": "Atuação 5, Esportes 2, Corte 2, Defesa 4, Etiqueta 2, Kenjutsu 4, Facas (Tanto) 5, Sinceridade 5, Furtividade (Esgueirar) 5 Vantagens: c Rápido c Conhecimento Proibido (Kolat) Desvantagens: c Segredo ", "hab": [], "nota": ""}, {"id": "idi_assassino_infiltrador", "n": "Assassino Infiltrador", "tipo": "humano", "fonte": "IdI p. 46", "an": [4, 3, 4, 2, 2], "tr": "Percepção 4", "ini": "9k4", "atq": [["Faca", "6k4", "C", "3k1"]], "tn": 25, "red": 0, "fer": "h", "per": "Atuação 5, Corte 4, Defesa 2, Etiqueta 4, Facas (Tanto) 6, Sinceridade (Ardil) 5, Furtividade 5 Vantagens: c Comum c Conhecimento Proibido (Kolat) Desvantagens: c Segredo Sombrio (Kolat)", "hab": [], "nota": ""}, {"id": "idi_comerciante_astuto", "n": "Comerciante Astuto", "tipo": "humano", "fonte": "IdI p. 47", "an": [4, 2, 2, 3, 4], "tr": "Inteligência 5, Percepção 4", "ini": "8k4", "atq": [["Wakizashi", "5k2", "C", "5k2"]], "tn": 25, "red": 0, "fer": "h", "per": "Atuação 5, Comércio (Matemática) 5, Corte 5, Etiqueta (Cortesia) 6, Falsificação 3, Investigação (Notar) 4, Intimidação 3, Kenjutsu 3, Conhecimento: Heráldica 3, Conhecimento: Lei 4, Sinceridade (Ardi", "hab": [], "nota": "Uma vasta rede de agentes e um igualmente vasto arsenal de armas e táticas exóticas não são baratos. Dentre os agentes dos Kolats está um pequeno exército de mercadores que fornecem à conspiração o dinheiro que ela precisa para continuar seus planos."}, {"id": "idi_mao_dos_mestres", "n": "Mão dos Mestres", "tipo": "humano", "fonte": "IdI p. 47", "an": [4, 4, 3, 3, 4], "tr": "Inteligência 5, Percepção 5", "ini": "8k4", "atq": [["Katana", "7k3", "C", "6k2"], ["tanto", "9k3", "C", "—"]], "tn": 25, "red": 0, "fer": "h", "per": "Atuação 5, Corte (Conversação) 5, Etiqueta (Cortesia) 6, Falsificação (Documentos) 6, Intimidação (Controle) 4, Investigação 4, Kenjutsu (Katana) 4, Facas (Tanto) 6, Sinceridade (Ardil) 7, Furtividade", "hab": [], "nota": "As Mãos dos Mestres estão entre mais altas elites dos agentes Kolats, respondendo diretamente aos Dez Mestres e cumprindo sua vontade no resto da conspiração. Eles são escolhidos cuidadosamente dentre os mais leais Kolats e estão normalmente sendo orientados à eventual liderança."}, {"id": "idi_yasuki_jinn_kuen_mestre_kolat", "n": "Yasuki Jinn-Kuen, mestre kolat", "tipo": "humano", "fonte": "IdI p. 48", "an": [4, 3, 4, 3, 4], "tr": "Inteligência 6, Percepção 5", "ini": "—", "atq": [], "tn": 30, "red": 0, "fer": "h", "per": "Treinar Animais (Falcões, Cavalos) 4, Caligrafia (Cifra) 5, Comércio (Avaliação, Matemática) 8, Corte (Manipulação) 7, Defesa 5, Etiqueta 6, Falsificação 4, Armas Pesadas 2, Intimidação (Controle) 7, ", "hab": [], "nota": "Brilhante e enérgico apesar de sua respeitosa idade, Yasuki Jinn-Kuen tem sorte de parecer muito mais jovem do que é, meramente uma das muitas ferramentas que ele emprega para garantir que outros o subestimem demais. Jinn-Kuen se uniu aos Kolats há tanto tempo que mal se lembra de sua vida antes da "}, {"id": "idi_doji_nashiko_a_noiva_demonio_de_fu_leng", "n": "Doji Nashiko, a Noiva Demônio de Fu Leng", "tipo": "humano", "fonte": "IdI p. 64", "an": [6, 5, 4, 4, 3], "tr": "Inteligência 6, Percepção 5", "ini": "—", "atq": [["Wakizashi", "7k4+8", "S", "10k4"], ["Garras Negras", "8k4+8", "S", "—"]], "tn": 35, "red": 0, "fer": [[95, null]], "per": "Atuação 8, Corte 6, Defesa 5, Etiqueta 7, Intimidação (Controle) 5, Investigação 4, Jiujutsu 4, Kenjutsu 3, Facas 4, Conhecimento (muitos) 3-6, Sinceridade (Ardil) 8, Furtividade 4, Tentação (Sedução)", "hab": [["Invulnerável Doji Nashiko era uma mulher vaidosa da era do C", ""]], "nota": ""}, {"id": "idi_hida_atarasi_o_primeiro_akutenshi", "n": "Hida Atarasi, o Primeiro Akutenshi", "tipo": "humano", "fonte": "IdI p. 65", "an": [3, 7, 4, 4, 5], "tr": "Reflexos 6, Vigor 10, Agilidade 7, Força 10", "ini": "—", "atq": [["Arma Pesada", "10k9+11", "S", "9k0"]], "tn": 45, "red": 15, "fer": [[197, null]], "per": "Esportes 5, Defesa 7, Armas Pesadas (Tetsubo) 8, Intimidação (Provocação) 5, Jiujutsu 8, Kenjutsu 5, Kyujutsu 3, Conhecimento: Terras Sombrias 4, Furtividade 3 Poderes das Terras Sombrias: Bênção do O", "hab": [["Avalanche de Atarasi", "Os golpes desarmados de Atarasi transmitem Mácula ao alvo. Toda vez que ele atacar alguém com um ataque desarmado, a vítima deve fazer um teste de Terra contra NA 20 ou ganhar 1-5 pontos de Mácula. Qualquer um que seja morto pelos ataques desarmados de Atarasi será ressuscitado como morto- -vivo 5 rodadas depois."], ["Invulnerável ita Hida Atarasi nasceu do mais forte dos Kamis", ""]], "nota": ""}, {"id": "idi_moto_tsume_general_das_terras_sombrias", "n": "Moto Tsume, General das Terras Sombrias", "tipo": "humano", "fonte": "IdI p. 66", "an": [6, 7, 5, 5, 4], "tr": "Percepção 6", "ini": "—", "atq": [["Katana", "10k6+11", "S", "10k5"]], "tn": 40, "red": 13, "fer": [[157, null]], "per": "Esportes 4, Batalha 9, Corte 2, Etiqueta 2, Cavalaria 7, Caça 4, Iaijutsu 3, Intimidação (Controle, Tortura) 9, Investigação 3, Jiujutsu 4, Kenjutsu (Katana) 8, Kyujutsu (Dai-Kyu) 4, Conhecimento: Ter", "hab": [["Invulnerável Se há um conto em Rokugan que resume os perigos", ""]], "nota": ""}, {"id": "idi_tsukuro_o_garca_caido", "n": "Tsukuro, o Garça Caído", "tipo": "humano", "fonte": "IdI p. 67", "an": [3, 4, 5, 4, 4], "tr": "Vigor 5, Percepção 6", "ini": "9k3", "atq": [["Katana", "10k6+8", "S", "10k4+2"]], "tn": 25, "red": 3, "fer": [[100, null]], "per": "Esportes 4, Batalha 6, Defesa 7, Cavalaria 3, Caça 4, Iaijutsu 5, Intimidação (Controle) 5, Investigação 3, Kenjutsu (Katana) 7, Facas 2, Kyujutsu 4, Lanças 5, Furtividade 4, Tentação 3 Poderes das Te", "hab": [["Invulnerável", ""], ["Morto-Vivo ita Os Perdidos Daidoji Tsukuro foi um guerreiro ", ""]], "nota": ""}, {"id": "idi_nezumi_roedor_guerreiro_tipico_nivel_2", "n": "Nezumi (Roedor) Guerreiro Típico (Nível 2)", "tipo": "povo", "fonte": "IdI p. 126", "an": [2, 3, 3, 3], "tr": "Reflexos 3, Agilidade 4", "ini": "5k3", "atq": [["Yari", "7k4", "C", "5k2"]], "tn": 25, "red": 3, "fer": "h", "per": "Esportes 4, Defesa 4, Jiujutsu 3, Caça (Sobrevivência) 3, Conhecimento: Terras Sombrias 3, Lanças 3, Furtividade 2 Habilidades Físicas Roedoras (incluem Veloz 2 e Imunidade à Mácula) Vantagens: c Forç", "hab": [], "nota": ""}, {"id": "idi_berserker_nezumi_chitatchikkan_tipico", "n": "Berserker Nezumi (Chitatchikkan) Típico", "tipo": "povo", "fonte": "IdI p. 127", "an": [2, 4, 4, 4], "tr": "Reflexos 5, Agilidade 6, Força 5", "ini": "10k5", "atq": [["Yari", "10k8", "S", "7k2"]], "tn": 40, "red": 5, "fer": "h", "per": "Esportes 7, Defesa 7, Jiujutsu 6, Caça (Sobrevivência) 5, Conhecimento: Terras Sombrias 6, Lanças 8, Furtividade 5 Habilidades Físicas Roedoras (incluem Veloz 2 e Imunidade à Mácula) Vantagens: c Gran", "hab": [], "nota": "(NÍVEL DE SABEDORIA 5)"}, {"id": "idi_coletor_nezumi_roedor_tipico_nivel_3", "n": "Coletor Nezumi (Roedor) Típico (Nível 3)", "tipo": "povo", "fonte": "IdI p. 127", "an": [4, 2, 3, 3], "tr": "Agilidade 5", "ini": "7k4", "atq": [["Yari", "8k5", "C", "4k1"]], "tn": 28, "red": 1, "fer": "h", "per": "Esportes 4, Defesa 5, Jiujutsu 3, Caça 5, Investigação 4, Facas 5, Conhecimento: Terras Sombrias 4, Furtividade (Esgueirar-se) 6, Mãos Rápidas 6 Habilidades Físicas Roedoras (incluem Veloz 2 e Imunida", "hab": [], "nota": ""}, {"id": "idi_xama_nezumi_roedor_tipico_nivel_3", "n": "Xamã Nezumi (Roedor) Típico (Nível 3)", "tipo": "povo", "fonte": "IdI p. 127", "an": [3, 3, 3, 2], "tr": "Reflexos 4, Percepção 3", "ini": "7k4", "atq": [["Yari", "7k3", "C", "5k2+6"]], "tn": 30, "red": 3, "fer": "h", "per": "Defesa 4, Caça 2, Conhecimento: Terras Sombrias 5, Conhecimento: Reinos Espirituais (Yume-dô) 5, Meditação 5, Performance: Dança Nezumi 2, Lanças 4, Furtividade 3. Feitiços: Dobrar Nome, Andar no Sonh", "hab": [], "nota": ""}, {"id": "idi_lembrador_nezumi_roedor_tipico_nivel_3", "n": "Lembrador Nezumi (Roedor) Típico (Nível 3)", "tipo": "povo", "fonte": "IdI p. 127", "an": [3, 3, 3, 3], "tr": "", "ini": "6k3", "atq": [["Faca", "7k3", "C", "4k1"]], "tn": 20, "red": 0, "fer": "h", "per": "Esportes 3, Defesa 2, Caça 2, Facas 4, Conhecimento: Terras Sombrias 4, Conhecimento: Cultura Nezumi 5, Conhecimento: História Nezumi 5, Meditação 4, Performance: Narração 5, Furtividade 3 Varetas de ", "hab": [], "nota": ""}, {"id": "idi_cria_da_sombra", "n": "Cria da Sombra", "tipo": "sombrio", "fonte": "IdI p. 147", "an": [3, 5, 3, 4], "tr": "Reflexos 4, Agilidade 4, Força 5", "ini": "6k4", "atq": [["Garras", "6k4", "S", "5k2"], ["qualquer arma", "6k4", "C", "de acordo NA Armadura: 25 com "]], "tn": 25, "red": 10, "fer": [[96, null]], "per": "Atuação 4, Sinceridade (Ardil) 4, Furtividade 5", "hab": [["Medo 3 (quando revelada como Cria da Sombra)", ""], ["Veloz 1", ""], ["Coesão da Sombra", "Uma Cria da Sombra Maior não sente dor e assim não sofre penalidades por Ferimentos. Ela continua a funcionar com força total até ser reduzida a Morto."], ["Invulnerabilidade Parcial", "Crias da Sombra Maiores sofrem metade do dano (arredondado para baixo) de armas que não sejam de cristal e feitiços que não sejam de Vazio e outros efeitos mágicos que não sejam especialmente destinados a afetar o Nada e seus lacaios. Armas de cristal e feitiços de Vazio as afetam normalmente."], ["Resistência Mental", "Crias da Sombra Maiores são imunes a todos os efeitos de Medo e a todos os feitiços que criam ilusões ou influenciam a mente ou pensamentos."], ["Poderes Sombrios", "Uma Cria da Sombra Maior tem todos os poderes e obstáculos de Nível de Sombra 5, incluindo metamorfose. De fato, ela pode assumir a forma e identidade de qualquer pessoa que ela tenha sido capaz de observar por uma Rodada completa — esta metamorfose requer uma Ação Complexa. Contato com cristal ou luz refletida através do cristal revelará sua forma verdadeira. Porém, diferente de Crias da Sombra M"], ["Raio de Sombra", "Uma Cria da Sombra Maior pode invocar um Raio de Sombra uma vez por dia, em qualquer alvo em sua linha de visão."]], "nota": ""}, {"id": "idi_besta_sombria", "n": "Besta Sombria", "tipo": "sombrio", "fonte": "IdI p. 147", "an": [2, 5, 3, 2], "tr": "Reflexos 4, Agilidade 4, Força 6", "ini": "5k4", "atq": [["Garras", "7k4", "S", "7k3"]], "tn": 25, "red": 12, "fer": [[24, 5], [48, 10], [72, 15], [96, null]], "per": "", "hab": [["Medo 3", ""], ["Veloz 2", ""], ["Invulnerabilidade", ""], ["Resistência Mental", "Feras Sombrias são imunes a todos os efeitos de Medo e a todos os feitiços que criam ilusões ou influenciam a mente ou pensamentos."], ["Poderes Sombrios", "Uma Fera Sombria tem todos os poderes e obstáculos de Nível de Sombra 3."], ["Uivo Vingativo", "Duas vezes por dia como Ação Complexa, uma Fera Sombria pode liberar um uivo aterrador que tira o poder de quaisquer oponentes Maculados que o ouçam. Todas as criaturas com Nível de Mácula 2 ou mais a 30 m da Fera Sombria automaticamente sofrem 2k2 Ferimentos. Para cada criatura afetada, a Fera Sombria ganha um bônus de +1k0 em suas rolagens de ataque por 1 hora depois. doaThadeuHudsonEm “Tais hor"]], "nota": ""}, {"id": "idi_akaru_no_oni_o_senhor_das_teias", "n": "Akaru no Oni, o Senhor das Teias", "tipo": "oni", "fonte": "IdI p. 154", "an": [3, 4, 1, 4], "tr": "Agilidade 4", "ini": "4k3", "atq": [["Garras", "6k4", "S", "4k4"], ["Mordida", "4k4", "C", "6k4"]], "tn": 20, "red": 5, "fer": [[25, 5], [50, 10], [75, null]], "per": "", "hab": [["Lançar Teia", "Akaru no Oni podem projetar poderosas teias de uma grossa substância adesiva para prender e confinar seus inimigos. Esta é uma Ação Complexa que não causa dano, mas o alvo é automaticamente Preso. O NA para escapar da condição Preso é 20."], ["Armadilhas de Teias", "Akaru no Oni espalha suas teias onde a presa pode entrar em contato com ela por acidente. Qualquer um que esbarre nas teias do oni é imediatamente Preso, com NA 20 para escapar."]], "nota": "A ameaça de onis é constante para os batedores Caranguejos que se aventuram nas Terras Sombrias, pois os demônios vagam por todo esse reino, destruindo qualquer criatura viva que não porte o toque do Jigoku. Akaru no Oni, pelo menos, é uma ameaça que os Hiruma sabem que não precisam temer, contanto "}, {"id": "idi_arugai_no_oni_maquina_imortal_de_destrui", "n": "Arugai no Oni, Máquina Imortal de Destruição", "tipo": "oni", "fonte": "IdI p. 154", "an": [4, 7, 2, 6], "tr": "Vigor 8, Agilidade 5, Força 8", "ini": "9k4", "atq": [["Garras", "10k5", "S", "10k4"], ["Cauda", "10k5", "S", "—"], ["Chifres", "10k5", "S", "—"]], "tn": 25, "red": 20, "fer": [[50, 5], [100, 10], [150, 15], [200, null]], "per": "", "hab": [["Medo 5", ""], ["Imenso", ""], ["Quase Imortal", "Um Arugai no Oni é praticamente impossível de matar. Durante o Estágio de Reações de toda Rodada, o oni regenera 10 Ferimentos. Esta regeneração não para quando o oni é morto, e assim que recuperar quaisquer Ferimentos, ele se levantará dos mortos e continuará lutando. O único meio de realmente matar um Arugai no Oni é encontrar e destruir seu coração. Dizem que o coração da criatura não é maior d"], ["Invulnerabilidade Superior", "Um Arugai no Oni é invulnerável a fogo (mundano e mágico) além de resistir a armas mundanas. c"], ["Veloz 2 Golpe de Cauda", "Um Arugai no Oni pode usar sua cauda para realizar ataques de Derrubada, e ganha um Incremento Livre ao fazê-lo."]], "nota": "Há muito poucos Arugai no Oni, o que é uma coisa boa para Rokugan. Estas máquinas irrefreáveis de destruição foram geradas nos poços de lava do Jigoku."}, {"id": "idi_byoki_no_oni_arauto_da_pestilencia", "n": "Byoki no Oni, Arauto da Pestilência", "tipo": "oni", "fonte": "IdI p. 155", "an": [2, 5, 2, 3], "tr": "Agilidade 3", "ini": "3k2", "atq": [["Garras", "4k2", "C", "3k3"]], "tn": 15, "red": 2, "fer": [[30, 5], [60, 10], [90, null]], "per": "", "hab": [["Medo 2", ""], ["Barreira de Praga", "Byoki no Oni podem infligir horríveis doenças com um simples toque. Após um ataque bem sucedido a um alvo, o oni e seu oponente devem fazer um Teste Disputado de Terra. Se o oni vencer, o oponente é afligido por uma doença virulenta. A cada dia subsequente, o alvo deve fazer um Teste de Terra contra NA 15 ou perder 1 Nível em todos os Atributos físicos. Três testes bem sucedidos consecutivos curam"], ["Respingo", "Sempre que um ataque bem sucedido é feito contra um Byoki no Oni, o respingar de fluidos afeta todos dentro de 1,5 m. Eles devem fazer Testes Disputados de Terra como se o oni os tocasse (como descrito em Barreira de Praga, acima). ita"]], "nota": "Há pouquíssimas entidades nas Terras Sombrias mais repulsivas do que a forma infestada dos Byoki no Oni. Estas criaturas rançosas são repletas de doenças virulentas — algumas delas os acompanham desde que rastejaram para fora do Poço Infecto, enquanto outras eles acumularam no caminho."}, {"id": "idi_daku_no_oni_flagelo_da_floresta", "n": "Daku no Oni, Flagelo da Floresta", "tipo": "oni", "fonte": "IdI p. 155", "an": [3, 4, 3, 3], "tr": "Agilidade 4, Força 5", "ini": "6k3", "atq": [["Garras", "6k4", "S", "5k2"]], "tn": 25, "red": 8, "fer": [[32, 5], [48, 10], [72, null]], "per": "", "hab": [["155", ""], ["Sem Olhos", "Daku no Oni não podem ver, embora fun- cionem normalmente e não sofram penalidades por cegueira. Feitiços e efeitos que dependem da visão (como ilusões) ou que se destinam a obstruir a visão não têm efeito em Daku no Oni."], ["Medo 2", ""], ["Casca Flamejante", "Daku no Oni podem quebrar pedaços flamejantes de si mesmos e atirar nos inimigos. O Daku no Oni joga 6k3 para atacar com esta casca flamejante, com alcance máximo de 9 m. A casca tem ND 3k2 e pode incendiar objetos inflamáveis."], ["Regeneração Flamejante", "Daku no Oni sofrem dano total de fogo mágico, mas regeneram tal dano durante o estágio de Reações da mesma Rodada (a menos que estejam mortos)."], ["Invulnerabilidade Parcial", "Daku no Oni são invulneráveis a chamas normais, embora chamas mágicas os danifiquem normalmente."], ["Incendiado", "Daku no Oni estão constantemente pegando fogo. Qualquer coisa inflamável pegará fogo se eles a tocarem. Por causa destas chamas, qualquer um que ataque um Daku no Oni com ataques desarmados ou armas Pequenas sofrerá 3k2 Ferimentos. Atacantes que usem armas Médias sofrem 2k1 Ferimentos, e atacantes usando armas Grandes ou ataques a distância não sofrem Ferimentos (embora suas armas peguem fogo se f"]], "nota": "Daku no Oni lembram árvores perpetuamente queimando. Eles têm pele escura e apêndices semelhantes a galhos nascendo de seu tronco e cabeça."}, {"id": "idi_furu_no_oni_oni_unico", "n": "Furu no Oni, Oni Único", "tipo": "oni", "fonte": "IdI p. 156", "an": [6, 8, 8, 6], "tr": "Inteligência 9, Força 8", "ini": "10k8", "atq": [["Tentáculos  (Simples", "10k10+2", "S", "10k5"]], "tn": 40, "red": 25, "fer": [[80, 5], [160, 10], [240, 15], [320, null]], "per": "", "hab": [["Sangue Fervente", "O sangue de Furu no Oni é fogo derretido, e queima tudo o que tocar. Qualquer um que ferir o oni em combate corporal deve fazer um teste de Defesa/Reflexos (NA 40 para ataques desarmados ou com armas Pequenas, NA 35 para ataques com armas Médias, e NA 30 para ataques com armas Grandes) para evitar ser atingido pelo sangue fervente. Falha significa que o atacante sofre 5k5 de dano (e deve jogar con"], ["Gerar Cria", "Furu no Oni pode, como Ação Complexa, imbuir o cadáver de um naga com sua própria essência maligna. O cadáver se ergue como uma cria de Furu no Oni no Estágio de Reações da Rodada seguinte."], ["Calor Extremo", "O ar em torno de Furu no Oni é tão quente que incendeia itens inflamáveis, consumindo-os. Flechas não mágicas atiradas em Furu no Oni são consumidas pelo fogo antes de atingi-lo, não causando dano ao oni."], ["Medo 5", ""], ["Ataque de Empalamento Ígneo", "Se Furu no Oni controla uma Imobilização no começo de seu Turno, ele pode, como Ação Simples, arrastar o oponente Imobilizado para seu corpo coberto de espinhos e empalá-lo em seus espinhos. Os espinhos causam 3k3 de dano no oponente na primeira Rodada da Imobilização (apenas). Além disso, contato com o sangue ígneo exposto causa 4k4 de dano por fogo toda Rodada em que Furu no Oni mantém sua Imobi"], ["Visão de Chamas", "As chamas dentro de seu coração revelam a verdade a Furu no Oni. Ele ganha +4k0 em todas as jogadas para detectar os que estão usando Furtividade para esconder-se dele, e é imune a todos os feitiços que criam ilusões ou outro modo de mascarar a verdade."], ["Atirar Sangue Flamejante", "Furu no Oni pode atirar parte de seu sangue fervente em oponentes dentro de 9 m. Esta é uma Ação Simples com jogada de ataque de 10k9, causando 4k4 de dano de fogo se atingir o alvo. O sangue continua a queimar até o estágio de Reações da Rodada posterior em que foi arremessado, causando mais 2k2 Ferimentos de dano de fogo a menos que tenha sido lavado antes."], ["Muitos Tentáculos", "Os tentáculos de Furu no Oni são normalmente manobras de ataque Simples. Porém, se ele usar uma Ação Complexa, ele pode usar até quatro de seus tentáculos de uma vez. Até dois destes ataques podem ser tentativas de Imobilização."], ["Vulnerabilidade a Pérolas", "Por sua conexão à mente comunal dos Nagas, Furu no Oni é vulnerável à magia de pérolas dos Nagas. Qualquer feitiço de magia de pérola que afete Furu no Oni ganha três Incrementos Livres."]], "nota": ""}, {"id": "idi_cria_de_furu_no_oni", "n": "Cria de Furu no Oni", "tipo": "oni", "fonte": "IdI p. 157", "an": [4, 4, 6, 4], "tr": "Força 5", "ini": "8k5", "atq": [["Tentáculos", "8k6", "S", "6k3"]], "tn": 30, "red": 10, "fer": [[24, 5], [48, 10], [72, 15], [96, null]], "per": "", "hab": [["Sangue Fervente", "O sangue da cria de Furu no Oni é fogo derretido, e queima tudo o que tocar. Qualquer um que ferir o oni em combate corporal deve fazer um teste de Defesa/Reflexos (NA 25 para ataques desarmados ou com armas Pequenas, NA 20 para ataques com armas Médias, e NA 15 para ataques com armas Grandes) para evitar ser atingido pelo sangue fervente. Falha significa que o atacante sofre 2k2 de dano (e deve j"], ["Medo 3", ""], ["Ataque de Empalamento Ígneo", "Se uma cria de Furu no Oni controla uma Imobilização no começo de seu Turno, ela pode, como Ação Simples, arrastar o oponente Imobilizado para seu corpo coberto de espinhos e empalá-lo em seus espinhos. Os espinhos causam 2k1 de dano no oponente na primeira Rodada da Imobilização (apenas). Além disso, contato com o sangue ígneo exposto causa 2k2 de dano por fogo a cada Rodada em que o Furu no Oni "], ["Atirar Sangue Flamejante", "Crias de Furu no Oni podem atirar parte de seu sangue fervente em oponentes dentro de 9 m. Esta é uma Ação Simples com jogada de ataque de 8k4, infligindo 2k2 de dano de fogo se atingir."], ["Muitos Tentáculos", "Os tentáculos de Furu no Oni são normalmente manobras de ataque Simples. Porém, se ele usar uma Ação Complexa, ele pode usar até três de seus tentáculos de uma vez. Um destes ataques pode ser uma tentativa de Imobilização. itad"], ["Vulnerabilidade a Pérolas", "Por sua conexão à mente comunal dos nagas, Furu no Oni é vulnerável à magia de pérolas dos nagas. Qualquer feitiço de magia de pérola que afete Furu no Oni ganha três Incrementos Livres."], ["Invulnerabilidade Parcial", "Crias de Furu no Oni são invulneráveis a fogo (mágico e mundano) mas sofrem dano normal de todos os outros ataques."], ["Veloz 2", ""]], "nota": ""}, {"id": "idi_gagoze_no_oni_praga_da_floresta", "n": "Gagoze no Oni, Praga da Floresta", "tipo": "oni", "fonte": "IdI p. 157", "an": [3, 4, 5, 4], "tr": "Reflexos 4", "ini": "4k4", "atq": [["Garras", "5k5", "S", "4k4"]], "tn": 25, "red": 5, "fer": [[25, 1], [50, 5], [75, 10], [125, 15], [150, null]], "per": "Defesa 4, Caça 6, Intimidação 4, Jiujutsu 4, Feitiçaria 5, Furtividade 6", "hab": [["Medo 3", ""], ["Imenso", ""], ["Invulnerável", ""], ["Domínio de", ""]], "nota": "A entidade singular conhecida como Gagoze no Oni talvez seja a única de sua raça que não veio por um portal do Jigoku nem foi invocada pela vontade de um mortal — ao menos não ao que se sabe. Ao invés disso, a besta rastejou totalmente formada de um pântano chamado de Charco das Terras Sombrias na S"}, {"id": "idi_genso_no_oni_guerreiro_negro", "n": "Genso no Oni, Guerreiro Negro", "tipo": "oni", "fonte": "IdI p. 158", "an": [3, 4, 4, 4], "tr": "Reflexos 5", "ini": "5k5", "atq": [["Katana de obsidiana", "9k4", "S", "7k2"], ["Garras", "8k4", "S", "4k4"]], "tn": 30, "red": 4, "fer": [[40, 5], [80, 10], [120, 15], [160, 20], [240, null]], "per": "Esportes 3, Defesa 4, Caça 7, Iaijutsu 5, Jiujutsu 4, Kenjutsu 5, Furtividade 4", "hab": [["Medo 3", ""], ["Daisho de Obsidiana", "Genso no Oni carrega um imenso daisho feito de obsidiana. As lâminas parecem ser espiritualmente conectadas à criatura e não sobrevivem à sua morte — se uma ou ambas forem roubadas antes de sua morte, o Genso no Oni caçará o ladrão até os confins da terra. Por sua íntima conexão às espadas, Genso no Oni não pode ser afetado pela Manobra Desarme."], ["Provocações", "Genso no Oni é incrivelmente capaz de perceber as culpas e arrependimentos da alma humana, e irrita os que o enfrentam com as mais horrendas acusações e insultos imagináveis, ofendendo a fé, decência humana e o Código do Bushidô. Durante a primeira Rodada de uma luta contra Genso no Oni, todo oponente rokugani deve fazer um Teste Disputado de Vontade contra ele. Se falhar, seu maior Nível de Escol"]], "nota": "O Genso no Oni é uma lenda nas Terras Sombrias, famoso mesmo entre os Perdidos e temido por outros onis que parecem ser mais poderosos. É dolorosamente bem conhecido pelo Caranguejo, embora poucos samurais de outros clãs já tenham ouvido falar dele."}, {"id": "idi_ianwa_no_oni_negociador_negro", "n": "Ianwa no Oni, Negociador Negro", "tipo": "oni", "fonte": "IdI p. 159", "an": [3, 3, 2, 3], "tr": "Inteligência 6, Percepção 6", "ini": "3k3", "atq": [["Garras", "2k2", "C", "3k3"]], "tn": 20, "red": 3, "fer": [[12, 5], [24, 10], [36, 15], [48, null]], "per": "Intimidação (Controle) 7, Tentação 8", "hab": [["Exigências Negras", "Se um mortal falhar em resistir ao efeito de Medo ampliado de Ianwa (vide a seguir), ele deve gastar um Ponto de Vazio por dia para resistir à exigência de Ianwa. Se ele não puder gastar Pontos de Vazio, ele deve obedecer. Sempre que ele obedecer, ele ganha 1-5 pontos de Mácula. Além disso, cada vez que Ianwa no Oni voltar a usar sua Ampliação de Medo na mesma vítima, o número de Pontos de Vazio q"], ["Medo 5", ""], ["Ampliação de Medo", "Ao enfrentar um indivíduo isolado, uma vez por encontro Ianwa no Oni pode aumentar seu efeito de Medo, projetando uma aura de terror que é quase completamente irresistível. Contra um só alvo, o efeito de Medo de Ianwa no Oni é aumentado para 8."], ["Invulnerável", ""], ["Teleporte", "Como Ação Complexa, Ianwa no Oni pode desaparecer de sua atual posição e aparecer em qualquer outro lugar nas Terras Sombrias ou Rokugan. Poderosas proteções mágicas podem bloquear este movimento, mas de outro modo, ele é irrestrito."]], "nota": ""}, {"id": "idi_kamu_no_oni_a_mandibula_assassina", "n": "Kamu no Oni, a Mandíbula Assassina", "tipo": "oni", "fonte": "IdI p. 159", "an": [2, 5, 2, 3], "tr": "Reflexos 3, Agilidade 4, Força 6", "ini": "3k3", "atq": [["Mordida", "4k4", "C", "7k5"], ["Garra", "7k4", "S", "—"]], "tn": 25, "red": 5, "fer": [[50, 5], [125, 20], [150, null]], "per": "Intimidação (Controle) 7, Tentação 8", "hab": [["Devorar", "Se um Kamu no Oni controlar uma Imobilização, ele pode infligir dano de mordida no oponente Imobilizado ao invés de seu dano de garras. Se este dano reduzir um oponente para o Nível de Ferimentos Inconsciente, ele foi engolido e morrerá no Estágio de Reações da Rodada seguinte a menos que seja libertado de algum modo ou o Kamu no Oni morra. Onis"], ["Medo 4", ""], ["Invulnerável 159", ""]], "nota": "O horripilante Kamu no Oni está entre os mais reconhecíveis de todos os onis, e tamanha impressão eles causaram nas raras ocasiões em que apareceram no Império que sua forma pode ser identificada por quase qualquer samurai educado. Kamu no Oni é uma máquina quase irracional de matar sem órgãos senso"}, {"id": "idi_kommei_no_oni_demonio_da_confusao", "n": "Kommei no Oni, Demônio da Confusão", "tipo": "oni", "fonte": "IdI p. 160", "an": [5, 5, 3, 3], "tr": "Força 4", "ini": "7k4", "atq": [["Garras", "7k3", "S", "6k3"]], "tn": 25, "red": 10, "fer": [[20, 5], [40, 10], [60, 15], [80, null]], "per": "Atuação 5, Corte 4, Etiqueta 4, Sinceridade (Ardil) 5", "hab": [["Visão Total", "Se um Kommei no Oni for capaz de expor os olhos de sua nuca, ele ganha dois Incrementos Livres em quaisquer rolagens de Investigação (Notar)/ Percepção para impedir que seja surpreendido."], ["Articulações Duplas", "Pela bizarra flexibilidade de suas juntas, Kommei no Oni não sofrem penalidades de combate por estarem Prostrados, e podem se levantar como Ação Livre."], ["Medo 3", ""], ["Metamorfose", "Como Ação Complexa, o Kommei no Oni pode mudar sua forma física e roupa para a forma de qualquer um cuja alma ele tenha devorado. Quando ele o faz, ele ganha três Perícias da pessoa que está 160 imitando conhecia, e o Nível em que ela as possuía."], ["Sugar Espírito", "O Kommei no Oni pode exalar uma Onis névoa amarela tóxica como Ação Simples, com alcance de 1,5 m. A névoa dura um número de Rodadas igual ao Ar do oni. Os que estão dentro da névoa devem fazer um Teste de Vigor com NA 25 a cada Rodada para segurarem o fôlego. Se uma vítima falhar no teste de Vigor e inalar, ela deve fazer um teste de Vontade com NA 25 durante o Estágio de Reações desta Rodada e e"], ["Trocar Espíritos", "Se duas ou mais vítimas inalarem a névoa e falharem no teste de Vontade na mesma Rodada, ao invés de suas almas serem devoradas, elas trocam de lugar aleatoriamente. A consciência de cada pessoa que falha é colocada no corpo de um dos outros. Cada vítima mantém todas as Perícias e Atributos mentais, bem como Vantagens e Desvantagens Mentais, mas ganha os Atributos, Vantagens e Desvantagens físicas"]], "nota": "Kommei no Oni adoram o caos. Felizmente poucos desses demônios já existiram, embora seja possível haver muitos vivendo no Império e nas Terras Sombrias que não foram notados."}, {"id": "idi_espelho_negro", "n": "Espelho Negro", "tipo": "oni", "fonte": "IdI p. 160", "an": [4, 4, 3, 4], "tr": "Inteligência 4, Percepção 5", "ini": "4k1", "atq": [["Pseudópodo", "4k3", "C", "4k1"]], "tn": 10, "red": 8, "fer": [[12, 5], [24, 10], [36, 15], [48, null]], "per": "Investigação 3, Furtividade (Emboscada) 6", "hab": [["Forma e Cor Maleáveis", "O Manesuru no Oni pode mudar sua forma e cor à vontade, concedendo-o três Incrementos Livres em testes de Perícia Furtividade para se esconder."], ["Resistência Mágica", "O Manesuru no Oni pode alterar sua forma para absorver e defletir as mais extremas forças elementais. Isto dificulta o efeito de magia elemental sobre o demônio, concedendo ao Manesuru no Oni a Vantagem Resistência Mágica."], ["Gerar Reflexo Negro", "Uma vez que um Manesuru no Oni tenha estudado uma criatura (usando sua habilidade Incrível Sabedoria) ele cria uma duplicata a partir de sua própria carne. O oni pode criar um número máximo de duplicatas igual ao seu Nível de Mácula, mas não pode copiar uma criatura específica novamente num período de vinte e quatro horas. A duplicata negra é sempre de cor preta translúcida, mas fora isso, totalme"], ["Incrível Sabedoria", "O Manesuru no Oni tem sentidos que vão além dos de seres mortais. Se o Demônio do Espelho Negro passar duas Ações Complexas estudando uma criatura, ele é capaz de duplicar esta criatura. Se uma criatura tiver defesas que previna outros de lerem sua mente, o Manesuru no Oni deve fazer uma jogada de Investigação/Astúcia contra o Nível de Sabedoria do alvo x 5 para romper suas defesas."]], "nota": "Manesuru no Oni estão entre os mais mortais inimigos que um samurai poderá enfrentar, pois eles forçam os samurais a lutarem contra oponentes que são tão bem treinados quanto eles e conhecem suas forças e fraquezas. Em sua forma natural, Manesuru no Oni são massas amorfas de protoplasma preto, lenta"}, {"id": "idi_morei_no_oni_o_demonio_dos_graos", "n": "Morei no Oni, o Demônio dos Grãos", "tipo": "oni", "fonte": "IdI p. 161", "an": [2, 2, 1, 1], "tr": "Força 2", "ini": "3k2", "atq": [["Garras", "3k2", "C", "3k1"]], "tn": 15, "red": 10, "fer": [[12, 5], [24, 10], [36, null]], "per": "", "hab": [["Imóvel", "Morei no Oni são árvores e não podem se mover."], ["Gerar Semente", "Todo dia, o Morei no Oni pode soltar até mil sementes que se parecem com grãos de arroz. Se uma semente for engolida, a vítima começa a sofrer dano na Rodada seguinte ao ritmo de 1k1 Ferimentos por Rodada (estes Ferimentos não estão sujeitos a Redução). A semente pode ser morta se a vítima ingerir um pedaço de jade ou cristal, ou uma dose de pó de jade. O feitiço Paz dos Kamis também matará a seme"]], "nota": "Morei no Oni são bastante inofensivos, ao menos pelos padrões CORROMPIDA de onis. Eles se parecem com saudáveis árvores marrons com folhas que exibem tons verdes, como se estivessem acordando do sono do inverno."}, {"id": "idi_muduro_no_oni_a_montanha_corrompida", "n": "Muduro no Oni, a Montanha Corrompida", "tipo": "oni", "fonte": "IdI p. 161", "an": [3, 7, 2, 4], "tr": "Agilidade 3, Força 8", "ini": "6k3", "atq": [["Garras", "7k3", "S", "10k3"], ["Mordida", "8k3", "C", "—"]], "tn": 15, "red": 20, "fer": [[100, 5], [150, 10], [200, null]], "per": "", "hab": [["161", ""], ["Medo 4", ""], ["Imenso", ""], ["Invulnerável", ""], ["Engolir Inteiro", "Se um Muduro no Oni acertar seu ataque de Mordida ele pode tentar engolir a vítima inteira. O Muduro no Oni e a criatura que ele mordeu fazem um Teste Disputado de Força. Se o Muduro no Oni vencer o teste, ele engole a criatura — caso contrário, a criatura se liberta de suas mandíbulas. Criaturas engolidas sofrem 3k3 Ferimentos e automaticamente ganham um 1 ponto de Mácula das Terras Sombrias dura"]], "nota": ""}, {"id": "idi_nairu_no_oni_flagelo_dos_ceus", "n": "Nairu no Oni, Flagelo dos Céus", "tipo": "oni", "fonte": "IdI p. 162", "an": [3, 2, 2, 2], "tr": "Agilidade 4, Força 4", "ini": "4k3", "atq": [["Garras", "6k4", "S", "4k4"]], "tn": 20, "red": 4, "fer": [[20, 5], [40, 10], [60, 15], [80, null]], "per": "", "hab": [["Ataque Rasante", "Nairu no Oni preferem lutar no ar, circulando por cima então descendo para atacar sua presa. Um Nairu que faça um ataque rasante de uma altura de pelo menos doze metros ganha um bônus de +1k1 em sua jogada de ataque (isto se acumula com quaisquer bônus de Ataque Total) mas após o ataque ser resolvido, o oni não pode mais voar e automaticamente fica Prostrado."], ["Medo 2", ""], ["Invulnerável", ""], ["Veloz 3 (quando voando)", ""]], "nota": "Pesados e reptilianos em aparência, os Nairu no Oni são na verdade oponentes extremamente ágeis assim que galgam o ar com suas poderosas asas de couro. Eles assolam o Caranguejo com táticas aéreas durante ataques em larga escala à Muralha Kaiu."}, {"id": "idi_nosloc_no_oni_vassalo_dos_lordes_demonio", "n": "Nosloc no Oni, Vassalo dos Lordes Demônios", "tipo": "oni", "fonte": "IdI p. 162", "an": [2, 4, 3, 4], "tr": "Reflexos 3, Agilidade 4", "ini": "5k3", "atq": [["Arma Pesada", "7k4", "C", "8k2"], ["Garras", "6k4", "C", "—"]], "tn": 20, "red": 5, "fer": [[16, 5], [24, 10], [32, 15], [48, 20], [80, null]], "per": "Batalha 2, Defesa 2, Armas Pesadas 3, Jiujutsu 3", "hab": [["Astúcia do Campo de Batalha", "Diferentemente de muitas das criaturas das Terras Sombrias, os Nosloc no Oni gostam de trabalhar em conjunto entre si. Para cada outro Nosloc no Oni dentro de 15 m, o demônio ganha um bônus de +1 no total de todas as jogadas de ataque, dano e Perícia Batalha."], ["Medo 2", ""], ["Invulnerável", ""]], "nota": "Os Nosloc no Oni são uma curiosa raça de onis descendentes de um ou mais progenitores que rasgaram seu caminho para fora do Poço Infecto há centenas de anos. Eles variam de dois a três metros de altura e físico poderoso, com músculos saltados e membros grossos."}, {"id": "idi_pekkle_no_oni_o_enganador", "n": "Pekkle no Oni, o Enganador", "tipo": "oni", "fonte": "IdI p. 163", "an": [5, 3, 2, 2], "tr": "Inteligência 5, Percepção 5", "ini": "5k5", "atq": [["Garras", "4k2", "C", "4k3"]], "tn": 30, "red": 0, "fer": [[20, 5], [30, 10], [40, 15], [80, null]], "per": "Atuação (Clã, Sexo, Profissão) 6, Corte (Manipulação) 3, Etiqueta 3, Sinceridade 5, Tentação 4", "hab": [["Escuridão Oculta", "A Mácula de um Pekkle no Oni não pode ser detectada por nenhum meio conhecido, embora outros Pekkle no Oni (e Pekkles não corrompidos) imediatamente reconheçam sua raça. O sangue do Pekkle no Oni é preto, logo ferir um é um meio eficaz de expor sua natureza. Efeitos mágicos que afetem indiscriminadamente a Mácula, como efeitos em área ou Onis proteções, não afetam Pekkle no Oni de maneira alguma. "], ["Poder das Terras Sombrias", "Garras Negras"], ["Mudar de Forma", "Pekkle no Oni podem, como Ação Complexa, mudar sua forma para a de um ser humano. Eles podem ser de qualquer gênero e idade, de criança a jovem adulto. O limite máximo parece ser em torno de 30 anos de idade. Nenhum Pekkle jamais demonstrou habilidade de parecer com uma forma não humana ou um humano idoso."]], "nota": "“Mas não é uma graça! Quem é sua mãe, pequenino?” De todas as ameaças de infiltração criadas pelas Terras Sombrias, talvez nenhuma tenha sido tão bem sucedida e perigosa quanto os Pekkle no Oni."}, {"id": "idi_morte_calma", "n": "Morte Calma", "tipo": "oni", "fonte": "IdI p. 164", "an": [1, 2, 1, 4], "tr": "Reflexos 3, Vigor 5, Agilidade 4", "ini": "3k3", "atq": [["Toque", "4k4", "C", "4k1"]], "tn": 20, "red": 10, "fer": [[30, 5], [60, 10], [120, null]], "per": "Caça 4, Furtividade 5", "hab": [["Amorfo", "A Morte Calma não contém órgãos vitais ou fisiologia importante, consistindo exclusivamente de uma substância macia, fluida e quase gelatinosa. Esta é a razão da alta Redução da criatura contra armas cortantes. 164"], ["Asfixia", "A Morte Calma pode tentar sufocar uma vítima Imobilizando-a — ela joga 8k4 de Iniciativa para controlar uma Imobilização. Ao controlar uma ImobiOnis lização, a Morte Calma pode causar dano como Ação Complexa. Esse dano começa em 3k3 e aumenta em +1k1 a cada Rodada seguida em que ela mantiver o controle. Se a Morte Calma perder o controle da Imobilização e posteriormente recuperá-lo, o dano começa "], ["Suscetibilidade", "A Morte Calma é particularmente suscetível a fogo, que rapidamente a desidrata e queima sua carne. Dano de qualquer fonte que inclua fogo causa +2k2 de dano adicionais à Morte Calma."]], "nota": "A entidade chamada de Morte Calma é um oni menor, um caçador quase irracional que procura estrangeiros isolados e os consome totalmente. Ele é astuto, apesar de sua falta de funções mentais superiores, e pode evitar captura bem facilmente."}, {"id": "idi_cria_de_akuma_no_oni", "n": "Cria de Akuma no Oni", "tipo": "oni", "fonte": "IdI p. 164", "an": [5, 5, 4, 5], "tr": "Inteligência 5", "ini": "9k5", "atq": [["Garras", "8k4", "S", "7k3"], ["Línguas Flamejantes", "8k4", "L", "2k2"]], "tn": 40, "red": 10, "fer": [[25, 5], [50, 10], [75, 15], [100, null]], "per": "Batalha (Batalha Massiva) 4, Tentação 4", "hab": [["Saliva Flamejante", "Quando a língua flamejante da Cria de Akuma no Oni toca a carne, ela deixa a saliva flamejante na ferida. Durante o Estágio de Reações de toda Rodada após a língua golpear, este oponente sofre 1k1 de dano de fogo. Isto dura por 10 rodadas ou até a saliva ser lavada. Água simples não lavará a ferida — ela requer vinagre ou álcool."], ["Medo 4", ""], ["Imenso", ""], ["Invulnerabilidade", ""], ["Múltiplas Línguas", "Crias de Akuma no Oni podem atacar com todas as três línguas na mesma Rodada, uma vez com cada língua. Esta é uma exceção especial à regra de que cada tipo de Ação Livre só pode ser feita uma vez por Rodada."]], "nota": "As crias de Akuma no Oni são raras mas geralmente mais poderosas que as crias de outros lordes onis. Akuma no Oni toma grande cuidado ao gerar suas crias e permite que elas adquiram poder nas Terras Sombrias antes de liberá-las para atormentar a humanidade."}, {"id": "idi_cria_de_kyoso_no_oni", "n": "Cria de Kyoso no Oni", "tipo": "oni", "fonte": "IdI p. 165", "an": [4, 4, 4, 4], "tr": "Reflexos 5, Força 5", "ini": "9k5", "atq": [["Garras", "5k4", "S", "4k3"], ["Fogo Negro", "9k5", "L", "3k2"]], "tn": 35, "red": 10, "fer": [[16, 5], [32, 10], [48, 15], [72, null]], "per": "", "hab": [["Fogo Negro", "A cria de Kyoso no Oni pode disparar raios de fogo negro contra qualquer oponente dentro de 15 m. Estas rajadas de poder destruidor de almas ignoram efeitos de armadura com o NA de Armadura do alvo. Elas também ignoram Redução. Sempre que um opo- itad nente é atingido por fogo negro, ele deve fazer um teste de Vazio contra NA 15 ou perder um Ponto de Vazio. Se o raio tirar seu último Ponto de Vazi"], ["Medo 3", ""], ["Alimentar-se da Alma", "Se uma cria de Kyoso no Oni matar um oponente, ela devora uma pequena porção da alma da vítima. Isto revigora a oni, fazendo-a curar instantaneamente Ferimentos iguais a 5 x o nível de Sabedoria do inimigo que ela matou."], ["Invulnerabilidade", ""], ["Talento Mágico", "Uma cria de Kyoso no Oni pode conjurar feitiços de Fogo e Terra como se fosse um shugenja de Nível 3 sem Afinidade ou Deficiência. Ela parece saber estes feitiços instintivamente e não precisa de pergaminhos, simplesmente conjurando qualquer feitiço que ela considere útil. Ela não pode conjurar feitiços com a palavra-chave Jade."], ["Múltiplos Braços", "A cria de Kyoso no Oni pode disparar seu fogo negro até quatro vezes na mesma Rodada (uma vez para cada garra). Esta é uma exceção à restrição normal de que cada Ação Livre só pode ser usada uma vez por Rodada. Ela não pode fazer ataques de Garras com uma mão que tenha disparado fogo negro na mesma Rodada."]], "nota": "Kyoso no Oni sempre foi bastante independente e suas crias não são diferentes, aventurando-se para cumprir seus próprios objetivos separadas de sua criadora. Crias de Kyoso no Oni são, como sua progenitora, as mais “humanas” das crias de lordes onis, podendo perder tempo conversando com suas vítimas"}, {"id": "idi_cria_de_shikibu_no_oni", "n": "Cria de Shikibu no Oni", "tipo": "oni", "fonte": "IdI p. 165", "an": [4, 3, 4, 3], "tr": "", "ini": "7k4", "atq": [["Garras", "6k4", "S", "5k2"]], "tn": 25, "red": 5, "fer": [[12, 5], [24, 10], [36, 15], [48, null]], "per": "Atuação 5, Sinceridade (Ardil) 5", "hab": [["Habitar Cadáver", "Quando uma cria de Shikibu no Oni é morta seu espírito se separa de seu corpo e pode habitar um cadáver humano próximo, retornando à vida. Se houver um cadáver preparado a 15 m do lugar onde ela morreu, ela habitará esse corpo durante o Estágio de Reações da Rodada após sua morte. Se não houver cadáveres preparados ao alcance, ela habitará qualquer outro cadáver humano ao alcance, mas demorará trê"], ["Medo 2", ""], ["Preservar Cadáver", "Shikibu no Oni normalmente preservará cadáveres para posterior habitação. Isto requer 166 que eles passem uma hora imbuindo uma pequena quantia de sua própria essência no corpo. Isto preserva o cadáver por um mês e também facilita para que o Onis Shikibu no Oni habite depois."], ["Veloz 2", ""]], "nota": "Shikibu no Oni é o menos fisicamente imponente dos lordes onis e suas crias mantêm essa tendência. Em sua forma natural, eles lembram pequenos anões mal-formados com bocas cheias de dentes afiados."}, {"id": "idi_cria_de_tsuburo_no_oni", "n": "Cria de Tsuburo no Oni", "tipo": "oni", "fonte": "IdI p. 166", "an": [1, 1, 3, 1], "tr": "Vigor 7, Força 7", "ini": "4k1", "atq": [["Agarrar", "8k3", "S", "7k2"]], "tn": 15, "red": 15, "fer": [[40, 5], [80, 10], [120, 15], [160, null]], "per": "", "hab": [["Medo 5", ""], ["Imenso", ""], ["Invulnerabilidade", ""], ["Devorar", "Se uma cria de Tsuburu no Oni conseguir usar com sucesso seu ataque Agarrar, ela pode escolher segurar sua presa. Isto é considerado uma Imobilização e o oni é considerado tendo 5 níveis de Jiujutsu para fins de manter a Imobilização. Se a cria de Tsuburu no Oni mantiver o controle da Imobilização no começo de seu Turno, ele pode, como Ação Livre, jogar a vítima Imobilizada por sua garganta. Os qu"], ["Teleporte", "Crias de Tsuburu no Oni podem, como Ação Simples, se teleportarem para qualquer lugar que possam ver. Isto conta como movimento para sua distância máxima de movimento para a Rodada."]], "nota": "Crias de Tsuburo no Oni sempre têm fome e devoram tudo em que puderem pôr as mãos. Eles são criados a partir de inchaços que brotam do corpo imenso do lorde oni e caem no chão totalmente formados."}, {"id": "idi_ryokaku_no_oni", "n": "Ryokaku no Oni", "tipo": "oni", "fonte": "IdI p. 167", "an": [4, 4, 4, 4], "tr": "", "ini": "8k4", "atq": [["Garras", "7k4", "S", "4k2"], ["Katana", "9k4", "S", "—"]], "tn": 25, "red": 8, "fer": [[16, 5], [32, 1], [72, null]], "per": "Corte 3, Etiqueta 3, Iaijutsu (Avaliação, Foco) 4, Kenjutsu (Katana) 5, Sinceridade 5, Tentação (Sedução) 5", "hab": [["Preso ao Duelo", "Se um Ryokaku no Oni for desafiado para um duelo de iaijutsu, ele sempre aceitará. Ele duelará honradamente e não permitirá que qualquer lacaio interrompa. Para fins de duelos, o Ryokaku no Oni é considerado tendo Vazio igual ao seu Nível de Mácula (embora ainda não tenha Pontos de Vazio). Ele também é considerado tendo Nível de Sabedoria 4 durante um duelo. O Ryokaku no Oni só duelará it até a mo"], ["Medo 3", ""], ["Beleza Insidiosa", "Ryokaku no Oni são muito belos e são considerados como se tivessem a Vantagem Beleza Perigosa."], ["Invulnerabilidade", ""], ["A Névoa Negra da Pureza", "Como Ação Complexa, Ryokaku no Oni podem transportar a si mesmos e a outra pessoa que toquem num nevoeiro negro que viaja tão rápido quanto o vento — sua velocidade mínima é como se tivesse Nível de Água 10, e pode se mover mais rápido se houver um vento forte ou tempestade disponíveis. Eles normalmente usam esta habilidade para roubar em Rokugan e raptar suas possíveis cônjuges. Na forma de névoa"]], "nota": "Ryokaku no Oni são problemáticos para samurais que os encontram porque negam as características físicas que se esperaria de um oni. Os Demônios da Pureza parecem ter um senso de honra e tradição que lembra de perto os dos samurais de Rokugan."}, {"id": "idi_cria_de_shokansuru", "n": "Cria de Shokansuru", "tipo": "oni", "fonte": "IdI p. 168", "an": [4, 4, 4, 4], "tr": "Agilidade 5, Percepção 6", "ini": "8k4", "atq": [["Garras", "7k5", "S", "5k3"], ["Língua-Ferrão", "8k5", "C", "4k2"]], "tn": 30, "red": 8, "fer": [[24, 5], [48, 10], [72, 15], [96, null]], "per": "", "hab": [["Seda Demoníaca", "A Morte de Muitos Braços pode lançar Onis uma teia negra pela sua boca. Essa teia é mais forte que seda e muito pegajosa. Uma criatura que a toque instantaneamente fica Presa e deve fazer um Teste de Força contra NA 15 para se libertar. Para cada Teste de Força subsequente o NA aumenta em 5 conforme a vítima fica mais enrolada, até o máximo de NA 30. O Shikage no Oni normalmente usa esta teia para"], ["Medo 3", ""], ["Invulnerabilidade", ""], ["Veneno Incapacitante", "Se uma criatura for atingida pelo ferrão de Shikage no Oni, o oni pode injetar veneno paralisante ou incapacitante. Uma vítima inoculada com veneno incapacitante perde imediatamente 1 Nível de Vontade, e durante o Estágio de Reações da mesma Rodada a vítima deve fazer um Teste de Vigor contra NA 20 ou perder um nível adicional de Vontade. Isto continua durante cada Estágio de Reações até a vítima "], ["Veneno Paralisante", "Se uma criatura for atingida pelo ferrão de Shikage no Oni, o oni pode injetar veneno pa- ralisante ou incapacitante. Uma vítima inoculada com veneno paralisante perde imediatamente 1 Nível de Reflexos, e durante o Estágio de Reações da mesma Rodada, a vítima deve fazer um Teste de Vigor contra NA 20 ou perder um Nível adicional de Reflexos. Isto continua durante cada Estágio de Reações até a víti"], ["Constituição Venenosa", "Devido ao Shikage no Oni ter veneno correndo por suas veias, eles são imunes a efeitos de todos os venenos."], ["Escalar Paredes", "Shikage no Oni pode escalar qualquer"]], "nota": ""}, {"id": "idi_hasaiki_no_oni_o_mar_ardente", "n": "Hasaiki no Oni, o Mar Ardente", "tipo": "oni", "fonte": "IdI p. 169", "an": [3, 6, 2, 3], "tr": "Agilidade 3, Força 6", "ini": "3k3", "atq": [["Mordida", "7k7", "C", "6k6"], ["Pisada", "7k3", "S", "—"], ["Vômito", "3k3", "C", "—"]], "tn": 20, "red": 5, "fer": [[32, 5], [48, 10], [64, 15], [200, null]], "per": "", "hab": [["Medo 3", ""], ["Imenso", ""], ["Invulnerável", ""], ["Salto", "Como Ação de Movimento Complexa, Hasaiki no Oni pode dar um salto imenso, sobre obstáculos de até 7 m de altura, e chegando a uma distância de até Anel de Água x 9 m."], ["Regeneração", "Hasaiki no Oni cura 5 Ferimentos durante o Estágio de Reações de cada Rodada, até ser morto. Mais de um grupo de samurais abateu o demônio até Inconsciente, apenas para dá-lo como morto, deixar que se curasse e retornasse a infestar o Império de novo."], ["Vômito", "Hasaiko no Oni pode vomitar um imenso jorro de ácido extremamente volátil. Este ataque tem um alcance máximo de 15 m e ignora os efeitos de armadura no NA de Armadura do alvo. O ácido causa 4k4 Ferimentos por Rodada e persiste por cinco Rodadas ou até o ácido ser lavado com amplo suprimento de água. O ácido não destruirá aço dobrado, mas placas de metal podem ser erodidas ao ponto da inutilidade a"]], "nota": ""}, {"id": "idi_munemitsu_no_oni_o_rompe_terra", "n": "Munemitsu no Oni, o Rompe-terra", "tipo": "oni", "fonte": "IdI p. 169", "an": [2, 7, 1, 5], "tr": "Reflexos 4, Agilidade 4, Força 8", "ini": "4k2", "atq": [["Chifrada", "6k4", "C", "8k6"], ["Pisada", "4k4", "S", "—"]], "tn": 25, "red": 6, "fer": [[32, 3], [64, 5], [96, 10], [128, 15], [160, 20], [224, null]], "per": "", "hab": [["Medo 3", ""], ["Chifrada", "Munemitsu no Oni pode chifrar um oponente. Oponentes atingidos por um ataque de chifres ficam presos neles e incapazes de se moverem a menos que se libertem com um Teste de Força contra NA 20 — isto causa mais 3k2 de dano adicional à medida que se libertam dos chifres. Munemitsu pode prender até três oponentes desta maneira."], ["Imenso", ""], ["Invulnerável", ""], ["Pisada", "Oponentes atingidos pela Pisada de Munemitsu são deixados Prostrados. Onis"]], "nota": ""}, {"id": "idi_sentei_no_oni_a_morte_de_muitas_pernas", "n": "Sentei no Oni, a Morte de Muitas Pernas", "tipo": "oni", "fonte": "IdI p. 169", "an": [2, 6, 4, 4], "tr": "Reflexos 4", "ini": "6k4", "atq": [["Mordida", "6k4", "C", "5k5"], ["Presas", "4k4", "S", "—"]], "tn": 25, "red": 5, "fer": [[30, 5], [60, 10], [120, 15], [240, null]], "per": "", "hab": [["Medo 4", ""], ["Imenso", ""], ["Invulnerável", ""], ["Regeneração Superior", "A maior arma de Sentei no Oni é seu incrível poder de regeneração. Muitas vezes a criatura já foi tida como destruída, mas em todo caso ela regenerou seu corpo a partir dos restos que não foram destruídos, em alguns casos, pedaços incrivelmente pequenos que caberiam numa mão. O oni recupera 30 Ferimentos por hora. Se o oni for morto, a regeneração não começa durante um dia, e então retorna ao ritm"]], "nota": ""}, {"id": "idi_yojireju_no_oni_o_devorador_de_almas", "n": "Yojireju no Oni, o Devorador de Almas", "tipo": "oni", "fonte": "IdI p. 170", "an": [3, 3, 3, 3], "tr": "Reflexos 5, Agilidade 4", "ini": "4k3", "atq": [["Garras", "6k5", "S", "5k3"]], "tn": 30, "red": 5, "fer": [[20, 3], [40, 5], [60, 10], [80, 15], [100, null]], "per": "", "hab": [["Absorver Cadáver", "Yojireju pode absorver a energia e material dos recentemente mortos, aumentando seu poder. A besta pode usar duas Ações Complexas para absorver completamente qualquer cadáver que tenha morrido há menos de uma hora. Quando isto é feito, o oni ganha um bônus em um Anel igual ao Nível de Sabedoria do indivíduo morto (animais e criaturas que não possuem Níveis de Sabedoria são considerados Nível 1). E"], ["Medo 3", ""], ["Invulnerável", ""], ["Absorção de Alma", "Assim como o demônio consome carne, ele também pode consumir almas. Quando o oni mata um oponente humano, os dois devem fazer um Teste Disputado de Nível de Sabedoria/Vontade. Se o demônio vencer, a alma é consumida e o indivíduo não vai para o reino espiritual devido. Yojireju no Oni permanentemente ganha um Nível em cada um de seus 170 Anéis cada vez que devora uma alma. Onis"]], "nota": ""}, {"id": "idi_sodatsu_no_oni_ruina_dos_shugenjas", "n": "Sodatsu no Oni, Ruína dos Shugenjas", "tipo": "oni", "fonte": "IdI p. 170", "an": [4, 6, 4, 4], "tr": "Reflexos 5, Força 6", "ini": "8k4", "atq": [["Pseudópodos", "8k4", "S", "6k4"]], "tn": 25, "red": 15, "fer": [[40, 5], [80, 10], [120, null]], "per": "", "hab": [["Medo 5", ""], ["Imenso", ""], ["Maleável", "Por ser composto de protoplasma, um Sodatsu no Oni pode se espremer por quase qualquer abertura em que água possa fluir."], ["Ruína do Shugenja", "Quando um feitiço é conjurado contra Sodatsu no Oni, ele absorve a magia elemental, fazendo com que o feitiço não tenha efeito nele. O oni deve instantaneamente fazer uma Ação Livre para usar a energia dos kamis de uma das três maneiras. Ele pode disparar um raio de energia mágica Maculada num inimigo a até 15 m; a rolagem do ataque é 4k4 e o ND do raio é igual ao Nível de Domínio do feitiço absor"]], "nota": "Sodatsu no Oni são terríveis massas de protoplasma negro e gosmento que parecem ter olhos e bocas se movendo e rodando consigo, flutuando na superfície em lugares aleatórios de vez em quando. Eles podem chegar a sete metros, mas há lendas de Sodatsu no Oni muito maiores."}, {"id": "idi_tasu_no_oni_praga_da_carne", "n": "Tasu no Oni, Praga da Carne", "tipo": "oni", "fonte": "IdI p. 171", "an": [1, 3, 1, 3], "tr": "Reflexos 3, Agilidade 4", "ini": "3k3", "atq": [["Perna", "4k4", "S", "3k2"], ["Mandíbulas", "4k4", "C", "—"]], "tn": 25, "red": 5, "fer": [[20, 5], [40, 10], [60, null]], "per": "", "hab": [["Medo 3", ""], ["Cria", "Após sua morte, um Tasu no Oni imediatamente liberará 2k2 filhotes. Estas criaturas têm cerca de 30 cm de comprimento e poucos meios de autodefesa. Eles são considerados tendo todos os Anéis em 1, com NA de Armadura 15 e 12 Ferimentos. As criaturas instintivamente se espalharão, e só podem se mover com uma Ação de Movimento Complexa que os permite se moverem até 9 m. Eles têm Furtividade 7 e tenta"]], "nota": "Um tormento vivo nas Terras Sombrias, Tasu no Oni são criaturas implacavelmente agressivas que atacam qualquer inimigo vivo que encontrem, às vezes até mesmo outros onis ou criaturas das Terras Sombrias. Mesmo os Perdidos não estão imunes a essa agressão irracional."}, {"id": "idi_utogu_no_oni_a_fome_eterna", "n": "Utogu no Oni, a Fome Eterna", "tipo": "oni", "fonte": "IdI p. 171", "an": [2, 5, 1, 5], "tr": "Agilidade 4", "ini": "3k2", "atq": [["Mordida", "6k4", "C", "5k5"], ["Investida", "6k5", "C", "—"], ["Pisada", "4k4", "S", "—"]], "tn": 20, "red": 8, "fer": [[60, 5], [90, 10], [120, null]], "per": "", "hab": [["Investida", "Apesar de seu chifre não ser particularmente afiado, um Utogu tem um ataque de investida que é bastante eficaz para enfraquecer ou aleijar a presa para consumo. Se o oni está na Postura Ataque Total, ele pode se mover até seu Anel de Água x 3 m e então fazer um ataque de Investida."], ["Devorar", "Embora prefira consumir coisas já mortas, ocasionalmente a fome do Utogu no Oni o levará a consumir carne ainda viva. Se o demônio infligir 30 ou mais Ferimentos com seu ataque Mordida, o oponente será agarrado pela mandíbula da besta. A vítima será considerada Presa. Em seu próximo Turno, o oni tentará engolir sua presa, fazendo um Teste Disputado de Força. Se a vítima tiver sucesso, ela consegue"], ["Medo 3", ""], ["Imenso", ""], ["Invulnerável", ""], ["Pisada", "Um ataque bem sucedido de Pisada de um Utogu no Oni deixará o oponente Prostrado. Se a rolagem de ataque exceder o NA de Armadura por 10 ou mais, o oponente também ficará Tonto. Onis UZAKI NO ONI, O COMANDANTE 171"]], "nota": "Os onis do Jigoku matam por vários motivos, mas Utogu no Oni mata pelo motivo mais básico de todos: saciar sua fome sem fim. Felizmente raras, estas imensas bestas queimam por dentro com uma fome que nunca pode ser totalmente satisfeita."}, {"id": "idi_oni_comandante", "n": "Oni Comandante", "tipo": "oni", "fonte": "IdI p. 172", "an": [5, 5, 5, 5], "tr": "Agilidade 6, Percepção 6", "ini": "9k5", "atq": [["Garras", "9k5", "C", "6k2"], ["Katana de Obsidiana", "10k5", "S", "—"]], "tn": 30, "red": 8, "fer": [[16, 5], [32, 10], [48, 15], [72, null]], "per": "Batalha (Combate em Massa, Luta) 5, Defesa 5, Iaijutsu 5, Jiujutsu 4, Kenjutsu (Katana de Obsidiana) 5. Conhecimento (Táticas Rokuganis) 5", "hab": [["Voz de Comandante", "Há muito tempo, os Uzaki no Oni fizeram uma barganha com os kansens do ar para ajudá-los em batalha. A voz de um Uzaki no Oni pode ser ouvida em qualquer lugar no campo de batalha que ele 172 quiser que seja ouvida."], ["Inimizade Eterna", "Uzaki no Oni nunca esquecem das táticas que o oponente usa. Se alguém consegue derroOnis tar o Uzaki no Oni no campo de batalha (numa luta ou numa batalha), o Uzaki no Oni aprenderá da derrota. Na próxima vez que o oni encontrar a pessoa que o derrotou, ele ganhará +1k1 em todos os testes contra esse oponente."], ["Medo 3", ""], ["Imenso", ""], ["Invulnerabilidade", ""], ["Líder de Onis", "Outras criaturas das Terras Sombrias recorrem ao Uzaki no Oni para liderança, como resultado, todo Uzaki no Oni tem a Vantagem Liderança."], ["Aprender com seus Inimigos", "Uzaki no Oni acumulam o máximo possível de informação sobre seus inimigos. Alguns Uzaki no Oni chegam a de fato saber uma ou duas Técnicas de Escolas de bushis rokuganis. Eles nunca saberão Técnicas acima do Nível Dois e não podem usar Técnicas que requeiram o gasto de Vazio."], ["Estrategista", "Uzaki no Oni são comandantes naturais e têm a Vantagem Estrategista."]], "nota": "Embora os lordes onis sejam governantes inquestionáveis dos onis, eles não são necessariamente bons comandantes em campo de batalha. Quando as criaturas das Terras Sombrias se unem para uma invasão ao Império, elas normalmente buscam o Uzaki no Oni para guiá-las em campo de batalha."}, {"id": "idi_wakeru_no_oni_a_horda_sem_fim", "n": "Wakeru no Oni, a Horda Sem Fim", "tipo": "oni", "fonte": "IdI p. 172", "an": [2, 5, 2, 2], "tr": "Reflexos 5, Agilidade 5, Força 5", "ini": "8k5", "atq": [["Garras", "6k5", "S", "6k2"]], "tn": 20, "red": 5, "fer": [[50, null]], "per": "", "hab": [["Horda Sem Fim", "Quando Wakeru no Oni sofre dano suficiente para matá-lo, ele não morre. Ao invés disso, ele se divide em duas versões menores de si mesmo. Elas agem no próximo turno do oni. Os Wakeru no Oni menores reduzem todos os seus Atributos físicos em um Nível, e seus Ferimentos decrescem em 5, mas seu NA de Armadura aumenta em 5 para refletir seu tamanho menor. Ele mantém a jogada de Iniciativa e suas joga"], ["Medo 2", ""], ["Fúria Ilimitada", "Quando ameaçado, o Wakeru no Oni luta de forma inconsequente, não se preocupando com defesa, já que a destruição só o torna mais poderoso. Um Wakeru no Oni sempre usa Ataque Total em combate."]], "nota": "Wakeru no Oni não são particularmente imponentes ou ameaçadores. Eles são da altura de samurais medianos."}, {"id": "idi_wanizame_no_oni_a_fome_aquatica", "n": "Wanizame no Oni, a Fome Aquática", "tipo": "oni", "fonte": "IdI p. 173", "an": [2, 2, 1, 4], "tr": "Reflexos 4, Agilidade 4", "ini": "4k4", "atq": [["Mordida", "6k4", "C", "4k4"]], "tn": 25, "red": 3, "fer": [[15, 5], [30, 10], [45, 15], [60, null]], "per": "", "hab": [["Aquático", "Wanizame no Oni é uma criatura aquática e não pode sair da água. Ele não sofre penalidades de movimento pela água e não precisa de rolagens de Esportes para nadar."], ["Farejar Sangue", "Wanizame no Oni pode farejar sangue na água a incríveis distâncias. Se qualquer sangue for derramado na água dentro de 8 km, ele pode fazer um Teste de Percepção contra NA 30 menos o número total de Ferimentos sofrido pela criatura sangrando. Se tiver sucesso, o oni descobre a localização exata da criatura sangrando."], ["Medo 2", ""], ["Fúria Voraz", "Se um alvo dentro de 8 km da localização no oni perder mais do que um Nível de Ferimentos, Wanizame no Oni ganha um bônus de +2k2 em jogadas de ataque feitas contra esse alvo."]], "nota": "Os misteriosos superpredadores conhecidos como Wanizame no Oni são um enigma mesmo para os mais esforçados estudiosos Kuni, devido principalmente à sua natureza aquática. Observá-los em seu ambiente natural, o Mar das Sombras, é praticamente impossível, portanto a única informação que o Caranguejo p"}, {"id": "idi_yuhmi_no_oni_carne_do_lorde_negro", "n": "Yuhmi no Oni, Carne do Lorde Negro", "tipo": "oni", "fonte": "IdI p. 173", "an": [2, 4, 2, 3], "tr": "Reflexos 4, Agilidade 4, Força 6", "ini": "4k3", "atq": [["Garras", "6k4", "S", "6k2"]], "tn": 25, "red": 5, "fer": [[40, 5], [80, 10], [120, 15], [160, null]], "per": "Esportes 2, Jiujutsu 2, Lanças 4", "hab": [["Medo 4", ""], ["Imenso", ""], ["Invulnerável", ""], ["Mai Chong", "Por razões desconhecidas a todos exceto o próprio demônio e talvez seu criador, Yuhmi no Oni empunha uma mai chong, uma lança especializada criada e utilizada pelo há muito extinto Clã Javali. Apesar de geralmente preferir o combate corporal, a besta pode atirar a mai chong com a mesma jogada de ataque listada para seu ataque corporal."], ["Cria Singular", "Yuhmi no Oni pode criar apenas uma cria, um oni menor que parece humano em todos os aspectos, exceto pelas placas reforçadas que cobrem sua face; felizmente, elas lembram uma mempo, o que previne detecção. A cria é o equivalente a um humano de Nível de Sabedoria 4, e possui Nível de Escola 4 numa Escola Básica do Clã Aranha ou Perdido. A cria pode agir completamente independente do oni, apesar do "]], "nota": "Durante um ataque falho à Cidade Imperial, Daigotsu, o akutenshi conhecido como o Lorde Negro das Terras Sombrias, perdeu um braço em combate com a herdeira Imperial Toturi Tsudao. Apesar de Daigotsu ter sobrevivido para lutar outro dia, seu braço foi perdido e ele não teve escolha senão substituí-l"}, {"id": "idi_espadachim_kenku", "n": "Espadachim Kenku", "tipo": "povo", "fonte": "IdI p. 179", "an": [4, 3, 3, 3, 4], "tr": "Agilidade 4, Força 4", "ini": "7k4", "atq": [["Katana   179", "10k4", "S", "7k2"]], "tn": 30, "red": 3, "fer": "h", "per": "Atuação 3, Kenjutsu (Katana) 6, Conhecimento: História 2, Meditação 4, Defesa 3, Furtividade 3, Cerimônia do Chá 3", "hab": [["Ilusão", "Uma vez por dia, um Kenku pode assumir forma humana ou se tornar invisível como Ação Simples. Esta ilusão persiste até o Kenku escolher descartá-la. Invisibilidade também cessará se o Kenku atacar."], ["Asas", "Kenkus em sua forma natural podem voar, e se mover ao dobro de sua velocidade normal ao fazê-lo."]], "nota": ""}, {"id": "idi_kenku_kensei", "n": "Kenku Kensei", "tipo": "povo", "fonte": "IdI p. 179", "an": [5, 4, 5, 3, 5], "tr": "Força 5", "ini": "10k5", "atq": [["Katana", "10k7", "S", "8k2"]], "tn": 35, "red": 3, "fer": "h", "per": "Atuação 4, Kenjutsu (Katana) 9, Conhecimento: História 4, Meditação 4, Defesa 5, Furtividade 4, Cerimônia do Chá 3", "hab": [["Ilusão", "Uma vez por dia, um Kenku pode tomar forma humana ou ficar invisível como Ação Simples. Esta ilusão persiste até o Kenku escolher descartá-la. Invisibilidade também cessará se o Kenku atacar."], ["Magia", "Um Kensei Kenku pode invocar Sentir, Comunicar e Invocar como se fosse um Shugenja de mesmo 180 Nível de Escola. Ele não precisa de manuscritos para invocar estes feitiços. As Cinco Raças Antigas"], ["Asas", "Kenkus em sua forma natural podem voar, e se mover ao dobro de sua velocidade normal ao fazê-lo."], ["Os reclusos kensei, ou “santos da espada” são mestres das ar", ""]], "nota": ""}, {"id": "idi_cacador_de_perolas_ningyo", "n": "Caçador de Pérolas Ningyo", "tipo": "povo", "fonte": "IdI p. 183", "an": [4, 3, 4, 3], "tr": "", "ini": "7k4", "atq": [["Yari", "8k4", "S", "5k2"]], "tn": 20, "red": 2, "fer": "h", "per": "Trato Animal 2, Defesa 3, Caça 2, Investigação 3, Jiujutsu 3, Lanças 4, Furtividade 4", "hab": [["Aquático", "Ningyos se movem em velocidade normal debaixo d’água e podem nadar sem necessidade para um Teste de Perícia Esportes. Eles não podem respirar ar, mas podem sobreviver fora da água por até uma hora. Fora da água eles se movem como se possuíssem Anel de Água 1."], ["Fala Ningyo", "Enquanto estiverem debaixo d’água, Ningyos podem se comunicar entre si em frequências indetectáveis por humanos. Os Trolls Trolls modernos, descritos no capítulo Bestas das Terras Sombrias em outro ponto deste livro, são humanoides grandes, cobertos de camadas de músculos inchados e couro verde espesso. Seus olhos são pretos e opacos, quase não mostrando inteligência alguma, e eles vivem em feroze"]], "nota": "O típico Caçador de Pérolas é um membro mais civilizado da raça Ningyo, normalmente por serem parte de uma civilização Ningyo maior bem nas profundezas. Estas criaturas são agitadas e reclusas, mas se defendem se ameaçadas."}, {"id": "idi_kitsu", "n": "Kitsu", "tipo": "povo", "fonte": "IdI p. 185", "an": [3, 3, 4, 5, 5], "tr": "", "ini": "6k3", "atq": [["Garras", "6k4", "S", "5k3"]], "tn": 25, "red": 5, "fer": [[18, 5], [36, 10], [54, 15], [72, null]], "per": "Esportes 3, Caça 5, Conhecimento: Reinos Espirituais 6, Meditação 5 185", "hab": [["Cruzar os Reinos", "Kitsus podem sentir e entrar em qualquer portal espiritual, cruzando facilmente entre os diferentes Reinos Espirituais. Eles também podem se comunicar com qualquer criatura com a qualidade Espírito, independente da língua."], ["Metamorfose", "Kitsus podem assumir qualquer forma felina ou humanoide (ou de tamanho e peso aproximados) como Ação Simples. Sua forma “normal” mais típica é um grande felino predador como um leão. Em todas as suas formas eles têm olhos dourados brilhantes. Acredita-se que eles possam assumir outras formas também, embora qualquer informação concreta sobre isso tenha sido perdida há muito tempo."], ["Espírito", ""], ["Uso de Vazio", "Os Kitsus são uma raça profundamente associada ao Vazio, e como resultado, eles estão entre as poucas criaturas capazes de usar um Anel de Vazio e de usar Pontos de Vazio da mesma maneira que humanos."]], "nota": "Os Kitsus estão extintos da Rokugan moderna, mas campanhas ambientadas na aurora do Império podem apresentar encontros com eles, e ao menos um Tsuno já foi transformado de volta em um Kitsu (vide “Tsuno Nintai”, ainda neste capítulo). Campanhas envolvendo jornadas pelos reinos espiri- itad tuais, ou"}, {"id": "idi_devastador_tsuno_nivel_3", "n": "Devastador tsuno (Nível 3)", "tipo": "povo", "fonte": "IdI p. 192", "an": [3, 5, 3, 3], "tr": "Reflexos 5, Agilidade 4, Força 4", "ini": "8k5", "atq": [["Lâmina Tsuno", "10k4", "S", "7k3"], ["desarmado", "8k4", "S", "—"]], "tn": 35, "red": 8, "fer": "h", "per": "Esportes 4, Batalha 3, Defesa 5, Armas Pesadas (Lâmina Tsuno) 6, Intimidação (Tortura) 4, Jiujutsu 4, Conhecimento: Terras Sombrias 3, Conhecimento: Reinos Espirituais 5, Furtividade 3", "hab": [["Medo 2", ""], ["Arma Especial (Lâmina Tsuno)", "As cruéis espadas dentadas dos Tsunos são armas 3k3 e ganham um bônus de ataque de +1k0 contra qualquer oponente que tenha ao menos um Nível de Mácula, a qualidade Espírito, ou que tenha a Vantagem Tocado pelos Reinos."], ["Espírito", ""], ["Veloz 3 EXEMPLO DE VILÃO", "DOBRADOR DE ALMAS"]], "nota": "c Reino/Anel: Sakkaku/Fogo c Alcance: 30 m c Duração: Nível de Escola do conjurador em semanas c Incrementos: Especial (4 Incrementos para um Nível adicional de Azar) Os espíritos do Sakkaku adoram travessuras, e um Dobrador de Almas que tenha dominado seus poderes pode fazê-los perturbar seus inimi"}, {"id": "idi_dobrador_de_almas_maculado_nivel_3", "n": "Dobrador de almas maculado (Nível 3)", "tipo": "povo", "fonte": "IdI p. 193", "an": [4, 4, 4, 4], "tr": "Reflexos 5, Inteligência 5", "ini": "8k5", "atq": [["Lâmina Tsuno", "9k4", "C", "7k3"], ["desarmado", "7k4", "C", "—"]], "tn": 35, "red": 8, "fer": "h", "per": "Esportes 3, Batalha 5, Defesa 4, Armas Pesadas (Lâmina Tsuno) 5, Intimidação (Provocação, Tortura) 5, Jiujutsu 3, Conhecimento: Terras Sombrias 6, Conhecimento: Reinos Espirituais 7, Meditação 5, Furt", "hab": [["Medo 2", ""], ["Arma Especial (Lâmina Tsuno)", "As cruéis espadas dentadas dos Tsunos são armas 3k3 e ganham um bônus de ataque de +1k0 contra qualquer oponente que tenha ao menos um Nível de Mácula, a qualidade Espírito, ou que tenha a Vantagem Tocado pelos Reinos."], ["Espírito", ""], ["Veloz 3 Os Zokujins “Dura como pedra é sua pele, e seus olho", ""]], "nota": ""}, {"id": "idi_zokujin_minerador", "n": "Zokujin Minerador", "tipo": "povo", "fonte": "IdI p. 194", "an": [3, 3, 2, 4], "tr": "Reflexos 4, Agilidade 3", "ini": "5k4", "atq": [["Garras", "5k3", "C", "4k1"]], "tn": 25, "red": 10, "fer": [[18, 5], [36, 10], [64, null]], "per": "Esportes 3, Furtividade 3", "hab": [["Escavar", "Um Zokujin pode se mover à velocidade normal através de terra sólida ou pedra, sem deixar um túnel para trás. Um Zokujin que se mova a Água 2 pode deixar um túnel para trás que durará por um minuto antes de desmoronar. Um Zokujin que se mova a Água 1 pode deixar um túnel permanente para trás."], ["Moldar a Terra", "Um Zokujin pode moldar terra ou pedra com as mãos nuas como se fosse argila. Isto é refletido em várias outras habilidades. Qualquer porção de terra ou pedra moldada por um Zokujin automaticamente retornará ao seu estado anterior uma rodada após o Zokujin cessar o contato, a menos que o Zokujin conscientemente queira que ela permaneça nesta nova forma."], ["Resistência Mineral", "A Redução de um Zokujin funciona apenas contra armas feitas de pedra ou metal. Armas de madeira a ignoram."]], "nota": "Os parâmetros de um Zokujin Minerador descrevem um operário Zokujin de uma mina do Clã Leão. Parâmetros similares também descrevem um Zokujin que viva em uma de suas tribos."}, {"id": "idi_cacador_da_pedra_zokujin", "n": "Caçador da Pedra Zokujin", "tipo": "povo", "fonte": "IdI p. 195", "an": [4, 4, 4, 4], "tr": "Reflexos 5, Força 5", "ini": "8k5", "atq": [["Garras", "9k4", "S", "5k2"]], "tn": 30, "red": 20, "fer": [[24, 5], [48, 10], [72, null]], "per": "Esportes 4, Caça 4, Investigação 3, Furtividade 4", "hab": [["Quebrar Armadura", "Um Caçador da Pedra Zokujin pode tentar Moldar a Terra na armadura de um inimigo. Um Caçador da Pedra que faça dois Incrementos numa jogada de ataque pode destruir qualquer armadura usada pelo alvo além de causar dano. Artefatos ancestrais e outras armaduras despertas são resistentes a este poder."], ["Escavar", "Um Zokujin pode se mover à velocidade normal através de terra sólida ou pedra, sem deixar um túnel para trás. Um Zokujin que se mova a Água 2 pode deixar um túnel para trás que durará por um minuto antes de desmoronar. Um Zokujin que se mova a Água 1 pode deixar um túnel permanente para trás."], ["Moldar a Terra", "Um Zokujin pode moldar terra ou pedra com as mãos nuas como se fosse argila. Isto é refletido em várias outras habilidades. Qualquer porção de terra ou pedra moldada por um Zokujin automaticamente retornará ao seu estado anterior uma rodada após o Zokujin cessar o contato, a menos que o Zokujin conscientemente queira que ela permaneça nesta nova forma."], ["Resistência Mineral", "A Redução de um Zokujin funciona apenas contra armas feitas de pedra ou metal. Armas de madeira a ignoram."], ["Quebrar Arma", "Um Caçador da Pedra Zokujin pode tentar usar Moldar a Terra na arma de um inimigo para autodefesa. Se uma arma feita de metal ou pedra for usada para atacar o Zokujin, e errar o NA de Armadura por 10 ou mais, a arma se torna cega, torta e inútil. Muito semelhante à habilidade Quebrar Armadura, este poder não afetará armas que sejam magicamente despertas. ita"]], "nota": "Os mais fortes e capazes Zokujin são escolhidos para procurar a Pedra Sangue Branco. Estes guerreiros podem ser surpreendentemente capazes, e embora prefiram evitar conflito quando puderem, um samurai que ataque um deles pode ter uma surpresa desagradável."}, {"id": "idi_xama_zokujin", "n": "Xamã Zokujin", "tipo": "povo", "fonte": "IdI p. 195", "an": [4, 5, 4, 4], "tr": "Reflexos 5, Inteligência 5, Força 5", "ini": "9k5", "atq": [["Garras", "7k4", "S", "5k2"]], "tn": 30, "red": 20, "fer": [[32, 5], [64, 10], [80, null]], "per": "Esportes 4, Caça 4, Investigação 3, Conhecimento: Terra 5, Furtividade 4 Feitiços: Xamãs Zokujins podem invocar qualquer feitiço de Terra (incluindo Sentir, Comunicar e Invocar para o elemento Terra) ", "hab": [["Quebrar Armadura", "Um Xamã Zokujin pode tentar Moldar a Terra na armadura de um inimigo. Um Xamã que faça dois Incrementos numa jogada de ataque pode destruir qualquer armadura usada pelo alvo além de causar dano. Artefatos ancestrais e outras armaduras despertas são resistentes a este poder."], ["Escavar", "Um Zokujin pode se mover à velocidade normal através de terra sólida ou pedra, sem deixar um túnel para trás. Um Zokujin que se mova a Água 2 pode deixar um túnel para trás que durará por um minuto antes de desmoronar. Um Zokujin que se mova a Água 1 pode deixar um túnel permanente para trás."], ["Moldar a Terra", "Um Zokujin pode moldar terra ou pedra com as mãos nuas como se fosse argila. Isto é refletido em várias outras habilidades. Qualquer porção de terra ou pedra moldada por um Zokujin automaticamente retornará ao seu estado anterior uma rodada após o Zokujin cessar o contato, a menos que o Zokujin conscientemente queira que ela permaneça nesta nova forma."], ["Resistência Mineral", "A Redução de um Zokujin funciona apenas contra armas feitas de pedra ou metal. Armas de madeira a ignoram."], ["Quebrar Arma", "Um Xamã Zokujin pode tentar Moldar a Terra na arma de um inimigo para autodefesa. Se uma arma feita de metal ou pedra for usada para atacar o Zokujin, e errar o NA de Armadura por 10 ou mais, a arma se torna cega, torta e inútil. Muito semelhante à habilidade Quebrar Armadura, este poder não afetará armas que sejam magicamente despertas. doaThadeuHudsonEm"]], "nota": "Comunidades Zokujins são lideradas por xamãs, indivíduos sábios e mágicos cujo conselho é universalmente obedecido. Seus poderes mágicos são um pouco similares aos dos Shugenjas humanos, mas eles invocam feitiços instintivamente, sem necessidade de pergaminhos ou preces."}, {"id": "idi_aka_name", "n": "Aka-name", "tipo": "sombrio", "fonte": "IdI p. 217", "an": [1, 2, 1, 3], "tr": "Reflexos 3, Agilidade 3", "ini": "4k3", "atq": [["Garras", "5k3", "C", "5k2"]], "tn": 20, "red": 5, "fer": [[16, 5], [32, null]], "per": "Esportes 3, Caça 3, Furtividade 3 Nível de Mácula: 3", "hab": [["Garras Venenosas", "As garras do Aka-name carregam um doloroso veneno que infecta feridas e as faz ficarem inflamadas e agonizantemente dolorosas. Qualquer criatura viva normal ferida por um Aka-name deve fazer um teste de Vigor contra NA 20 ou sofrer um adicional de 2k1 Ferimentos. Além disso, independente dos resultados da rolagem de Vigor, se a ferida não for prontamente lavada e então purificada com jade, ela rap"], ["Veloz 1 itad", ""]], "nota": "“Eles não se importam com a guerra ou qualquer outro propósito. Eles só querem se alimentar.” – KUNI DAIGO, CAMPEÃO DE JADE, SÉCULO XII Uma das criaturas mais repulsivas e odiadas das Terras Sombrias, o Aka-name é notável por sua aparência excepcionalmente horrenda."}, {"id": "idi_cria_de_dokufu", "n": "Cria de Dokufu", "tipo": "sombrio", "fonte": "IdI p. 218", "an": [1, 2, 1, 2], "tr": "Reflexos 2, Agilidade 3", "ini": "3k2", "atq": [["Garras", "4k3", "C", "3k2"]], "tn": 15, "red": 5, "fer": [[10, 5], [20, null]], "per": "", "hab": [["Veloz 1", ""]], "nota": ""}, {"id": "idi_garegosu_no_bakemono", "n": "Garegosu no Bakemono", "tipo": "sombrio", "fonte": "IdI p. 218", "an": [1, 6, 2, 3], "tr": "Reflexos 2, Agilidade 4, Força 5", "ini": "4k2", "atq": [["Tentáculos", "8k4", "S", "5k1"], ["Mordida", "5k4", "C", "—"]], "tn": 20, "red": 10, "fer": [[36, 5], [48, 10], [72, null]], "per": "Jiujutsu 4", "hab": [], "nota": "A prova viva da falta de racionalidade das Terras Sombrias, o Garegosu no Bakemono se parece com um polvo gigante terrestre. Seu tamanho e massa não têm limite."}, {"id": "idi_berserker_goblin", "n": "Berserker Goblin", "tipo": "goblin", "fonte": "IdI p. 221", "an": [1, 2, 1, 2], "tr": "Reflexos 3, Agilidade 3", "ini": "4k3", "atq": [["pau pontiagudo", "4k3", "S", "—"], ["Mordida", "4k3", "C", "—"]], "tn": 20, "red": 3, "fer": [[10, 5], [20, null]], "per": "", "hab": [["Fúria Berserker", "Nas primeiras duas Rodadas de uma luta, o frenesi de um goblin berserker o torna mais difícil de ser atingido e ele sente pouca ou nenhuma dor. Ele soma +1k1 às suas jogadas de ataque e aumenta sua Redução em 5 (até o total de 8). Esses efeitos terminam no Estágio de Reações da segunda Rodada."], ["Veloz 2 itad", ""]], "nota": "“Não temos medo de samurai! Não temos medo de samurai!"}, {"id": "idi_atirador_goblin", "n": "Atirador Goblin", "tipo": "goblin", "fonte": "IdI p. 221", "an": [1, 2, 1, 1], "tr": "Reflexos 4, Agilidade 2, Força 2", "ini": "5k4", "atq": [["Objeto manuseável", "6k4", "S", "Objeto aleatório"], ["Atiradeira", "6k4", "C", "—"], ["Arco  , faca", "6k4", "C", "—"], ["pau pontiagudo", "3k2", "C", "—"]], "tn": 25, "red": 3, "fer": [[9, 5], [18, null]], "per": "Esportes (Arremesso) 2, Furtividade 2 Nível de Mácula: 3", "hab": [["Veloz 2 oaThadeuHudsonEm", ""]], "nota": "“Pequenos, imprecisos, mas numerosos. Um só atirador não é grande ameaça..."}, {"id": "idi_xama_goblin", "n": "Xamã Goblin", "tipo": "goblin", "fonte": "IdI p. 222", "an": [1, 2, 2, 1], "tr": "Percepção 2", "ini": "3k2", "atq": [["pau pontudo", "4k2", "S", "pau pon-"]], "tn": 15, "red": 4, "fer": [[9, 5], [18, null]], "per": "Criação (Lama Mágica) 3, Caça (Sobrevivência) 1, Intimidação (Provocação) 2, Conhecimento: Maho 2, Conhecimento: Terras Sombrias 4, Medicina (Goblin, Herbalismo) 2, Feitiçaria 2, Furtividade 2 Nível d", "hab": [["Invocador", "Um xamã goblin pode invocar feitiços de maho como se possuísse Nível de Sabedoria 1. Tipicamente só sabem feitiços de Níveis de Domínio 1 e 2, apesar de alguns raros xamãs conseguirem feitiços de Nível de Domínio 3."], ["Veloz 2", ""]], "nota": "Bakemonos imitam outras criaturas, por razões insondáveis e com resultados lamentáveis. Não surpreende, portanto, que alguns tentem copiar os rituais dos maho-tsukais."}, {"id": "idi_goblin_furtivo", "n": "Goblin Furtivo", "tipo": "goblin", "fonte": "IdI p. 223", "an": [1, 2, 2, 1], "tr": "Reflexos 3, Percepção 3", "ini": "4k3", "atq": [["pau pontudo", "4k2", "S", "pau pon-"]], "tn": 20, "red": 3, "fer": [[9, 5], [18, null]], "per": "Defesa 2, Sinceridade (Ardil) 2, Furtividade (Emboscada,Ocultação, Esgueirar) 4 Nível de Mácula: 3", "hab": [["Fingir Morte", "Um goblin furtivo pode fingir sua própria morte, cobrindo-se de sangue, caindo e ficando imóvel. Um PJ que deseje ver através deste ardil deve fazer um teste de Investigação (Notar) / Percepção contra o teste de Furtividade do goblin de 5k3."], ["Veloz 3 ita", ""]], "nota": "“A única coisa pior do que os que são só dentes, são os que não lutam.” – TORITAKA SENSAICHI Os goblins conhecidos como “furtivos” são tão astutos quanto os chefes guerreiros, mas não possuem o poder físico dos líderes goblins. Todos os goblins mentem tal como respiram, mas muitos não são espertos o"}, {"id": "idi_chefe_guerreiro_goblin", "n": "Chefe Guerreiro Goblin", "tipo": "goblin", "fonte": "IdI p. 223", "an": [2, 3, 2, 2], "tr": "Reflexos 3, Agilidade 3, Força 3", "ini": "6k3", "atq": [["Katana", "6k3", "S", "6k2"]], "tn": 25, "red": 7, "fer": [[15, 5], [30, 10], [45, null]], "per": "Esportes 2, Batalha 3, Defesa 3, Engenharia 2, Intimidação (Provocação) 3, Conhecimento: Terras Sombrias 3, Kenjutsu 3, Furtividade 3 223 Nível de Mácula: 4", "hab": [["Líder de Massas", "Como Ação Complexa, um chefe guerreiro pode tentar inspirar suas tropas a um fervor de violência. O chefe guerreiro faz um teste de Intimidação (Provocação) / Vontade contra NA 20. Se tiver sucesso, todos os goblins que o ouvirem (ao máximo de 10 goblins) ganham um bônus de +1k0 em todas as jogadas de dano e ataque. Se o chefe guerreiro superar o NA por 15 ou mais, o bônus é de +2k0. Os bônus dura"], ["Veloz 2 doaThadeuHudsonEm", ""]], "nota": "Antes do misterioso escultor de carne chamado Omoni ter criado seus goblins melhorados, houve isoladas ocorrências de bakemonos de força, intelecto e tamanho superiores, às vezes chegando a um metro e meio de altura. Os Kuni especulam que estas criaturas são o que Fu Leng originalmente pretendia qua"}, {"id": "idi_goblin_de_omoni", "n": "Goblin de Omoni", "tipo": "goblin", "fonte": "IdI p. 224", "an": [1, 3, 2, 1], "tr": "Reflexos 3, Agilidade 3, Força 4", "ini": "5k3", "atq": [["pau pontudo", "5k3", "S", "pau pon-"]], "tn": 20, "red": 4, "fer": [[15, 5], [30, null]], "per": "Esportes 2, Batalha 3, Defesa 3, Engenharia 2, Intimidação (Provocação) 3, Conhecimento: Terras Sombrias 3, Kenjutsu 3, Furtividade 3 Nível de Mácula: 4", "hab": [["Destemido", "Goblins de Omoni ganham bônus de +3k3 para resistir a efeitos de Medo."], ["Veloz 2", ""]], "nota": "“Erga-se de novo, ainda há sangue a ser derramado!” – OMONI, O ESCULTOR DE CARNE, SÉCULO XII A monstruosidade conhecida como Omoni apareceu nas Terras Sombrias durante o século XII, rapidamente unindo forças ao Lorde Negro Daigotsu. Em resposta às necessidades de seu senhor, Omoni — que possuía estr"}, {"id": "idi_hanemuri", "n": "Hanemuri", "tipo": "sombrio", "fonte": "IdI p. 224", "an": [1, 1, 1, 1], "tr": "Reflexos 4, Agilidade 4, Percepção 2", "ini": "4k4", "atq": [["Mordida", "4k4", "C", "2k1"]], "tn": 25, "red": 0, "fer": [[5, 10], [10, null]], "per": "", "hab": [["Ataque de Enxame", "Para cada 3 hanemuris atacando o mesmo alvo, cada um ganha um bônus de +1k0 em suas jogadas de ataque (portanto, 6 hanemuris atacando o mesmo inimigo ganhariam um total de +2k0 de bônus)."], ["Veloz 4 (apenas voando).", ""]], "nota": "Hanemuris são répteis voadores do tamanho de corvos. Eles têm corpos curvos e ossudos, com fina pele marrom, asas de couro e mandíbulas exageradas com milhares de dentes parecidos com pequenos pregos."}, {"id": "idi_kumo", "n": "Kumo", "tipo": "sombrio", "fonte": "IdI p. 225", "an": [3, 3, 3, 4], "tr": "Reflexos 4, Agilidade 4, Força 5", "ini": "6k4", "atq": [["Mordida", "7k4", "C", "6k2"]], "tn": 30, "red": 5, "fer": [[16, 5], [32, 10], [48, 15], [64, null]], "per": "Esportes 3, Furtividade 5", "hab": [["Camuflagem", "Kumos podem mudar sua coloração para igualar a de seus arredores, concedendo-lhes um bônus de +2k0 em seus testes de Furtividade."], ["Medo 2", ""], ["Veneno", "Um kumo pode cuspir veneno como Ação Complexa. Este ataque tem alcance de 5 m e faz uma jogada de 5k4 para acertar. O veneno funciona como o veneno de uma aranha normal (como descrito no Livro do Vazio ita do Livro Básico de L5A 4ª Edição), porém, ele funciona como se tivesse sido introduzido na corrente sanguínea do alvo."], ["Teia", "Um kumo pode atirar uma teia num oponente como Ação Complexa. Ela tem alcance de 6 m e uma rolagem de ataque de 6k4. Se tiver sucesso, a vítima está Presa, e pode tentar escapar como Ação Complexa com uma rolagem de NA 20."]], "nota": ""}, {"id": "idi_mamono", "n": "Mamono", "tipo": "sombrio", "fonte": "IdI p. 226", "an": [4, 3, 2, 3], "tr": "Agilidade 4, Força 4", "ini": "5k4", "atq": [["Garras", "5k4", "C", "4k4"]], "tn": 30, "red": 15, "fer": [[25, 5], [40, 10], [60, null]], "per": "Atuação 3, Caça 3, Sinceridade (Ardil) 2, Furtividade 3", "hab": [["Sensibilidade à Luz do Dia", "Durante o dia, um mamono não pode regenerar Ferimentos. Se sua pele for exposta à luz do sol direta, ele sofrerá 1k1 de Ferimentos por minuto. Mamonos em forma humana geralmente usam chapéus, guarda-sóis e outros métodos para se protegerem do sol."], ["Medo 3 (na forma real)", ""], ["Metamorfose inferior", "Um mamono pode assumir forma humana, mas demora quinze minutos para fazê-lo, e durante esse tempo ele só pode fazer Ações Livres. Ele só tem uma forma humana (que pode ser masculina ou feminina). Ele pode retornar à sua forma monstruosa como Ação Livre e o fará automaticamente se sofrer Ferimentos. 226"], ["Invisibilidade", "Um mamono pode ficar invisível como Ação Simples, envolvendo-se num manto de kansens Bestas das Terras Sombrias do Ar. Cessar a invisibilidade também é uma Ação Simples, mas ele se torna automaticamente visível se for reduzido a Morto. A invisibilidade também cessa após ele fazer um ataque. Enquanto invisível, ele ganha +30 para sua NA de Armadura e +2k2 em todos os testes de Furtividade."], ["Ressurreição", "Durante as horas noturnas, um mamono regenera 5 Ferimentos por Rodada, mesmo que tenha sido previamente reduzido a “morto”. Se for desmembrado e enterrado, ele não pode mais se regenerar."]], "nota": "M estres que desejem oferecer um pouco mais de variedade em sua descrição dos kumos podem escolher permitir que a raça conserve uma habilidade limitada de metamorfose. Nesta opção, um kumo pode assumir forma humana (ou voltar à sua forma de aranha) como Ação Simples."}, {"id": "idi_fudoshi_cipos_estranguladores", "n": "Fudoshi (Cipós Estranguladores)", "tipo": "sombrio", "fonte": "IdI p. 226", "an": [0, 0, 0, 1], "tr": "Reflexos 1, Agilidade 3, Força 2", "ini": "2k2", "atq": [["Tentáculo de Vinha", "3k3", "C", "Especial (ataque"]], "tn": 10, "red": 15, "fer": [[6, null]], "per": "", "hab": [["Prender", "O fudoshi ataca simultaneamente com todos os seus tentáculos (de 1 a 10, dependendo do tamanho do fudoshi), podendo agarrar qualquer alvo dentro de 3 m. Cada tentáculo ataca como se fosse uma criatura independente, prendendo-se à vítima após um ataque bem sucedido. Cada ataque bem sucedido impõe uma penalidade ao NA de Armadura do alvo de 5 e inflige uma penalidade de NA +5 para todas as ações fís"], ["Tentáculos Agarradores", "Os ataques de tentáculos do fudoshi ignoram os efeitos de armadura no NA de Armadura da vítima."]], "nota": "O fudoshi parece um cipó que se espalha pela terra, cobrindo desde alguns metros quadrados até várias centenas de metros. Assim que um ser vivo começa a caminhar sobre o fudoshi, os cipós reagem ao calor da vida e se movem para prender a vítima, apertando-a até a morte por asfixia."}, {"id": "idi_arvore_de_lava", "n": "Árvore de Lava", "tipo": "sombrio", "fonte": "IdI p. 227", "an": [0, 5, 0, 4], "tr": "Reflexos 1, Agilidade 3", "ini": "2k1", "atq": [["Tentáculo de Raiz", "5k3", "S", "4k2"]], "tn": 10, "red": 10, "fer": [[60, null]], "per": "Jiujutsu 2", "hab": [["Seiva Corrosiva", "Se uma árvore de lava sofrer dano, ela vaza uma seiva viscosa vermelha que causa 1k1 Ferimentos ao atacante se a vítima estiver a 1,5 m da árvore."], ["Imensa", ""], ["Sentido das Folhas", "Caminhar sobre as folhas da árvore de lava sem ser percebido requer um Teste Disputado de Furtividade (Esgueirar) / Agilidade contra a Percepção da árvore. Falha indica que a árvore de lava detecta sua presa e faz um ataque imediato (antes de jogar a Iniciativa)."], ["Invulnerabilidade Parcial (Fogo)", ""], ["Ataque de Ramos", "Os tentáculos da árvore de lava podem agarrar um alvo a até 4,5 m. Com um ataque bem sucedido, a árvore inicia uma Imobilização sobre seu alvo. O dano da Imobilização é de 4k2. A árvore de lava nunca sofre penalidades pelo Efeito Condicional Imobilizado."]], "nota": "A árvore de lava se parece com uma árvore arrancada e virada de cabeça para baixo, com caule e folhas vermelhas. As folhas cobrem os arredores, enquanto as raízes ondulam mesmo com o ar parado."}, {"id": "idi_takesasu_planta_ferrao", "n": "Takesasu (Planta-ferrão)", "tipo": "sombrio", "fonte": "IdI p. 227", "an": [0, 1, 0, 0], "tr": "Reflexos 1, Agilidade 3", "ini": "2k1", "atq": [["Cipó Venenoso", "4k3", "C", "1k1"]], "tn": 5, "red": 10, "fer": [[5, null]], "per": "", "hab": [["Rajada de Ácido", "Quando um takesasu é destruído, Bestas das Terras Sombrias sua reserva de ácido explode, automaticamente infligindo 2k2 Ferimentos em tudo dentro de 1,5 m."], ["Ataque de Ácido/Veneno", "Se seu ataque tiver sucesso, o espinho do takesasu perfura a pele do alvo e se prende à vítima, infligindo 1k1 Ferimentos e imediatamente injetando o veneno paralisante. A vítima deve passar num teste de Terra contra NA 25 ou ficar paralisada, incapaz de realizar Ações de qualquer tipo. Em cada rodada seguinte, a menos que o ferrão seja 227 removido (com um teste disputado de Agilidade) ou destruí"], ["Vulnerabilidade", "O takesasu é facilmente queimado, devido à sua composição seca. Qualquer ataque baseado em fogo (mundano ou mágico) inflige um adicional de 1k1 de dano por vez."]], "nota": "O takesasu parece com um alto caule morto. Em seu topo, pende um único cipó com um bulbo afiado."}, {"id": "idi_goblin_da_montanha", "n": "Goblin da Montanha", "tipo": "goblin", "fonte": "IdI p. 228", "an": [1, 3, 2, 1], "tr": "Reflexos 3, Agilidade 3, Força 3", "ini": "4k3", "atq": [["Garras", "4k3", "C", "4k2"], ["Arma", "4k3", "C", "—"]], "tn": 20, "red": 5, "fer": [[10, 5], [20, 10], [35, null]], "per": "Furtividade 4 Bestas das Terras Sombrias", "hab": [["Visão Noturna", "Goblins da montanha podem ver igualmente bem em penumbra como em luz normal."], ["Regeneração", "Goblins da montanha curam 5 Ferimentos durante o Estágio de Reações de cada Rodada, continuando a se curar até serem mortos. Eles podem religar membros mutilados em 2 rodadas, contanto que o membro e o ferimento sejam unidos durante este tempo."], ["Veloz 2 c", ""]], "nota": "À primeira vista, esta criatura lembra um goblin, mas é mais corpulento, sua pele é cinza e não verde, e sua cabeça chata e protuberante exibe uma crina de cabelo sujo. Diferente de goblins verdadeiros, goblins da montanha não são particularmente agressivos e são poucos em número."}, {"id": "idi_nikumizu_vermes_do_coracao", "n": "Nikumizu (Vermes do Coração)", "tipo": "sombrio", "fonte": "IdI p. 228", "an": [1, 1, 1, 1], "tr": "Reflexos 3", "ini": "3k3", "atq": [["Enterrar", "1k1", "C", "Especial (vide a"]], "tn": 20, "red": 0, "fer": [[4, null]], "per": "", "hab": [["Enterrar", "Uma vez que o ataque do nikumizu obtenha sucesso, ele se enterra na pele da vítima. Ele causa 4 Ferimentos a cada Rodada até que a vítima morra ou o nikumizu seja removido. A remoção só pode ser feita via cirurgia, o que requer um teste de Medicina/Agilidade contra NA 25. Cada tentativa por cirurgia cauda 2k2 Ferimentos no paciente."]], "nota": "“A criatura deve ser extirpada, a dificuldade disto depende da perícia do cirurgião e da cooperação do paciente.” – KUNI MOKUNA Nikumizus estão entre as menores criaturas das Terras Sombrias, mas isto não os torna menos perigosos. Estes vermes marrons medem cerca do tamanho de um dedo indicador huma"}, {"id": "idi_obake", "n": "Obake", "tipo": "sombrio", "fonte": "IdI p. 229", "an": [2, 3, 4, 1], "tr": "Reflexos 6, Força 3", "ini": "6k6", "atq": [["Ataque", "7k4", "S", "3k2"]], "tn": 35, "red": 5, "fer": [[10, 5], [30, 10], [50, null]], "per": "Intimidação (Provocação, Controle) 6, Sinceridade (Ardil) 6, Bastões 3", "hab": [["Regeneração", "A barganha do obake dificulta ele ser morto. Enquanto estiver vivo, ele curará 2 Ferimentos durante o estágio de Reações de cada Rodada."], ["Veloz 3", ""], ["Enxame de Vespas", "O obake pode liberar um enxame de vespas furiosas das colmeias em suas costas. Esta é uma Ação Complexa. O enxame pode voar a até 18 m dele e ataca até três alvos, infligindo 1k1 Ferimentos por rodada automaticamente. Um alvo afetado pelas vespas é considerado Atordoado e não pode invocar feitiços. Apenas efeitos que afetem áreas (feitiços que liberem jorros ou raios de fogo, ventos fortes, etc.) "]], "nota": "O obake é o horripilante lembrete de que nem todo mal vem das profundezas do Jigoku: ele às vezes pode ser encontrado em sua mais pura forma no coração dos homens. Alguns desses homens chegam à velhice manipulando todos que conhecem, subindo na vida através dos mais ambiciosos, repulsivos e detestáv"}, {"id": "idi_ogro_livre_tipico", "n": "Ogro Livre Típico", "tipo": "ogro", "fonte": "IdI p. 230", "an": [2, 3, 3, 2], "tr": "Reflexos 3, Vigor 6, Força 6", "ini": "4k3", "atq": [["tetsubo", "8k4", "C", "—"]], "tn": 30, "red": 15, "fer": [[20, 5], [40, 10], [60, 15], [80, null]], "per": "Batalha 1, Defesa 2, Jiujutsu 2, Armas Pesadas 4, Caça 1, Intimidação (Provocação) 2, Furtividade 1", "hab": [["Medo 2", ""], ["Imenso", ""]], "nota": ""}, {"id": "idi_ogro_livre_lider_tipico", "n": "Ogro Livre Líder Típico", "tipo": "ogro", "fonte": "IdI p. 230", "an": [3, 4, 3, 4], "tr": "Vigor 6, Força 6", "ini": "6k3", "atq": [["tetsubo", "9k4", "C", "—"]], "tn": 30, "red": 15, "fer": [[30, 5], [50, 10], [70, 15], [90, null]], "per": "Esportes 3, Batalha 3, Defesa 4, Jiujutsu 5, Armas Pesadas 5, Caça 3, Intimidação (Provocação) 5, Kenjutsu 2, Conhecimento: História (ogros) 2, Conhecimento: Submundo 1, Furtividade 3", "hab": [["Medo 2", ""], ["Imenso", ""]], "nota": ""}, {"id": "idi_ogro_livre_supremo_tipico", "n": "Ogro Livre Supremo Típico", "tipo": "ogro", "fonte": "IdI p. 231", "an": [4, 5, 4, 4], "tr": "Vigor 6, Força 7", "ini": "9k4", "atq": [["tetsubo", "10k6", "C", "ár-"]], "tn": 35, "red": 25, "fer": [[40, 5], [60, 10], [80, 15], [100, null]], "per": "Esportes 3, Batalha 6, Defesa 5, Jiujutsu 6, Armas Pesadas 7, Caça 4, Intimidação (Provocação) 7, Kenjutsu 4, Conhecimento: História (Ogros) 5, Conhecimento: Submundo 3, Sinceridade 2, Furtividade 5", "hab": [["Medo 3", ""], ["Imenso OGRO BRUXO/MAGO TÍPICO", ""]], "nota": ""}, {"id": "idi_ogro_livre_supremo_tipico", "n": "Ogro Livre Supremo Típico", "tipo": "ogro", "fonte": "IdI p. 231", "an": [2, 4, 4, 3], "tr": "Reflexos 3, Vigor 6, Força 6", "ini": "6k3", "atq": [["Clava", "7k5", "C", "8k2"]], "tn": 25, "red": 10, "fer": [[20, 5], [40, 10], [60, 15], [80, null]], "per": "Batalha 1, Defesa 3, Armas Pesadas 2, Caça 1, Jiujutsu 2, Intimidação (Provocação) 3, Conhecimento: História (Ogros) 5, Feitiçaria 5, Furtividade 1 Feitiços: Chamas Invejosas, Fogo Purificador, As Cha", "hab": [["Medo 2", ""], ["Imenso", ""]], "nota": "AR 4 TERRA 5 FOGO 4 ÁGUA 4 - VIGOR 6 - FORÇA 7 Iniciativa: 9k4 Ataque: Clava ou tetsubo 10k6 (Complexa) Dano: 9k2 (Clava ou ár- NA de Armadura: 35 vore pequena) ou 10k3 (usa Armadura Pesada) (Tetsubo) Redução: 25 (5 de Ar- Ferimentos: 40: +5; 60: +10; madura Pesada) 80: +15; 100: Morto Nível de Mácu"}, {"id": "idi_onibaba_bruxa_demonio", "n": "Onibaba (bruxa demônio)", "tipo": "sombrio", "fonte": "IdI p. 231", "an": [3, 3, 4, 3], "tr": "Reflexos 4, Força 4", "ini": "7k4", "atq": [["Garras", "7k4", "C", "4k3"], ["Faca", "6k4", "S", "—"], ["Tentáculo de Cabelo", "7k4", "S", "—"]], "tn": 25, "red": 5, "fer": "h", "per": "Atuação 4, Jiujutsu (Tentáculo de Cabelo) 3, Facas (Tanto) 2, Sinceridade (Ardil) 5, Furtividade 4, Tentação (Sedução) 5", "hab": [["Cabelo Demoníaco", "A onibaba pode estender ou retrair fios de seu cabelo à vontade, ao comprimento máximo de 12 m. Os fios podem ser usados como simples tentáculos preênseis, e também podem atacar, defender ou agarrar conforme a onibaba desejar. Cada tentáculo de cabelo pode agir completamente independente dos outros, mas a onibaba nunca controla mais do que 4 ao mesmo tempo. Ao atacar (como se fosse um 232 chicote)"], ["Medo 3", ""], ["Invulnerabilidade", ""], ["Metamorfose", "A onibaba pode assumir a forma de uma bela jovem como Ação Simples, e retornar à sua verdadeira forma como Ação Livre. Ela também assume automaticamente sua verdadeira forma se atacar"]], "nota": ""}, {"id": "idi_onikage", "n": "Onikage", "tipo": "sombrio", "fonte": "IdI p. 232", "an": [0, 4, 1, 4], "tr": "Reflexos 3, Agilidade 3, Força 6", "ini": "3k3", "atq": [["Cascos com Garras", "4k3", "C", "6k3"]], "tn": 20, "red": 10, "fer": [[40, null]], "per": "", "hab": [["Imenso", ""], ["Veloz 3", ""], ["Morto-Vivo", ""]], "nota": "P ara domar um onikage, o potencial cavaleiro deve primeiro montá-lo, precisando de um teste bem-sucedido de Esportes/Agilidade ou Cavalaria/Agilidade contra NA 25. Então vem a parte difícil: ficar sobre a criatura por 3 rodadas enquanto ela escoiceia, pula e faz o possível para tirar o cavaleiro de"}, {"id": "idi_sanshu_denki_monstro_do_lodo", "n": "Sanshu Denki (Monstro do Lodo)", "tipo": "sombrio", "fonte": "IdI p. 233", "an": [2, 3, 2, 4], "tr": "Reflexos 4, Agilidade 3", "ini": "4k4", "atq": [["Mordida", "5k3", "C", "7k4"]], "tn": 15, "red": 0, "fer": [[30, 5], [60, 15], [90, null]], "per": "Furtividade (Emboscada) 5", "hab": [["Aquático", "Sanshu denkis nadam tão facilmente quanto se movem em terra, se não mais. Eles não precisam fazer um teste de Perícia para nadar."], ["Caçador Cego", "O sanshu denki não sofre penalidades por sua cegueira, devido a seus sentidos superiores."], ["Imenso", ""], ["Choque", "Qualquer um que toque o sanshu denki com pele nua ou objetos metálicos sofre 3k1 Ferimentos e seu nível de Iniciativa é diminuído em 5 até o próximo Estágio de Reações. Isto pode afetar um personagem apenas uma vez por Rodada."], ["Engolir Inteiro", "Após um ataque bem-sucedido de mordida, o sanshu denki pode tentar segurar sua vítima, que é considerada Presa e só pode se libertar com um teste Disputado de Força. Em seu próximo turno, o sanshu denki pode engolir sua vítima como Ação Complexa. O personagem imediatamente sofre 2k1 Ferimentos e a mesma quantia para cada rodada em que permanecer na criatura. Após um número de Rodadas igual ao seu "]], "nota": "O sanshu denki é uma criatura anfíbia que habita os pântanos das Terras Sombrias. Ela se parece com uma imensa salamandra, de 9 m ou mais, de pele macia e mucosa num padrão de camuflagem preta e verde."}, {"id": "idi_goblin_do_pantano", "n": "Goblin do Pântano", "tipo": "goblin", "fonte": "IdI p. 233", "an": [2, 2, 1, 1], "tr": "Inteligência 3, Percepção 2", "ini": "3k2", "atq": [["Mordida", "4k2", "C", "2k1"], ["Clava", "5k1", "C", "—"]], "tn": 10, "red": 8, "fer": [[15, 10], [30, null]], "per": "Conhecimento: Terras Sombrias 4, Furtividade (Emboscada) 4", "hab": [["Aquático", "Goblins do pântano nadam em água tão facilmente quanto se movem em terra. Eles não precisam fazer um teste de Perícia para nadar."], ["Visão Noturna", "Goblins do pântano podem enxergar tão facilmente à noite quanto na luz fraca do dia."], ["Vulnerabilidade", "Goblins do pântano detestam calor. Qualquer ataque baseado em fogo lhes causa 1k1 de dano extra. oaThadeuHudsonEm"]], "nota": "Goblins do Pântano são goblins apenas no nome. Apesar de compartilharem características físicas e comportamentos gerais (o que lhes rendeu o nome), estas criaturas diabólicas são de fato bem diferentes dos bakemonos."}, {"id": "idi_troll_comum", "n": "Troll Comum", "tipo": "ogro", "fonte": "IdI p. 234", "an": [1, 3, 3, 3], "tr": "Reflexos 3, Vigor 5, Força 5", "ini": "5k3", "atq": [["Garras", "6k3", "S", "6k3"], ["Clava Grande", "5k3", "C", "—"]], "tn": 20, "red": 5, "fer": [[20, 5], [40, 10], [65, 15], [90, null]], "per": "Jiujutsu 3, Armas Pesadas 2, Furtividade (Emboscada) 4", "hab": [["Aquático", "Trolls não precisam fazer um teste de perícia para nadar, e podem permanecer debaixo d’água por um número de horas igual ao seu Vigor."], ["Visão em Baixa Luz", "Trolls podem enxergar facilmente na luz fraca e à noite, embora não na completa escuridão."]], "nota": "Como o nome sugere, trolls comuns (também chamados de trolls do pântano) são a mais numerosa subespécie de troll. Eles preferem evitar lutar, a menos que tenham vantagem clara ou quando invasores entram em seu território."}, {"id": "idi_umibozu_troll_marinho", "n": "Umibozu (troll marinho)", "tipo": "ogro", "fonte": "IdI p. 235", "an": [2, 4, 3, 2], "tr": "Força 6", "ini": "5k3", "atq": [["Garras", "5k3", "S", "6k3"], ["Língua", "6k4", "C", "—"]], "tn": 15, "red": 10, "fer": [[25, 5], [50, 10], [75, 15], [95, null]], "per": "Jiujutsu 2, Furtividade (Emboscada) 2", "hab": [["Aquático", "Trolls não precisam fazer um teste de Perícia para nadar, e podem permanecer debaixo d’água por um número de horas igual ao seu Vigor."], ["Visão em Baixa Luz", "Trolls podem enxergar facilmente em luz fraca e noite, embora não na completa escuridão."], ["Choque", "Qualquer um que toque um umibozu com pele nua ou itens de metal sofre um choque elétrico, causando 3k1 Ferimentos. O nível de Iniciativa da vítima é reduzido por 5 até o estágio de Reações da próxima Rodada. Isto pode afetar um personagem apenas uma vez por rodada."], ["Veloz 3 (na água)", ""]], "nota": "Umibozu são trolls que vivem no Mar das Sombras, a porção do Umi Amaterasu que banha as Terras Sombrias. Como trolls comuns, eles são reclusos apesar de seu poder real."}, {"id": "idi_o_umi_bozu_troll_marinho_gigante", "n": "O-umi-bozu (troll marinho gigante)", "tipo": "ogro", "fonte": "IdI p. 235", "an": [3, 6, 3, 6], "tr": "Agilidade 5, Força 8", "ini": "7k3", "atq": [["Garras", "9k5", "S", "10k6"]], "tn": 20, "red": 15, "fer": [[40, 5], [80, 10], [120, 15], [160, null]], "per": "Furtividade 6 (apenas debaixo d’água)", "hab": [["Aquático", "Assim como o troll normal, o o-umi-bozu não precisa fazer um teste de Perícia para nadar. Ele pode permanecer debaixo d’água indefinidamente."], ["Medo 4", ""], ["Imenso", ""], ["Visão Sobrenatural", "O o-umi-bozu pode enxergar perfeitamente na escuridão completa."], ["Cachoeira Esmagadora", "Como Ação Complexa, o o-umi-bozu pode lançar uma torrente de água de sua boca. O alcance deste ataque é de 12 m e inflige 8k4 Ferimentos em todos a 3 m do ponto de impacto. Ataques repetidos arrastarão a maioria dos prédios de madeira e danificarão seriamente estruturas de pedra por erodir suas fundações. Isto pode facilmente naufragar um barco, afundando-o."], ["Regeneração Aquática", "Enquanto o o-umi-bozu permanecer num grande corpo de água, ele cura 10 Ferimentos durante o estágio de Reações de cada Rodada."]], "nota": "X amãs trolls são tão raros que até mesmo a maioria dos estudiosos Kuni os consideram lendas. Isto é principalmente porque eles raramente deixam as tocas de suas tribos, e quando perturbados, eles escondem sua localização muito eficazmente."}, {"id": "idi_tsumunagi_enguia_de_sangue", "n": "Tsumunagi (Enguia de Sangue)", "tipo": "sombrio", "fonte": "IdI p. 236", "an": [1, 2, 1, 2], "tr": "Reflexos 3, Agilidade 2, Força 4", "ini": "4k3", "atq": [["Mordida", "4k2", "C", "3k1"]], "tn": 20, "red": 0, "fer": [[10, 10], [20, null]], "per": "Furtividade (Emboscada) 4", "hab": [["Rastejante", "A tsumunagi se move normalmente na água. Se estiver em terra, porém, ela se move apenas 1,5 m com uma Ação Simples e não pode se mover como Ação Livre. Porém, ela pode se enrolar como Ação Complexa e na Rodada subsequente ela pode saltar num alvo a até 4,5 m como Ação Livre"], ["Sugar", "Após um ataque bem sucedido, a tsumunagi se enrola num membro e começa a drenar sangue. A cada Rodada subsequente ela inflige automaticamente 2k2 Ferimentos de dreno de sangue. Remover a tsumunagi por força bruta requer um Teste Disputado de Força e inflige mais 2k1 Ferimentos com garras e dentes sendo soltos. Se não for imediatamente estancado (um teste de Medicina/Inteligência contra NA 20) o fe"], ["Veloz 4 (na água)", ""], ["Vulnerabilidade", "Fogo ou calor farão a tsumunagi se retrair em dor, liberando a vítima que foi mordida."]], "nota": "“Apesar de eu não estar certo de que picar estas coisas em pedaços pequenos após a remoção seja absolutamente necessário, é extremamente satisfatório.” – KUNI MOKUNA 236 A tsumunagi é algum tipo de cruzamento entre uma lesma monstruosa e uma enguia, e só é encontrada nas regiões mais Maculadas das T"}, {"id": "idi_yamauba_a_ogra_da_montanha", "n": "Yamauba, a Ogra da Montanha", "tipo": "ogro", "fonte": "IdI p. 237", "an": [4, 3, 3, 3], "tr": "Força 5", "ini": "6k4", "atq": [["Garras", "6k3", "S", "6k2"]], "tn": 25, "red": 8, "fer": [[20, 5], [50, 10], [80, null]], "per": "Atuação 4, Etiqueta 3, Sinceridade (Ardil) 4", "hab": [["Invulnerável", ""], ["Face da Mãe", "Uma yamauba se parece com a mãe da pessoa que olha para ela. Esta ilusão pode ser exposta se ela morrer, atacar ou alguém notar sua pele gélida ou a pequena boca dentada nas costas de seu pescoço. NOVA ESCOLA BÁSICA: OGRO LIVRE BUSHI [BUSHI] Os chamados ogros livres, assim que começam a se libertar do controle direto do Jigoku, rapidamente descobrem que se lembram de um antigo conjunto de técnicas"], ["Bônus", "Força +1 c"]], "nota": "“Acabei com o Mês das Crianças Mortas.” – KAIU YUKIO, 602 A criatura conhecida como Ogra da Montanha é uma caçadora solitária com um poder singular: qualquer pessoa que olhe para ela verá a sua própria mãe. Naturalmente, ela prefere evitar multidões."}, {"id": "idi_kitsune", "n": "Kitsune", "tipo": "espirito", "fonte": "IdI p. 246", "an": [2, 2, 2, 1], "tr": "Reflexos 5, Percepção 4", "ini": "6k5", "atq": [["Garras", "2k2", "C", "2k1"]], "tn": 25, "red": 0, "fer": [[15, 10], [30, 20], [45, null]], "per": "", "hab": [["Metamorfose", "Toda kitsune possui as Habilidades e Penalidades Metamórficas listadas no capítulo. Uma kitsune “típica” terá: Imitar, Movimentos de Pantera, Proteção do Yomi e Forma Efêmera."], ["Espírito", ""], ["Veloz 3", ""]], "nota": "Espíritos raposas são as mais numerosas e famosas criaturas do Reino dos Animais. A forma natural dos kitsunes é a de uma raposa com várias caudas, variando entre duas (um espírito raposa menor) a nove (uma deusa da floresta)."}, {"id": "idi_kitsune_tsuki", "n": "Kitsune-tsuki", "tipo": "espirito", "fonte": "IdI p. 246", "an": [2, 2, 3, 4], "tr": "", "ini": "7k4", "atq": [["Garras", "6k3", "C", "4k2"]], "tn": 20, "red": 5, "fer": [[15, 10], [30, 15], [45, 20], [60, null]], "per": "", "hab": [["Invulnerabilidade Parcial", "A kitsune-tsuki é Invulnerável a todas as armas mundanas."], ["Possessão", "A kitsune-tsuki pode tentar possuir qualquer alvo que esteja dormindo ou que esteja nos Níveis de Ferimentos Abatido ou Inconsciente. A vítima deve fazer um teste de Vontade contra NA 25 ou ser possuída. A kitsune-tsuki deve sair de seu hospedeiro dentro de vinte e quatro horas após a possessão."], ["Espírito", ""], ["Ataque Espiritual", "Os ataques da kitsune-tsuki ignoram armadura, tanto o bônus ao NA de Armadura e qualquer Redução recebida pela armadura."]], "nota": "Quando uma kitsune morre ela tenta limpar sua mente e alma dos problemas do mundo, para entrar na próxima vida com tran- quilidade. As que falham em fazê-lo são consumidas pelas falhas dessa vida e se transformam numa kitsune-tsuki, uma mortífera e atormentada sátira da nobre criatura que elas já fo"}, {"id": "idi_buruburu", "n": "Buruburu", "tipo": "espirito", "fonte": "IdI p. 247", "an": [2, 1, 2, 1], "tr": "", "ini": "3k2", "atq": [], "tn": 10, "red": 10, "fer": [[10, 10], [20, null]], "per": "", "hab": [["Decaída ao Terror", "Toda noite, uma vítima possuída por um buruburu sofre terríveis pesadelos. A vítima deve jogar Vontade contra NA 20. Se falhar, ela é considerada não tendo descansado durante a noite. Após três dias de falhas consecutivas nestes testes, o alvo tem uma penalidade de NA +5 em todos os testes (exceto testes de Vontade para resistir aos pesadelos). Cada dia consecutivo depois disto soma mais uma penal"], ["Mestre do Invisível", "O buruburu é difícil de detectar pela visão ou outros meios convencionais. Ele não pode ser visto a olho nu, e só os que sabem de seus efeitos sobre suas vítimas serão capazes de discernir sua presença. Os que reconhecem seu impacto em suas vítimas podem fazer um Teste Disputado de Astúcia para detectar sua presença. A criatura também pode ser detectada por meios mágicos como o feitiço Pela Luz da"], ["Possessão", "O buruburu pode possuir sua vítima se ela falhar num Teste Disputado de Vontade contra o espírito. Uma vez possuído, o alvo pode tentar um Teste Disputado de Vontade uma vez por semana para repelir o buruburu. Diferente de outras formas de possessão, o buruburu não pode controlar as ações de sua vítima totalmente."], ["Espírito", ""]], "nota": "A fome que guia as criaturas do Gaki-dô não se limita a alimentar o corpo. Algumas criaturas ganham energia de fontes diferentes de depravação e corrupção."}, {"id": "idi_o_toyo", "n": "O-toyo", "tipo": "espirito", "fonte": "IdI p. 248", "an": [2, 2, 2, 3], "tr": "Reflexos 4, Agilidade 4, Percepção 4", "ini": "2k1", "atq": [["Presas", "9k4", "C", "5k3"]], "tn": 25, "red": 3, "fer": [[20, 10], [40, null]], "per": "", "hab": [["Aparência Ilusória", "O o-toyo pode mudar sua forma para a de um gato caseiro comum à vontade. Uma pessoa que o visualize pode testar Percepção contra Na 25 para ver sua forma verdadeira pelo canto do olho."], ["Destruidor da Vida", "O o-toyo drena a essência daqueles sob suas presas. Cada ataque bem sucedido cura o o-toyo de 5 Ferimentos."], ["Espírito", ""]], "nota": "Ninguém sabe exatamente como o o-toyo é formado, e ainda assim sua presença no mundo é dolorosamente sentida. Diferente de alguns espíritos do Gaki-dô, o o-toyo tem uma forte forma corpórea no reino mortal."}, {"id": "idi_mokumokuren", "n": "Mokumokuren", "tipo": "espirito", "fonte": "IdI p. 248", "an": [0, 1, 0, 0], "tr": "Inteligência 1, Percepção 6", "ini": "2k1", "atq": [["Ataque Mental", "6k4", "C", "4k4"]], "tn": 5, "red": 0, "fer": [[10, 10], [20, null]], "per": "", "hab": [["Ataque do Olhar", "O ataque mental do mokumokuren ignora qualquer armadura e Redução que a vítima tenha. Os Ferimentos que o mokumokuren inflige são espirituais e não deixam ferimentos externos diretos — assim, não podendo serem tratados com Medicina, embora cura mágica ou natural funcione normalmente."], ["Espírito", ""], ["Invulnerabilidade Superior", "Mokumokurens sofre dano normal de magia e jade, mas não sofre Ferimentos por nenhuma outra forma de ataque."], ["Os Cantos do Mundo", "Mokumokurens existem dentro das fronteiras do Ningen-dô e só podem habitar paredes de papel. Se uma vítima olhar nos olhos do mokumokuren, ele imediatamente faz seu ataque mental. O mokumokuren não pode atacar sob nenhuma outra circunstância."]], "nota": "O mokumokuren é uma besta peculiar, especialmente porque 248 ninguém jamais viu sua forma verdadeira. Ele é facilmente banido do reino mortal e se alimenta apenas dos incautos."}, {"id": "idi_hannya", "n": "Hannya", "tipo": "espirito", "fonte": "IdI p. 249", "an": [3, 3, 3, 3], "tr": "Reflexos 5, Agilidade 6, Força 5", "ini": "6k5", "atq": [["Garras", "8k6", "S", "de"]], "tn": 30, "red": 4, "fer": "h", "per": "Atuação 2, Arte: Pintura 1, Arte: Poesia 1, Jogos: Go 1, Iaijutsu 1, Kenjutsu 1", "hab": [["Alterar Forma", "A hannya tem a habilidade de mudar seu corpo para imitar a forma básica das pessoas próximas. Esta é uma Ação Complexa. Ela sempre parece ser mulher."], ["Medo 2", ""], ["Imitar Rival", "A hannya sempre se fixa num alvo como seu rival. Escolha uma das perícias da hannya que é compartilhada pelo seu alvo; a hannya competirá com o alvo usando esta perícia. Se ela perder, é possível que ela usará esta perícia exclusivamente para assassinar seu rival (se a competição não envolver perícia marcial, a hannya rasgará o adversário em pedaços com suas garras)."], ["Espírito", ""]], "nota": "Demônios do Jigoku escapam para o Ningen-dô pelo Poço Infecto. Muitos residem nas Terras Sombrias sem jamais entrarem nas terras humanas."}, {"id": "idi_koku_no_seishin", "n": "Koku no Seishin", "tipo": "espirito", "fonte": "IdI p. 249", "an": [2, 2, 2, 2], "tr": "Reflexos 3, Força 4", "ini": "3k2", "atq": [["Garras", "5k3", "C", "5k2"]], "tn": 15, "red": 6, "fer": [[15, 5], [30, 10], [45, 15], [60, null]], "per": "", "hab": [["Medo 3 Os Espíritos", ""], ["Tomar Vida", "O Koku no Seishin pode tentar ganhar forma corpórea sugando a vida daqueles à sua volta. Isto é uma Ação Complexa. O alvo deve fazer um Teste Disputado com um Anel (à escolha do koku no seishin) contra o resultado da jogada do koku no 249 seishin em 5k3. O vencedor do Teste Disputado ganha +1 Nível no Anel escolhido e cura 20 Ferimentos. O perdedor do Teste Disputado sofre -1 Nível neste Anel (ao "], ["Espírito", ""]], "nota": "Estas criaturas são chamadas almas vazias por aqueles que as encontram. Eles são uma perversa combinação de múltiplos Reinos Espirituais."}, {"id": "idi_koumori_espirito_morcego", "n": "Koumori (espírito morcego)", "tipo": "espirito", "fonte": "IdI p. 250", "an": [4, 3, 3, 2], "tr": "Reflexos 5, Inteligência 4", "ini": "6k4", "atq": [["Katana", "7k3", "C", "5k2"], ["Garras", "5k3", "C", "—"]], "tn": 30, "red": 3, "fer": [[15, 5], [30, 10], [45, 15], [60, 20], [75, null]], "per": "Esportes 4, Defesa 3, Kenjutsu 4, Furtividade 5", "hab": [["Metamorfo", "Koumoris são Metamorfos e podem usar as Habilidades e Penalidades Metamórficas listadas ainda neste capítulo."], ["Espírito", ""], ["Veloz 3 (ao voar)", ""]], "nota": "Espíritos metamorfos morcegos sempre tiveram fortes laços com a sobrevivência da raça humana. Eles ficaram nas sombras e ajudaram a humanidade de várias maneiras, realizando esses deveres sem deixar os rokuganis saberem de seu envolvimento."}, {"id": "idi_hagaken_mokumokuren", "n": "Hagaken Mokumokuren", "tipo": "espirito", "fonte": "IdI p. 250", "an": [2, 3, 3, 4], "tr": "Reflexos 4, Agilidade 4", "ini": "6k4", "atq": [["Katana", "8k4", "S", "7k2"]], "tn": 40, "red": 5, "fer": [[32, 10], [64, 15], [96, null]], "per": "Defesa 4, Jiujutsu 3, Kenjutsu 4", "hab": [["Guardião Eterno", "Se o Hagaken mokumokuren realizar a ação Guardar, o bônus de NA de Armadura que concede é aumentado em +5 para ele e seu alvo."], ["Incorpóreo", "O Hagaken mokumokuren mantém uma forma nebulosa e incorpórea, mesmo enquanto ataca; isto é responsável por seu NA de Armadura maior. Aqueles com formas extraordinárias de visão (como visão de calor, movimento ou visão noturna) ganham um bônus de +5 em testes de ataque contra ele. Um oponente sem essas habilidades pode usar uma Ação Simples para fazer um Teste de Astúcia contra NA 25 para ganhar es"], ["Tabuleta da Alma", "O Hagaken mokumokuren não pode ser morto a menos que sua tabuleta seja destruída. Se o Hagaken mokumokuren for reduzido a Morto enquanto esta tabuleta ainda estiver inteira, ele se revive com Ferimentos totais em uma hora. A tabuleta em si pode tomar qualquer forma, embora normalmente seja uma pequena tabuleta de preces de cerca de 15 cm de comprimento. Ela pode ser destruída com dois golpes físic"], ["Espírito", ""]], "nota": "O mokumokuren é uma criatura do Gaki-dô, e sua fome devorou dúzias de vítimas incautas. O Hagaken mokumokuren é uma criatura completamente diferente, um espírito único criado por fortuita coincidência."}, {"id": "idi_bakeneko", "n": "Bakeneko", "tipo": "espirito", "fonte": "IdI p. 251", "an": [2, 2, 2, 2], "tr": "", "ini": "3k2", "atq": [["Garras", "3k2", "C", "2k2"]], "tn": 10, "red": 5, "fer": [[10, 5], [20, 10], [30, null]], "per": "Defesa 4, Jiujutsu 3, Kenjutsu 4", "hab": [["Metamorfo", "Bakenekos são Metamorfos e podem usar as Habilidades e Penalidades Metamórficas descritas ainda neste capítulo."], ["Espírito", ""]], "nota": "Dizem que gatos são criaturas de grande curiosidade, seguindo objetos de que gostem até suas mortes. Esses ditados devem ter se originado pelo bakeneko, espíritos metamórficos originários dos Reinos de Sakakku e Chikushudô."}, {"id": "idi_konak_jiji", "n": "Konak Jiji", "tipo": "espirito", "fonte": "IdI p. 251", "an": [1, 2, 3, 2], "tr": "", "ini": "3k2", "atq": [["Garras", "5k3", "C", "2k1"]], "tn": 10, "red": 3, "fer": [[10, 5], [20, 10], [30, null]], "per": "", "hab": [["ita", ""], ["Peso Ilusório", "Se o konak jiji for pego, ele automaticamente atinge o alvo, sem necessidade para uma rolagem de ataque. Adicionalmente, o peso do konak jiji aumenta para 180 kg, prendendo o alvo até que seja movido. Mover um konak jiji que tenha aumentado seu peso requer um teste de Esportes/Força contra NA 40 (isto pode ser feito como um Teste Cooperativo)."], ["Veneno Paralisante", "Se um konak jiji atingir alguém Os Espíritos com sucesso, ele injeta um veneno paralisante. O alvo é considerado Paralisado por um número de minutos igual à Água do konak jiji."], ["Espírito 251", ""]], "nota": "Os konak jijis são primos distantes dos pekkles. Eles são espíritos que lembram bebês humanos."}, {"id": "idi_mujina", "n": "Mujina", "tipo": "espirito", "fonte": "IdI p. 252", "an": [3, 3, 3, 3], "tr": "", "ini": "6k3", "atq": [], "tn": 15, "red": 0, "fer": [[50, null]], "per": "", "hab": [["Forma Fantasmagórica", "Um Mujina é naturalmente intangível enquanto está no Ningen-dô, e pode escolher passar através de objetos físicos. Ele pode se tornar tangível se quiser interagir com objetos físicos (como atirar coisas ou quebrar objetos de valor). Já que pode se tornar tangível ou intangível à vontade (uma Ação Livre que pode ser usada ilimitadas vezes), normalmente ele só pode ser ferido se escolher estar tangí"], ["Imortal", "Um mujina não pode ser de fato morto no reino mortal. Se reduzido a Morto, ele simplesmente retorna para o Sakkaku por um ano e um dia, a menos que alguém o convoque antes. Ele normalmente voltará para pregar peças em quem o “matou”."], ["Invisibilidade", "Um Mujina pode se tornar invisível à vontade, ocultando-se em um kami do Ar amigável, e pode permanecer invisível mesmo enquanto conjura feitiços."], ["Resistência a Magia (+6 NA para Testes de Conjuração)", ""], ["Conjuração", "Um mujina pode conjurar feitiços como se fosse um shugenja de Nível 3. Ele tem infinitos espaços de feitiços por dia mas só pode conjurar os feitiços listados aqui."], ["Espírito", ""], ["Veloz 6 (ao voar). Embora mujinas tenham asas extremamente p", ""]], "nota": ""}, {"id": "idi_orochi", "n": "Orochi", "tipo": "espirito", "fonte": "IdI p. 252", "an": [3, 7, 3, 4], "tr": "Reflexos 4, Agilidade 6, Força 9", "ini": "5k4", "atq": [["Mordida", "10k8", "C", "10k5"], ["Garras", "10k6", "S", "—"]], "tn": 30, "red": 7, "fer": [[35, 5], [70, 10], [105, 20], [140, 25], [200, null]], "per": "", "hab": [["Anfíbio", "Orochis podem sobreviver igualmente na água ou em terra, e não precisam fazer testes de Esportes para nadar. Porém, fora da água eles se movem como se sua Água fosse 2 níveis menores. Eles preferem a segurança e solidão das profundezas."], ["Constrição", "Os orochis podem espremer suas vítimas com seu corpo imenso. Se um orochi atingir seu alvo com suas garras, ele pode optar em iniciar uma Imobilização, jogando 10k10 para controlá-la. A cada Rodada em que ele controlar a Imobilização, ele causará 5k5 de dano em seu Turno."], ["Imenso", ""], ["Resistência Mágica (+6 no NA para Testes de Conjuração)", ""], ["Espírito", ""], ["Engolir Inteiro", "Se a jogada de ataque de um Orochi exceder o NA de Armadura de um alvo de tamanho humano por 20 ou mais, o alvo será engolido. Um alvo engolido pode tentar usar armas Pequenas para atacar o orochi por dentro e causar automaticamente 5k4 a cada Rodada no Turno do orochi. Um orochi pode engolir até cinco alvos de tamanho humano de uma vez."], ["Veloz 3 (enquanto na água)", ""]], "nota": "Estas criaturas ofídias titânicas vivem nos fundos dos oceanos de Rokugan e do Sakkaku, mas preferem as profundezas dos mares de Rokugan, a milhas de distância dos afazeres do homem e a um reino inteiro de distância do Sakkaku. Um número limitado de orochis entrou no mundo mortal séculos atrás para "}, {"id": "idi_pekkle", "n": "Pekkle", "tipo": "espirito", "fonte": "IdI p. 253", "an": [5, 4, 2, 1], "tr": "", "ini": "5k5", "atq": [["Garras", "4k2", "C", "1k1"]], "tn": 15, "red": 3, "fer": [[15, 5], [30, 10], [45, 20], [60, null]], "per": "Atuação (Clã, Sexo, Profissão) 6, Corte (Manipulação) 3, Etiqueta 3, Sinceridade 5, Tentação 4", "hab": [["Invulnerabilidade Parcial", "O pekkle reduz todo dano que sofrer pela metade (arredondada para baixo), independentemente de sua fonte. Dados de dano não explodem contra o pekkle, a menos que especificamente mencionado numa habilidade ou Técnica (como a dos Berserkers Matsu Nível 5)."], ["Espírito ita", ""]], "nota": "Os pekkles são perigosos e cruéis espíritos trapaceiros. É curioso o fato dos pekkles permanecerem relativamente desconhecidos pelos rokuganis enquanto seus primos corrompidos e manipuladores, os Pekkle no Oni, são bastante conhecidos e odiados."}, {"id": "idi_ryu_espirito_dragao", "n": "Ryu (espírito dragão)", "tipo": "espirito", "fonte": "IdI p. 254", "an": [4, 3, 4, 3], "tr": "Inteligência 5, Percepção 4", "ini": "7k4", "atq": [["Garras", "8k4", "S", "6k3"]], "tn": 30, "red": 5, "fer": [[15, 5], [30, 10], [45, 15], [60, 20], [75, null]], "per": "", "hab": [["Metamorfo", "O ryu é um metamorfo e pode usar as Habilidades e Penalidades Metamórficas listadas ainda neste capítulo."], ["Alma de um Dragão", "Um ryu age como arauto do Tengoku e dos Dragões Elementais, e estes grandes seres concedem uma parte de seu poder ao ryu. Embora sirvam aos desejos dos Dragões Elementais, o Anel Elemental apropriado (e seus Anéis) aumentam para 6, e ele ganha os seguintes benefícios:"], ["Dragão do Ar", "NA de Armadura 40"], ["Dragão da Terra", "Ferimentos: 25: +5; 50: +10; 75: +15; 100: +20; 150: Morto"], ["Dragão do Fogo", "Ataque — Garras 10k6 (Simples)"], ["Dragão da Água", "Dano da Garra 8k5"], ["Dragão do Vazio", "Redução 10"], ["Espírito", ""], ["Veloz 4 (ao voar)", ""]], "nota": "RYU O ryu é um espírito menor comparado aos Dragões Elementais propriamente ditos, ainda assim os mortais dificilmente reconheceriam isso quando diante da majestade de um ryu. A forma natural de um ryu é a de uma serpente voadora com escamas que brilham em cor luminescente."}, {"id": "idi_fushicho_fenix", "n": "Fushicho (Fênix)", "tipo": "espirito", "fonte": "IdI p. 254", "an": [3, 3, 5, 3], "tr": "", "ini": "—", "atq": [["Bico", "8k5", "C", "6k3"]], "tn": 20, "red": 3, "fer": [[15, 5], [30, 10], [45, 20], [60, null]], "per": "", "hab": [], "nota": "As fushichos são espíritos que lembram as houhous, nobres aves dos Paraísos Celestiais. As houhous frequentemente vivem no reino mortal, porém, enquanto as fushicho executam quaisquer deveres que exijam que elas viajem para outros Reinos Espirituais."}, {"id": "idi_tennyo", "n": "Tennyo", "tipo": "espirito", "fonte": "IdI p. 255", "an": [2, 3, 4, 3], "tr": "Percepção 8", "ini": "4k2", "atq": [["Arma   — as tennyos podem usar todas as ", "7k4", "C", "De acordo com a"]], "tn": 15, "red": 3, "fer": [[20, 5], [40, 10], [60, null]], "per": "", "hab": [["Metamorfo", "Koumoris são Metamorfos e podem usar as Habilidades e Penalidades Metamórficas listadas ainda neste capítulo."], ["Espírito", ""], ["Veloz 4", ""]], "nota": "As tennyo (ou tennin, como as versões masculinas são chamadas) são criaturas curiosas que vivem nos limites do Tengoku. Diferente de muitos dos habitantes deste reino, as tennyos não são boas nem estão no topo da Ordem Celestial."}, {"id": "idi_shutsudohin", "n": "Shutsudohin", "tipo": "espirito", "fonte": "IdI p. 256", "an": [3, 3, 3, 3], "tr": "Agilidade 5", "ini": "4k3", "atq": [["Arma", "4k3", "C", "5k3"]], "tn": 20, "red": 5, "fer": [[15, 5], [30, 10], [45, 20], [60, null]], "per": "", "hab": [["Arsenal Excepcional", "O Shutsudohin pode mudar para a forma de uma arma samurai ou armadura samurai. Se assumir a forma de uma arma, sua jo- gada de ataque se torna 8k4 (Simples). Se assumir a forma de uma armadura, seu NA de Armadura aumenta para 30 e sua Redução aumenta para 10."], ["Espírito", ""]], "nota": ""}, {"id": "idi_guarda_abencoada", "n": "Guarda Abençoada", "tipo": "espirito", "fonte": "IdI p. 256", "an": [4, 4, 5, 4, 5], "tr": "Reflexos 5, Agilidade 6", "ini": "8k5", "atq": [["Katana", "10k7", "S", "7k2"]], "tn": 40, "red": 5, "fer": [[20, 5], [40, 10], [60, 15], [80, 20], [100, null]], "per": "Defesa 5, Kenjutsu 6, Conhecimento: Bushidô 5, Conhecimento: Gaki-dô 4, Conhecimento: Terras Sombrias 4, Conhecimento: Toshigoku 3, muitas outras perícias de Armas em Nível 5, outras perícias possuída", "hab": [["Luz do Yomi", "Uma vez por luta, um Guarda Abençoado pode usar uma Ação Complexa para afetar um oponente com Nível de Honra menor (criaturas sem Nível de Honra são consideradas com 0 de Honra para fins desta habilidade). Este oponente não pode realizar Ações Simples ou Complexas durante seu próximo Turno."], ["Espírito", ""]], "nota": "Todo membro da Guarda Abençoada já foi um ancestral normal, e ainda assim, cada um destes samurais ganhou grande importância no Yomi. Como o Yomi é um Reino Espiritual que vê favoravelmente os humanos que vivem em Rokugan, Os Espíritos os inimigos de Rokugan regularmente tentam destruí-lo."}, {"id": "idi_transcendentes_nezumis", "n": "Transcendentes Nezumis", "tipo": "espirito", "fonte": "IdI p. 256", "an": [4, 4, 5, 4], "tr": "Agilidade 5", "ini": "10k5", "atq": [["Faca", "9k3", "C", "5k1"]], "tn": 20, "red": 3, "fer": [[15, 5], [30, 10], [45, 15], [60, 20], [75, null]], "per": "Defesa 5, Caça 4, Investigação 5, Facas 6, Conhecimento: Magia de Nomes 10, Conhecimento: Terras Sombrias 5, Conhecimento: Reinos Espirituais (Yume-dô) 7, Meditação 8", "hab": [["Transcendentes mantêm todas as Habilidades Físicas de Roedor", ""], ["Invulnerabilidade", ""], ["Espírito", ""]], "nota": "Os xamãs nezumis têm a peculiar habilidade de transcender a realidade e se tornarem criaturas de puro Nome, ascendendo ao Yume-dô para viver para sempre. Embora habitem o Reino dos Sonhos, os Transcendentes sempre vigiam o bem-estar de sua raça no Ningen-dô."}, {"id": "idi_baku", "n": "Baku", "tipo": "espirito", "fonte": "IdI p. 257", "an": [3, 4, 4, 4], "tr": "", "ini": "—", "atq": [["Garras", "9k5", "S", "8k4"]], "tn": 20, "red": 3, "fer": [[20, 5], [40, 15], [60, null]], "per": "", "hab": [], "nota": "Os bakus são o coração do Reino dos Sonhos. Sem os bakus, os sonhadores dos outros mundos nunca teriam acesso ao Yume-dô durante seu sono."}, {"id": "idi_baku_no_oni", "n": "Baku no Oni", "tipo": "espirito", "fonte": "IdI p. 257", "an": [4, 5, 3, 3], "tr": "Reflexos 5, Agilidade 4, Força 5", "ini": "8k5", "atq": [["Garras", "9k4", "S", "8k3"]], "tn": 30, "red": 8, "fer": [[30, 5], [50, 15], [80, null]], "per": "", "hab": [["Forja de Pesadelos", "O Baku no Oni pode tomar muitas formas diferentes, mas não possui Habilidades ou Penalidades Metamórficas listadas neste capítulo. Ele Os Espíritos muda de forma como Ação Livre mas seus atributos não mudam quando ele muda de forma."], ["Sono Hipnotizante", "Se o Baku no Oni atingir um alvo com sucesso um número de vezes igual ao Anel de Vazio do alvo na mesma luta, o Baku no Oni invoca os poderes do pesadelo sobre o alvo. O alvo deve fa257 zer um teste de Vontade contra NA 20 ou cair num sono sem sonhos que dura 24 horas. Este sono não pode ser quebrado por meios normais, mas se o alvo sofrer mais de 10 Ferimentos ele acorda imediatamente. Feitiços q"], ["Espírito oaThadeuHudsonEm", ""]], "nota": "Baku no Oni são os reflexos sombrios dos bakus. Eles servem à mesma função que os bakus, transformando-se para servir aos pensamentos do sonhador quando ele toca o Reino dos Sonhos."}, {"id": "idi_ghul", "n": "Ghul", "tipo": "morto", "fonte": "IdI p. 269", "an": [1, 2, 1, 2], "tr": "Reflexos 3, Vigor 4, Agilidade 3, Força 4", "ini": "4k3", "atq": [["Garras", "4k3", "C", "5k2"]], "tn": 20, "red": 5, "fer": [[72, null]], "per": "", "hab": [["Medo 3", ""], ["Ataque à Garganta", "Se um ghul causar 15 ou mais Ferimentos num só ataque de garras, ele investirá e tentará atacar a garganta da vítima. Este ataque adicional é feito como uma Ação Livre com uma jogada de ataque de 5k3 e dano de 4k1."], ["Morto-Vivo ita", ""]], "nota": "Nas terras conhecidas como Areias Ardentes, além das fronteiras ocidentais de Rokugan, a necromancia é praticada em mais de um reino. O reino Senpet ficou famoso por criar mortos-vivos por seus rituais religiosos, e um bando de cultistas conhecido como Chacais expandiu as atividades Senpets a método"}, {"id": "idi_harionago", "n": "Harionago", "tipo": "morto", "fonte": "IdI p. 270", "an": [3, 3, 3, 3], "tr": "", "ini": "3k3", "atq": [["Garras", "8k4", "C", "3k3"], ["Ganchos de Cabelo", "4k4", "C", "—"]], "tn": 20, "red": 10, "fer": [[80, null]], "per": "Atuação 3, Jiujutsu 4, Sinceridade (Ardil) 3, Furtividade 4, Tentação 3", "hab": [["Gancho Imobilizador", "Se a Harionago atingir um oponente com seus ganchos de cabelo, ela os usará para Imobilizar o inimigo. Ela pode usar seus ataques de garras para atacar um oponente Imobilizado. Um oponente que consiga se libertar da Imobilização sofre 1k1 Ferimentos quando os ganchos são arrancados."], ["Veloz 1", ""], ["Morto-Vivo", ""]], "nota": ""}, {"id": "idi_hyakuhei", "n": "Hyakuhei", "tipo": "morto", "fonte": "IdI p. 270", "an": [1, 4, 2, 3], "tr": "Reflexos 3, Agilidade 3, Força 4", "ini": "4k3", "atq": [["Arma", "5k3", "C", "De acordo com a"], ["Garras", "4k3", "C", "—"]], "tn": 20, "red": 5, "fer": [[80, null]], "per": "Esportes 3, Batalha 2, várias Perícias de Armas em 2", "hab": [["Medo 4", ""], ["Morto-Vivo", ""]], "nota": "Hyakuheis são criados a partir de samurais que morrem nas Terras Sombrias, atraindo kansens incomumente poderosos para trazer seus corpos de volta à não-vida. Diferentemente de muitos mortos-vivos animados nas Terras Sombrias, Hyakuhei conservam parte da inteligência que tinham em vida, junto com um"}, {"id": "idi_kekkai", "n": "Kekkai", "tipo": "morto", "fonte": "IdI p. 271", "an": [1, 1, 1, 1], "tr": "", "ini": "2k1", "atq": [["Punho", "1k1", "S", "1 Ferimento"]], "tn": 10, "red": 5, "fer": [[16, null]], "per": "", "hab": [["ita", ""], ["Medo 4", ""], ["Invulnerabilidade", ""], ["Purificação", "Um shugenja pode tentar livrar-se de um kekkai realizando um elaborado ritual de purificação. Isto requer uma hora de preces seguida por um Teste Disputado do Vazio do shugenja contra a Mácula do kekkai."], ["Morto-Vivo", ""]], "nota": "Sangue não santificado é uma das substâncias mais impuras conhecidas pelos rokuganis, motivo pelo qual sacerdotes estão sempre engajados em rituais de purificação após nascimento, morte, batalha ou qualquer incidente similar que resulte no derramamento de sangue. Se tais rituais não forem realizados"}, {"id": "idi_nukekubi", "n": "Nukekubi", "tipo": "morto", "fonte": "IdI p. 271", "an": [1, 2, 1, 2], "tr": "Reflexos 4, Agilidade 3", "ini": "3k3", "atq": [["Arma", "3k3", "C", "—"], ["Mordida", "4k3", "S", "—"]], "tn": 25, "red": 5, "fer": [[36, null]], "per": "", "hab": [["Medo 3", ""], ["Veloz 2 (só com a cabeça solta) doaThadeuHudsonEm", ""], ["Cabeça Voadora", "Um nukekubi pode soltar e religar sua cabeça a qualquer momento entre o pôr e o nascer do sol. Isto é uma Ação Simples. Enquanto estiver solta, a cabeça pode levitar e voar em qualquer dire- ção. Porém, se não puder retornar ao seu corpo até o nascer do sol, ele morrerá."], ["Invulnerável", ""], ["Morto-Vivo", ""], ["Corpo Vulnerável", "Enquanto a cabeça de um nukekubi está solta, seu corpo não é Invulnerável. 272 NUPPEPPO Nuppeppos são criaturas de fato indescritíveis, pois são Os Mortos-Vivos amontoados animados de carne desprovidos de ossos. Eles não são exatamente cadáveres, como zumbis ou hyakuheis, mas são pilhas amorfas de pele e tecidos podres e fedorentos. Eles surgem frequentemente de restos imbuídos de Mácula daqueles "]], "nota": "Estas criaturas parecem ser formas mais fracas e primitivas de pennagolans, embora alguns Kuni achem que eles sejam de fato um tipo totalmente diferente de entidade. Eles sugerem que nukekubis são criações de experimentos de maho, embora ninguém jamais tenha lhes dado crédito."}, {"id": "idi_nuppeppo", "n": "Nuppeppo", "tipo": "morto", "fonte": "IdI p. 272", "an": [1, 1, 0, 1], "tr": "Vigor 3, Agilidade 2, Força 2", "ini": "2k1", "atq": [["Clava", "2k2", "S", "3k2"]], "tn": 10, "red": 15, "fer": [[24, null]], "per": "", "hab": [["Fedor Abominável", "Sempre que um nuppeppo é atingido por uma arma cortante ou perfurante, ele libera um fedor imundo e pútrido. Todas as pessoas vivas a menos seis metros devem fazer uma rolagem de Vigor (NA 20) para evitar ficarem nauseadas. Todos estes alvos são considerados Fadigados até o nuppeppo ser destruído ou se moverem para pelo menos seis metros de distância."], ["Medo 3", ""], ["Morto-Vivo", ""]], "nota": ""}, {"id": "idi_pennaggolan", "n": "Pennaggolan", "tipo": "morto", "fonte": "IdI p. 273", "an": [3, 3, 3, 3], "tr": "Reflexos 4, Vigor 4, Agilidade 4, Percepção 4", "ini": "5k4", "atq": [["Mordida", "4k4", "C", "2k2"], ["Entranhas  . Um pennaggolan pode usar es", "9k4", "C", "—"]], "tn": 25, "red": 15, "fer": [[72, null]], "per": "Atuação 4, Jiujutsu 5, Sinceridade (Ardil) 5, Furtividade 5, e quaisquer perícias conhecidas em vida.", "hab": [["Mácula Ilusória", "A Mácula de um pennaggolan só pode ser detectada quando sua cabeça está solta de seu corpo. Enquanto sua cabeça está conectada, jade não o queimará e outros feitiços ou efeitos detectores de Mácula não o afetarão."], ["Constrição de Entranhas", "Um pennaggolan usa sua perícia Jiujutsu para atacar com suas entranhas, tentando imobilizar seu alvo e então agarrar e estrangular a vítima até a morte."], ["Medo 3", ""], ["Veloz 2 (apenas com a cabeça solta)", ""], ["Cabeça Voadora", "Um pennaggolan pode soltar e religar sua cabeça a qualquer momento, mas deve reconectar sua cabeça antes do próximo nascer do sol. it Isto é uma Ação Simples. Enquanto estiver solta, a cabeça pode levitar e voar em qualquer direção. Se não puder retornar ao seu corpo até o próximo nascer do sol, ela cairá no chão paralisada e indefesa."], ["Invulnerável", ""], ["Morto-Vivo", ""], ["Corpo Vulnerável", "Enquanto a cabeça de um pennaggolan está solta, seu corpo não é Invulnerável."]], "nota": ""}, {"id": "idi_zumbi_da_praga", "n": "Zumbi da Praga", "tipo": "morto", "fonte": "IdI p. 273", "an": [0, 3, 0, 1], "tr": "", "ini": "1k1", "atq": [["Punho", "4k2", "C", "3k1"], ["Clava", "4k2", "C", "—"]], "tn": 10, "red": 5, "fer": [[72, null]], "per": "", "hab": [["Decapitação", "Um zumbi normalmente pode ser destruído dilacerando-o (reduzindo-o a Morto). Porém, ele também pode ser destruído instantaneamente arrancando sua cabeça. Isto requer os Incrementos necessários para um Golpe Preciso e causar pelo menos 18 Ferimentos."], ["Medo 3 adoaThadeuHudsonEm", ""], ["Vetor da Praga", "Qualquer um atingido por um zumbi da praga tem uma chance em 5 de pegar uma doença amplificada pela Mácula. Uma doença dessas tipicamente causará enfraquecimento, surtos de tosse"]], "nota": "Estas entidades são muito similares a zumbis comuns em natureza e aparência, mas são vetores ativos da doença que os matou. Em alguns casos a doença em si pode ser de natureza sobrenatural, mas zumbis da praga também podem ocorrer quando um corpo morre perto da Mácula."}, {"id": "idi_gakimushi", "n": "Gakimushi", "tipo": "morto", "fonte": "IdI p. 274", "an": [2, 5, 3, 3], "tr": "Reflexos 4, Vigor 4, Agilidade 5, Força 5", "ini": "6k4", "atq": [["Ferrão", "6k6", "C", "5k3"]], "tn": 25, "red": 10, "fer": [[25, 5], [60, 10], [95, null]], "per": "Furtividade 3", "hab": [["Medo 4", ""], ["Ferrão Venenoso", "Aqueles que são atingidos pelo ferrão do Gakimushi são inoculados com um temível veneno paralisante que reduz sua Força em 1 Nível por acerto. Vítimas cuja Força chegue a 0 ficam paralisadas até que o efeito do veneno cesse (o que requer 1 hora por dose, cumulativas) ou seja tratado com sucesso com um feitiço. Um teste da Perícia Medicina contra NA 25 pode reduzir a duração do veneno pela metade."], ["Metamorfose", "Um gakimushi pode assumir a forma de um inseto normal como Ação Complexa. Recuperar sua forma verdadeira é uma Ação Simples."]], "nota": "Os mais malignos dos gakis conhecidos pelos mortais, Gakimushis são entidades intensamente Maculadas que parecem usufruir dos poderes do Jigoku e de seu Gaki-dô nativo. Eles se alimentam de dor, e como tal, seu comportamento predileto é raptar mortais e torturá-los por dias, semanas ou até mesmo mes"}, {"id": "idi_gaki_kwaku_shin_gaki", "n": "Gaki, Kwaku-shin Gaki", "tipo": "morto", "fonte": "IdI p. 275", "an": [2, 3, 3, 2], "tr": "Reflexos 3, Vigor 5, Agilidade 4, Força 4", "ini": "4k3", "atq": [["Corpo", "6k4", "C", "4k3"]], "tn": 20, "red": 5, "fer": [[32, 5], [64, 10], [96, null]], "per": "", "hab": [["Barriga de Caldeirão", "O Kwaku-shin gaki pode vomitar uma golfada de chamas uma vez por luta. O ataque dessa golfada de fogo ardente é feito com 6k3, e pode atingir até três alvos que estejam a menos de 3 m um do outro. Ele causa 4k4 de dano e colocará fogo em objetos inflamáveis."], ["Medo 3", ""], ["Natureza Ígnea", "Devido ao intenso calor que contêm, Kwaku-shin Gakis são imunes a todo fogo e calor, sejam normais ou mágicos em natureza. Porém, água e frio lhes causam dor — um balde de água causará 1k1 de dano em um Kwaku-shin Gaku (ignorando Redução), e quantidades maiores infligirão dano proporcionalmente maior."]], "nota": "Estes bizarros gakis são criados a partir das almas daqueles que permitem que outros morram de frio em vez de compartilhar o calor que possuem. Eles são bem raros, com tipicamente apenas um ou dois a cada geração."}, {"id": "idi_shikko_gaki", "n": "Shikko-gaki", "tipo": "morto", "fonte": "IdI p. 275", "an": [2, 3, 3, 2], "tr": "Reflexos 3, Vigor 5, Agilidade 3, Força 4", "ini": "5k3", "atq": [["Garras", "4k2", "S", "4k2"]], "tn": 20, "red": 5, "fer": [[32, 5], [64, null]], "per": "", "hab": [["Toque Infecto", "As garras imundas de um Shikko-gaki carregam doenças, e os atingidos por elas devem fazer um teste de Vigor contra o número de Ferimentos causados ou adoecer com uma séria infecção febril. A doença faz com que Vigor e Força caiam em 1 Nível; ao fim de uma semana, a vítima deve fazer um teste de Vigor contra NA 20 para se recuperar, ou a doença ita"]], "nota": "Shikko-gakis são criados de almas desprovidas de túmulos ou outros locais de repouso dos mortos honrados. Este blasfemo pecado os condena a uma existência como um gaki que anseia por carne de mortais falecidos."}, {"id": "idi_gaki_mare_de_caveiras", "n": "Gaki Maré de Caveiras", "tipo": "morto", "fonte": "IdI p. 276", "an": [1, 1, 3, 3], "tr": "Reflexos 3, Vigor 5, Força 6", "ini": "3k3", "atq": [["Mordida", "8k4", "S", "6k3"]], "tn": 20, "red": 5, "fer": [[25, 5], [50, 10], [75, 15], [100, null]], "per": "", "hab": [["Ligado à Água", "A Maré de Caveiras não pode deixar a água."], ["Medo 5 (O efeito de Medo da Maré de Caveiras é criado no mom", ""]], "nota": "Por séculos de navegação, incontáveis marinheiros traíram seus capitães e tripulação por riquezas. Esses assassinos e ladrões, obcecados com o aumento de seus próprios cofres, estão condenados a renascer na Maré de Caveiras, um gigantesco gaki corrompido que reside nas águas Maculadas perto da costa"}, {"id": "idi_espiritos_assassinos", "n": "Espíritos Assassinos", "tipo": "morto", "fonte": "IdI p. 277", "an": [1, 1, 1, 2], "tr": "", "ini": "5k4", "atq": [["Arma", "8k4", "C", "De acordo com a"]], "tn": 25, "red": 0, "fer": [[30, 5], [60, 10], [90, null]], "per": "Perícia de Arma apropriada (mesma que em vida, normalmente Kenjutsu) 4, Esportes 4, Jiujutsu (Arma Improvisada) 4", "hab": [["Veloz 3", ""], ["Invulnerabilidade Parcial", "Espíritos assassinos são imunes a todos os feitiços, perícias e técnicas que afetam sua mente e pensamentos. Eles podem, porém, ter os sentidos enganados por ilusões."], ["Agressão Incessante", "Espíritos assassinos não podem usar posturas de combate exceto Ataque e Ataque Total."], ["Espírito ita", ""]], "nota": "A vida de um samurai é guerrear e o caminho do samurai é a morte. Estas são filosofias comumente aceitas em Rokugan, mas mesmo numa cultura tão marcial, alguns samurais passam do limite e abraçam a violência e a batalha por prazer, venerando a matança e destruição."}, {"id": "idi_fu_leng", "n": "Fu Leng", "tipo": "oni", "fonte": "IdI p. 277", "an": [4, 8, 5, 5], "tr": "", "ini": "10k6", "atq": [["Garras", "10k5", "C", "7k2"], ["arma", "10k5", "C", "de"]], "tn": 40, "red": 13, "fer": [[172, null]], "per": "Defesa 5, Caça 7, Intimidação (Provocação) 8, Jiujutsu 6, Kenjutsu 5, Lanças 5 Vantagens: c Exemplar Negro (Determinação) c Rápido c Toque do Jigoku Poderes das Terras Sombrias: c Acima dos Elementos ", "hab": [["Medo 6", ""], ["Invulnerável", ""], ["Morto-Vivo doaThadeuHudsonEm Kitsune Gohei, senhor do Clã Me", ""]], "nota": ""}, {"id": "idi_fatina_lorde_ghul", "n": "Fatina, Lorde Ghul", "tipo": "morto", "fonte": "IdI p. 278", "an": [4, 5, 3, 2], "tr": "Agilidade 4, Força 4", "ini": "5k4", "atq": [["Garras", "6k3", "C", "4k2"]], "tn": 25, "red": 5, "fer": [[92, null]], "per": "", "hab": [["Medo 3", ""], ["Poder dos Sahir", "Fatina conhece as artes de magia das Areias Ardentes. Em termos mecânicos, ela pode ser considerada um shugenja Chuda de Nível 3, mas por empregar magia estranha de uma terra estrangeira, ela não precisa derramar sangue para invocar feitiços de maho. Sua seleção de feitiços é vasta e esotérica, e seria melhor deixá-la ao critério do Mestre"], ["Morta-Viva Quando os ghuls das Areias Ardentes começaram a a", ""]], "nota": ""}, {"id": "idi_yogo_junzo_feiticeiro_morto_vivo", "n": "Yogo Junzo, Feiticeiro Morto-vivo", "tipo": "morto", "fonte": "IdI p. 279", "an": [7, 5, 3, 4], "tr": "Vigor 4, Inteligência 5", "ini": "10k8", "atq": [["Garras", "5k3", "C", "4k1"]], "tn": 40, "red": 10, "fer": [[95, null]], "per": "Caligrafia 5, Corte 3, Etiqueta 4, Kenjutsu 3, Conhecimento: História 4, Conhecimento: Maho 5, Conhecimento: Clã Escorpião 6, Meditação 4, Feitiçaria 8, Furtividade 3 Feitiços: Junzo tem um vasto conj", "hab": [["Medo 5", ""], ["Morto-Vivo Yogo Junzo foi o daimyo da família Yogo do Clã Es", ""]], "nota": ""}];
